#requires -Version 5.1

# English source of truth: data/i18n/en.json. Generated locales are overlaid
# at startup. Callers use Get-WinToolText / Get-WinToolCountText.

$script:WinToolShippedLanguages = @(
    "en", "pt-BR", "es", "fr", "de", "it", "ja", "ko",
    "zh-Hans", "zh-Hant", "pl", "nl", "ru", "tr"
)


# Display-language tags that should resolve to a shipped locale before the
# generic parent walk (zh-CN is not a parent of zh-Hans).
$script:WinToolCultureAliases = @{
    "zh-CN" = "zh-Hans"
    "zh-SG" = "zh-Hans"
    "zh-Hans-CN" = "zh-Hans"
    "zh-TW" = "zh-Hant"
    "zh-HK" = "zh-Hant"
    "zh-MO" = "zh-Hant"
    "zh-Hant-TW" = "zh-Hant"
    "pt-PT" = "pt-BR"
    "pt"    = "pt-BR"
}

function Get-WinToolPreferencePath {
    if (-not [string]::IsNullOrWhiteSpace($script:WinToolPreferencesPath)) {
        return $script:WinToolPreferencesPath
    }
    if ([string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        return $null
    }
    return (Join-Path $env:LOCALAPPDATA "WinTool\preferences.json")
}

function Get-WinToolPreference {
    $path = Get-WinToolPreferencePath
    $prefs = [pscustomobject]@{
        schemaVersion = 1
        language = "auto"
        modernHostOfferDismissed = $false
    }
    if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path)) {
        return $prefs
    }
    try {
        $loaded = ConvertFrom-WinToolJsonText -Text ([System.IO.File]::ReadAllText($path))
        $language = [string](Get-WinToolNote -Object $loaded -Name "language" -Default "auto")
        if ([string]::IsNullOrWhiteSpace($language)) {
            $language = "auto"
        }
        $prefs.language = $language
        $dismissed = Get-WinToolNote -Object $loaded -Name "modernHostOfferDismissed" -Default $false
        $prefs.modernHostOfferDismissed = [bool]($dismissed -eq $true -or [string]$dismissed -eq "True" -or [string]$dismissed -eq "1")
    }
    catch {
        $null = $_.Exception.Message
    }
    return $prefs
}

function Save-WinToolPreference {
    param(
        [Parameter(Mandatory = $true)]$Preferences
    )
    $path = Get-WinToolPreferencePath
    if ([string]::IsNullOrWhiteSpace($path)) {
        return
    }
    $directory = Split-Path -Parent $path
    if (-not (Test-Path -LiteralPath $directory)) {
        New-Item -ItemType Directory -Path $directory -Force | Out-Null
    }
    $dismissed = Get-WinToolNote -Object $Preferences -Name "modernHostOfferDismissed" -Default $false
    $payload = [pscustomobject]@{
        schemaVersion = 1
        language = [string](Get-WinToolNote -Object $Preferences -Name "language" -Default "auto")
        modernHostOfferDismissed = [bool]($dismissed -eq $true -or [string]$dismissed -eq "True" -or [string]$dismissed -eq "1")
    }
    Write-WinToolJsonFile -Path $path -Value $payload
}

function Test-WinToolLocaleAvailable {
    param([Parameter(Mandatory = $true)][string]$Code)
    if ($Code -eq "en") {
        return $true
    }
    $embedded = $script:WinToolEmbedded
    $key = "Locales:" + $Code
    if ($null -ne $embedded -and $embedded.ContainsKey($key)) {
        return $true
    }
    if ([string]::IsNullOrWhiteSpace($script:WinToolRoot)) {
        return $false
    }
    $generated = Join-Path $script:WinToolRoot ("data/i18n/generated/" + $Code + ".json")
    $override = Join-Path $script:WinToolRoot ("data/i18n/overrides/" + $Code + ".json")
    return (Test-Path -LiteralPath $generated) -or (Test-Path -LiteralPath $override)
}

function Read-WinToolLocaleObject {
    param([Parameter(Mandatory = $true)][string]$Code)
    $embedded = $script:WinToolEmbedded
    $key = "Locales:" + $Code
    if ($null -ne $embedded -and $embedded.ContainsKey($key)) {
        return (ConvertFrom-WinToolJsonText -Text (Get-WinToolPayloadText -Name $key))
    }

    if ([string]::IsNullOrWhiteSpace($script:WinToolRoot)) {
        if ($Code -eq "en") {
            throw "WinTool locale files are not embedded and no source folder is set."
        }
        return $null
    }

    $root = Join-Path $script:WinToolRoot "data/i18n"
    if ($Code -eq "en") {
        $enPath = Join-Path $root "en.json"
        return (ConvertFrom-WinToolJsonText -Text ([System.IO.File]::ReadAllText($enPath)))
    }

    $table = [ordered]@{}
    $generated = Join-Path $root ("generated/" + $Code + ".json")
    if (Test-Path -LiteralPath $generated) {
        $loaded = ConvertFrom-WinToolJsonText -Text ([System.IO.File]::ReadAllText($generated))
        foreach ($property in $loaded.PSObject.Properties) {
            $table[$property.Name] = [string]$property.Value
        }
    }
    $override = Join-Path $root ("overrides/" + $Code + ".json")
    if (Test-Path -LiteralPath $override) {
        $loaded = ConvertFrom-WinToolJsonText -Text ([System.IO.File]::ReadAllText($override))
        foreach ($property in $loaded.PSObject.Properties) {
            $table[$property.Name] = [string]$property.Value
        }
    }
    if ($table.Count -eq 0) {
        return $null
    }
    return [pscustomobject]$table
}

function ConvertTo-WinToolTextMap {
    param($Source)
    $map = New-Object "System.Collections.Generic.Dictionary[string,string]" ([StringComparer]::Ordinal)
    if ($null -eq $Source) {
        return $map
    }
    if ($Source -is [System.Collections.IDictionary]) {
        foreach ($key in @($Source.Keys)) {
            $map[[string]$key] = [string]$Source[$key]
        }
        return $map
    }
    foreach ($property in $Source.PSObject.Properties) {
        $map[[string]$property.Name] = [string]$property.Value
    }
    return $map
}

function Get-WinToolLocaleTable {
    param([Parameter(Mandatory = $true)][string]$Code)
    if ($null -eq $script:WinToolLocaleTables) {
        $script:WinToolLocaleTables = @{}
    }
    if ($script:WinToolLocaleTables.ContainsKey($Code)) {
        return $script:WinToolLocaleTables[$Code]
    }
    $loaded = Read-WinToolLocaleObject -Code $Code
    if ($null -ne $loaded) {
        $script:WinToolLocaleTables[$Code] = $loaded
    }
    return $loaded
}

function Get-WinToolAvailableLanguage {
    $codes = New-Object System.Collections.Generic.List[string]
    $codes.Add("en") | Out-Null
    foreach ($code in @($script:WinToolShippedLanguages)) {
        if ($code -eq "en") { continue }
        if (Test-WinToolLocaleAvailable -Code $code) {
            $codes.Add($code) | Out-Null
        }
    }
    return $codes.ToArray()
}

function ConvertTo-WinToolShippedLanguage {
    param([string]$Tag)
    if ([string]::IsNullOrWhiteSpace($Tag)) {
        return $null
    }
    $available = @{}
    foreach ($code in @(Get-WinToolAvailableLanguage)) {
        $available[$code] = $true
    }
    $current = $Tag.Trim()
    $seen = @{}
    while (-not [string]::IsNullOrWhiteSpace($current) -and -not $seen.ContainsKey($current)) {
        $seen[$current] = $true
        if ($script:WinToolCultureAliases.ContainsKey($current) -and $available.ContainsKey($script:WinToolCultureAliases[$current])) {
            return $script:WinToolCultureAliases[$current]
        }
        if ($available.ContainsKey($current)) {
            return $current
        }
        $dash = $current.LastIndexOf("-")
        if ($dash -le 0) {
            # Same language, different region: pt-PT already tried pt, then pt-BR via alias.
            foreach ($code in @($available.Keys)) {
                if ($code.Equals($current, [StringComparison]::OrdinalIgnoreCase) -or $code.StartsWith($current + "-", [StringComparison]::OrdinalIgnoreCase)) {
                    return $code
                }
            }
            break
        }
        $current = $current.Substring(0, $dash)
    }
    return $null
}

function Resolve-WinToolLanguage {
    param(
        [string]$Requested,
        [string]$UiCulture,
        [string[]]$PreferredLanguages
    )
    $available = @(Get-WinToolAvailableLanguage)
    if (-not [string]::IsNullOrWhiteSpace($Requested) -and $Requested -ne "auto") {
        $direct = ConvertTo-WinToolShippedLanguage -Tag $Requested
        if (-not [string]::IsNullOrWhiteSpace($direct)) {
            return $direct
        }
    }

    $candidates = New-Object System.Collections.Generic.List[string]
    if (-not [string]::IsNullOrWhiteSpace($UiCulture)) {
        $candidates.Add($UiCulture) | Out-Null
    }
    else {
        try { $candidates.Add([System.Globalization.CultureInfo]::CurrentUICulture.Name) | Out-Null } catch { $null = $_.Exception.Message }
    }
    if ($null -ne $PreferredLanguages) {
        foreach ($item in @($PreferredLanguages)) {
            if (-not [string]::IsNullOrWhiteSpace($item)) {
                $candidates.Add($item) | Out-Null
            }
        }
    }
    else {
        try {
            if (Get-Command -Name Get-WinUserLanguageList -ErrorAction SilentlyContinue) {
                foreach ($item in @(Get-WinUserLanguageList)) {
                    $name = [string]$item.LanguageTag
                    if (-not [string]::IsNullOrWhiteSpace($name)) {
                        $candidates.Add($name) | Out-Null
                    }
                }
            }
        }
        catch {
            $null = $_.Exception.Message
        }
    }

    foreach ($tag in $candidates) {
        $matched = ConvertTo-WinToolShippedLanguage -Tag $tag
        if (-not [string]::IsNullOrWhiteSpace($matched)) {
            return $matched
        }
    }
    if ($available -contains "en") {
        return "en"
    }
    return $available[0]
}

function Get-WinToolPluralCategory {
    param(
        [Parameter(Mandatory = $true)][int]$Count,
        [string]$Language
    )
    if ([string]::IsNullOrWhiteSpace($Language)) {
        $Language = [string]$script:WinToolLanguage
    }
    $n = [math]::Abs($Count)
    if ($Language -eq "ru") {
        $mod10 = $n % 10
        $mod100 = $n % 100
        if ($mod10 -eq 1 -and $mod100 -ne 11) { return "one" }
        if ($mod10 -ge 2 -and $mod10 -le 4 -and ($mod100 -lt 12 -or $mod100 -gt 14)) { return "few" }
        return "many"
    }
    if ($n -eq 1) {
        return "one"
    }
    return "other"
}

function Merge-WinToolTextTable {
    param(
        [Parameter(Mandatory = $true)][string]$Language
    )
    $merged = New-Object "System.Collections.Generic.Dictionary[string,string]" ([StringComparer]::Ordinal)
    $english = ConvertTo-WinToolTextMap -Source (Get-WinToolLocaleTable -Code "en")
    foreach ($key in @($english.Keys)) {
        $merged[$key] = $english[$key]
    }
    if ($Language -ne "en") {
        $overlay = ConvertTo-WinToolTextMap -Source (Get-WinToolLocaleTable -Code $Language)
        if ($null -ne $overlay) {
            foreach ($key in @($overlay.Keys)) {
                $value = [string]$overlay[$key]
                if (-not [string]::IsNullOrWhiteSpace($value)) {
                    $merged[$key] = $value
                }
            }
        }
    }
    return $merged
}

function Initialize-WinToolLocale {
    param(
        [string]$Language,
        [string]$UiCulture,
        [string[]]$PreferredLanguages,
        [switch]$Force
    )
    $requested = $Language
    if ([string]::IsNullOrWhiteSpace($requested)) {
        $requested = [string](Get-WinToolNote -Object (Get-WinToolPreference) -Name "language" -Default "auto")
    }
    if ([string]::IsNullOrWhiteSpace($requested)) {
        $requested = "auto"
    }
    $resolved = Resolve-WinToolLanguage -Requested $requested -UiCulture $UiCulture -PreferredLanguages $PreferredLanguages
    if (-not $Force -and $script:WinToolLocaleReady -eq $true -and $script:WinToolLanguage -eq $resolved -and $script:WinToolLanguagePreference -eq $requested) {
        return $resolved
    }

    $script:WinToolLanguagePreference = $requested
    $script:WinToolLanguage = $resolved
    $localeStamp = Get-Date
    $script:WinToolText = Merge-WinToolTextTable -Language $resolved
    $script:WinToolEnglishText = Merge-WinToolTextTable -Language "en"
    $script:WinToolLocaleReady = $true
    if (Get-Command -Name Write-WinToolStartupMark -ErrorAction SilentlyContinue) {
        Write-WinToolStartupMark -Name "localeInit" -Started $localeStamp
    }
    if ($null -ne $script:WinToolPayloadObject) {
        $script:WinToolPayloadObject = @{}
    }
    return $resolved
}

function Test-WinToolTextKey {
    param([Parameter(Mandatory = $true)][string]$Key)
    if ($null -eq $script:WinToolText) {
        return $false
    }
    return $script:WinToolText.ContainsKey($Key)
}

function Get-WinToolText {
    param(
        [Parameter(Mandatory = $true)][string]$Key,
        [Parameter(ValueFromRemainingArguments = $true)][object[]]$Format
    )
    if ($script:WinToolLocaleReady -ne $true) {
        Initialize-WinToolLocale | Out-Null
    }
    $text = $null
    if ($null -ne $script:WinToolText -and $script:WinToolText.ContainsKey($Key)) {
        $text = [string]$script:WinToolText[$Key]
    }
    elseif ($null -ne $script:WinToolEnglishText -and $script:WinToolEnglishText.ContainsKey($Key)) {
        $text = [string]$script:WinToolEnglishText[$Key]
    }
    if ([string]::IsNullOrEmpty($text)) {
        return $Key
    }
    $values = @($Format | Where-Object { $null -ne $_ })
    if ($values.Count -gt 0) {
        try {
            return ($text -f $values)
        }
        catch {
            return $text
        }
    }
    return $text
}

function Get-WinToolCountText {
    param(
        [Parameter(Mandatory = $true)][string]$Key,
        [Parameter(Mandatory = $true)][int]$Count,
        [Parameter(ValueFromRemainingArguments = $true)][object[]]$Format
    )
    $extra = @()
    if ($null -ne $Format) {
        $extra = @($Format)
    }
    $category = Get-WinToolPluralCategory -Count $Count
    $suffixes = @()
    if ($category -eq "one") {
        $suffixes = @(".one")
    }
    elseif ($category -eq "few") {
        $suffixes = @(".few", ".many", ".other")
    }
    elseif ($category -eq "many") {
        $suffixes = @(".many", ".other")
    }
    else {
        $suffixes = @(".many", ".other")
    }
    $chosen = $null
    foreach ($suffix in $suffixes) {
        $candidate = $Key + $suffix
        if (Test-WinToolTextKey -Key $candidate) {
            $chosen = $candidate
            break
        }
        if ($null -ne $script:WinToolEnglishText -and $script:WinToolEnglishText.ContainsKey($candidate)) {
            $chosen = $candidate
            break
        }
    }
    if ([string]::IsNullOrWhiteSpace($chosen)) {
        $chosen = $Key + ".many"
    }
    if ($category -eq "one" -and $extra.Count -gt 0) {
        return (Get-WinToolText -Key $chosen -Format $extra)
    }
    if ($category -eq "one") {
        return (Get-WinToolText -Key $chosen)
    }
    $values = @($Count) + $extra
    return (Get-WinToolText -Key $chosen -Format $values)
}

function Set-WinToolXamlText {
    param($Root)
    if ($null -eq $Root) {
        $Root = $script:WinToolWindow
    }
    if ($null -eq $Root) {
        return
    }
    if ($script:WinToolLocaleReady -ne $true) {
        Initialize-WinToolLocale | Out-Null
    }

    $visit = New-Object System.Collections.Generic.Queue[object]
    $visit.Enqueue($Root)
    $seen = New-Object System.Collections.Generic.HashSet[int]
    while ($visit.Count -gt 0) {
        $node = $visit.Dequeue()
        if ($null -eq $node) { continue }
        try {
            $hash = [int]$node.GetHashCode()
            if (-not $seen.Add($hash)) { continue }
        }
        catch {
            $null = $_.Exception.Message
        }

        $ids = New-Object System.Collections.Generic.List[string]
        try {
            $uid = [string]$node.Uid
            if (-not [string]::IsNullOrWhiteSpace($uid)) { $ids.Add($uid) | Out-Null }
        }
        catch { $null = $_.Exception.Message }
        try {
            $elementName = [string]$node.Name
            if (-not [string]::IsNullOrWhiteSpace($elementName) -and -not $ids.Contains($elementName)) {
                $ids.Add($elementName) | Out-Null
            }
        }
        catch { $null = $_.Exception.Message }

        foreach ($id in $ids) {
            foreach ($pair in @(
                    @{ Key = "ui.$id.Text"; Property = "Text" },
                    @{ Key = "ui.$id.Content"; Property = "Content" },
                    @{ Key = "ui.$id.Title"; Property = "Title" },
                    @{ Key = "ui.$id.ToolTip"; Property = "ToolTip" },
                    @{ Key = "ui.$id.Header"; Property = "Header" }
                )) {
                if (-not (Test-WinToolTextKey -Key $pair.Key) -and -not ($null -ne $script:WinToolEnglishText -and $script:WinToolEnglishText.ContainsKey($pair.Key))) {
                    continue
                }
                $value = Get-WinToolText -Key $pair.Key
                try {
                    if ($pair.Property -eq "Content") {
                        $current = $node.Content
                        if ($current -is [string] -or $null -eq $current) {
                            $node.Content = $value
                        }
                    }
                    elseif ($pair.Property -eq "ToolTip") {
                        $tip = $node.ToolTip
                        if ($tip -is [string] -or $null -eq $tip) {
                            $node.ToolTip = $value
                        }
                        elseif ($null -ne $tip.PSObject.Properties["Content"] -and $tip.Content -is [string]) {
                            $tip.Content = $value
                        }
                    }
                    else {
                        $node.($pair.Property) = $value
                    }
                }
                catch {
                    $null = $_.Exception.Message
                }
            }
            $autoKey = "ui.$id.AutomationName"
            if ((Test-WinToolTextKey -Key $autoKey) -or ($null -ne $script:WinToolEnglishText -and $script:WinToolEnglishText.ContainsKey($autoKey))) {
                try {
                    [System.Windows.Automation.AutomationProperties]::SetName($node, (Get-WinToolText -Key $autoKey))
                }
                catch {
                    $null = $_.Exception.Message
                }
            }
        }

        try {
            foreach ($child in [System.Windows.LogicalTreeHelper]::GetChildren($node)) {
                if ($child -is [System.Windows.DependencyObject]) {
                    $visit.Enqueue($child)
                }
            }
        }
        catch {
            $null = $_.Exception.Message
        }
    }
}

function Set-WinToolCatalogLocale {
    param($Catalog, [Parameter(Mandatory = $true)][string]$Kind)
    if ($null -eq $Catalog) {
        return $Catalog
    }
    $set = {
        param($Object, $Name, $Key)
        if ($null -eq $Object) { return }
        if (-not (Test-WinToolTextKey -Key $Key) -and -not ($null -ne $script:WinToolEnglishText -and $script:WinToolEnglishText.ContainsKey($Key))) {
            return
        }
        $property = $Object.PSObject.Properties[$Name]
        if ($null -eq $property) {
            return
        }
        $property.Value = Get-WinToolText -Key $Key
    }
    switch ($Kind) {
        "Apps" {
            foreach ($category in @(Get-WinToolNote -Object $Catalog -Name "categories" -Default @())) {
                $cid = [string](Get-WinToolNote -Object $category -Name "id" -Default "")
                & $set $category "name" "catalog.apps.category.$cid.name"
                & $set $category "chip" "catalog.apps.category.$cid.chip"
                & $set $category "description" "catalog.apps.category.$cid.description"
                foreach ($app in @(Get-WinToolNote -Object $category -Name "apps" -Default @())) {
                    $aid = [string](Get-WinToolNote -Object $app -Name "id" -Default "")
                    & $set $app "description" "catalog.apps.$aid.description"
                }
            }
        }
        "Tweaks" {
            foreach ($preset in @(Get-WinToolNote -Object $Catalog -Name "presets" -Default @())) {
                $presetId = [string](Get-WinToolNote -Object $preset -Name "id" -Default "")
                & $set $preset "name" "catalog.tweaks.preset.$presetId.name"
                & $set $preset "description" "catalog.tweaks.preset.$presetId.description"
            }
            foreach ($tweak in @(Get-WinToolNote -Object $Catalog -Name "tweaks" -Default @())) {
                $tid = [string](Get-WinToolNote -Object $tweak -Name "id" -Default "")
                & $set $tweak "name" "catalog.tweaks.$tid.name"
                & $set $tweak "description" "catalog.tweaks.$tid.description"
                $category = [string](Get-WinToolNote -Object $tweak -Name "category" -Default "")
                if (-not [string]::IsNullOrWhiteSpace($category)) {
                    $slug = ($category.ToLowerInvariant() -replace '[^a-z0-9]+', '-').Trim("-")
                    $key = "catalog.tweaks.category.$slug"
                    if ((Test-WinToolTextKey -Key $key) -or ($null -ne $script:WinToolEnglishText -and $script:WinToolEnglishText.ContainsKey($key))) {
                        $tweak.category = Get-WinToolText -Key $key
                    }
                }
            }
        }
        "Terminal" {
            foreach ($prompt in @(Get-WinToolNote -Object $Catalog -Name "prompts" -Default @())) {
                $promptId = [string](Get-WinToolNote -Object $prompt -Name "id" -Default "")
                & $set $prompt "summary" "catalog.terminal.prompt.$promptId.summary"
            }
            foreach ($extra in @(Get-WinToolNote -Object $Catalog -Name "extras" -Default @())) {
                $eid = [string](Get-WinToolNote -Object $extra -Name "id" -Default "")
                & $set $extra "name" "catalog.terminal.extra.$eid.name"
                & $set $extra "description" "catalog.terminal.extra.$eid.description"
            }
            foreach ($scheme in @(Get-WinToolNote -Object $Catalog -Name "schemes" -Default @())) {
                $sid = [string](Get-WinToolNote -Object $scheme -Name "id" -Default "")
                & $set $scheme "name" "catalog.terminal.scheme.$sid.name"
            }
            foreach ($preset in @(Get-WinToolNote -Object $Catalog -Name "starshipPresets" -Default @())) {
                $sid = [string](Get-WinToolNote -Object $preset -Name "id" -Default "")
                & $set $preset "name" "catalog.terminal.starship.$sid.name"
            }
            $variants = Get-WinToolNote -Object $Catalog -Name "promptVariants" -Default $null
            if ($null -ne $variants) {
                foreach ($engineProp in $variants.PSObject.Properties) {
                    foreach ($variant in @($engineProp.Value)) {
                        $vid = [string](Get-WinToolNote -Object $variant -Name "id" -Default "")
                        & $set $variant "name" ("catalog.terminal.variant.{0}.{1}.name" -f $engineProp.Name, $vid)
                        & $set $variant "description" ("catalog.terminal.variant.{0}.{1}.description" -f $engineProp.Name, $vid)
                    }
                }
            }
        }
        "Updates" {
            foreach ($mode in @(Get-WinToolNote -Object $Catalog -Name "modes" -Default @())) {
                $mid = [string](Get-WinToolNote -Object $mode -Name "id" -Default "")
                & $set $mode "name" "catalog.updates.mode.$mid.name"
                & $set $mode "description" "catalog.updates.mode.$mid.description"
            }
            foreach ($vendor in @(Get-WinToolNote -Object $Catalog -Name "vendors" -Default @())) {
                $vid = [string](Get-WinToolNote -Object $vendor -Name "id" -Default "")
                & $set $vendor "note" "catalog.updates.vendor.$vid.note"
            }
        }
        "Features" {
            foreach ($item in @(Get-WinToolNote -Object $Catalog -Name "features" -Default @())) {
                $fid = [string](Get-WinToolNote -Object $item -Name "id" -Default "")
                & $set $item "description" "catalog.features.$fid.description"
            }
        }
        "Fixes" {
            foreach ($item in @(Get-WinToolNote -Object $Catalog -Name "fixes" -Default @())) {
                $fid = [string](Get-WinToolNote -Object $item -Name "id" -Default "")
                & $set $item "name" "catalog.fixes.$fid.name"
                & $set $item "description" "catalog.fixes.$fid.description"
                $index = 0
                foreach ($step in @(Get-WinToolNote -Object $item -Name "steps" -Default @())) {
                    & $set $step "label" "catalog.fixes.$fid.step.$index"
                    $index += 1
                }
            }
        }
        "System" {
            foreach ($dns in @(Get-WinToolNote -Object $Catalog -Name "dns" -Default @())) {
                $did = [string](Get-WinToolNote -Object $dns -Name "id" -Default "")
                & $set $dns "name" "catalog.system.dns.$did.name"
                & $set $dns "description" "catalog.system.dns.$did.description"
            }
            $plan = Get-WinToolNote -Object $Catalog -Name "powerPlan" -Default $null
            if ($null -ne $plan) {
                & $set $plan "name" "catalog.system.powerPlan.name"
                & $set $plan "description" "catalog.system.powerPlan.description"
            }
        }
        "Drivers" {
            foreach ($gpu in @(Get-WinToolNote -Object $Catalog -Name "gpuApps" -Default @())) {
                $gid = [string](Get-WinToolNote -Object $gpu -Name "id" -Default "")
                & $set $gpu "note" "catalog.drivers.gpu.$gid.note"
            }
            foreach ($problem in @(Get-WinToolNote -Object $Catalog -Name "problem" -Default @())) {
                $code = [string](Get-WinToolNote -Object $problem -Name "code" -Default "")
                & $set $problem "name" "catalog.drivers.problem.$code.name"
            }
        }
    }
    return $Catalog
}

function Test-WinToolTextTable {
    param($Errors)
    if ($null -eq $Errors) {
        $Errors = New-Object System.Collections.Generic.List[string]
    }
    if ($script:WinToolLocaleReady -ne $true) {
        Initialize-WinToolLocale -Language "en" | Out-Null
    }
    if ($null -eq $script:WinToolEnglishText -or $script:WinToolEnglishText.Count -eq 0) {
        Add-WinToolDataError -Errors $Errors -Message "The English UI text table is empty."
        return $Errors
    }
    foreach ($key in @($script:WinToolEnglishText.Keys)) {
        $value = [string]$script:WinToolEnglishText[$key]
        if ([string]::IsNullOrWhiteSpace($value)) {
            Add-WinToolDataError -Errors $Errors -Message ("UI text '" + $key + "' is empty.")
        }
    }
    $previous = $script:WinToolLanguage
    $previousPref = $script:WinToolLanguagePreference
    $previousTable = $script:WinToolText
    try {
        $script:WinToolLanguage = "en"
        $script:WinToolText = $script:WinToolEnglishText
        $sample = Get-WinToolText "activity.count.warning.many" 3
        if ($sample -ne "3 warnings") {
            Add-WinToolDataError -Errors $Errors -Message "Get-WinToolText did not format a known English string."
        }
    }
    finally {
        $script:WinToolLanguage = $previous
        $script:WinToolLanguagePreference = $previousPref
        $script:WinToolText = $previousTable
    }
    return $Errors
}

Initialize-WinToolLocale | Out-Null
# endregion

# region src/Private/Activity.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT
#requires -Version 5.1

$script:WinToolHasActivity = $true

function Initialize-WinToolActivityState {
    if ($null -eq $script:WinToolState) {
        $script:WinToolState = @{}
    }
    if ($null -eq $script:WinToolState.ActivityRuns) {
        $script:WinToolState.ActivityRuns = New-Object System.Collections.Generic.List[object]
    }
    if ($null -eq $script:WinToolState["ActivityCurrent"]) {
        $script:WinToolState.ActivityCurrent = $null
    }
    if ($null -eq $script:WinToolState["ActivityFilter"]) {
        $script:WinToolState.ActivityFilter = "all"
    }
    if ($null -eq $script:WinToolState["ActivityExpanded"]) {
        $script:WinToolState.ActivityExpanded = $false
    }
    if ($null -eq $script:WinToolState["ActivityPinned"]) {
        $script:WinToolState.ActivityPinned = $false
    }
    if ($null -eq $script:WinToolState["ActivityBadge"]) {
        $script:WinToolState.ActivityBadge = 0
    }
}

function New-WinToolActivityRun {
    param(
        [Parameter(Mandatory = $true)][string]$Title
    )
    $started = [datetime]::Now
    return [pscustomobject]@{
        Id        = [guid]::NewGuid().ToString("N")
        Title     = $Title
        Started   = $started
        Ended     = $null
        Status    = "running"
        Summary   = ""
        Steps     = New-Object System.Collections.Generic.List[object]
        Completed = 0
        Warnings  = 0
        Errors    = 0
        Skipped   = 0
    }
}

function Start-WinToolActivity {
    param(
        [Parameter(Mandatory = $true)][string]$Title
    )
    Initialize-WinToolActivityState
    if ($null -ne $script:WinToolState.ActivityCurrent) {
        Complete-WinToolActivity
    }
    $run = New-WinToolActivityRun -Title $Title
    $script:WinToolState.ActivityRuns.Insert(0, $run)
    $script:WinToolState.ActivityCurrent = $run
    return $run
}

function Add-WinToolActivityStep {
    param(
        [string]$Status = "ok",
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Message,
        [string]$Detail = ""
    )
    if ([string]::IsNullOrWhiteSpace($Message)) {
        return $null
    }
    Initialize-WinToolActivityState
    $run = $script:WinToolState.ActivityCurrent
    if ($null -eq $run) {
        return $null
    }
    $level = [string]$Status
    if ($level -eq "info") { $level = "ok" }
    if ($level -eq "fail") { $level = "error" }
    if (@("ok", "warn", "error", "skipped", "running") -notcontains $level) {
        $level = "ok"
    }
    $step = [pscustomobject]@{
        Status  = $level
        Message = $Message
        Detail  = $Detail
        Time    = [datetime]::Now
    }
    $run.Steps.Add($step) | Out-Null
    $script:WinToolState.ActivityDirty = $true
    switch ($level) {
        "ok" { $run.Completed = [int]$run.Completed + 1 }
        "warn" { $run.Warnings = [int]$run.Warnings + 1 }
        "error" { $run.Errors = [int]$run.Errors + 1 }
        "skipped" { $run.Skipped = [int]$run.Skipped + 1 }
    }
    return $step
}

function Complete-WinToolActivity {
    param(
        [string]$Summary = "",
        [string]$Status = ""
    )
    Initialize-WinToolActivityState
    $run = $script:WinToolState.ActivityCurrent
    if ($null -eq $run) {
        return $null
    }
    $run.Ended = [datetime]::Now
    if (-not [string]::IsNullOrWhiteSpace($Summary)) {
        $run.Summary = $Summary
    }
    $final = [string]$Status
    if ([string]::IsNullOrWhiteSpace($final)) {
        if ([int]$run.Errors -gt 0) { $final = "error" }
        elseif ([int]$run.Warnings -gt 0) { $final = "warn" }
        else { $final = "ok" }
    }
    if ($final -eq "fail") { $final = "error" }
    $run.Status = $final
    $script:WinToolState.ActivityCurrent = $null
    $script:WinToolState.ActivityBadge = [int]$script:WinToolState.ActivityRuns.Count
    return $run
}

function Get-WinToolActivityRun {
    Initialize-WinToolActivityState
    return @($script:WinToolState.ActivityRuns.ToArray())
}

function Format-WinToolActivityDuration {
    param($Started, $Ended)
    if ($null -eq $Started) { return "" }
    $end = $Ended
    if ($null -eq $end) { $end = [datetime]::Now }
    $span = ([datetime]$end) - ([datetime]$Started)
    if ($span.TotalSeconds -lt 0) { $span = [TimeSpan]::Zero }
    if ($span.TotalHours -ge 1) {
        return (Get-WinToolText "activity.duration.hours" ([int][math]::Floor($span.TotalHours)) $span.Minutes)
    }
    if ($span.TotalMinutes -ge 1) {
        return (Get-WinToolText "activity.duration.minutes" $span.Minutes $span.Seconds)
    }
    return (Get-WinToolText "activity.duration.seconds" ([int][math]::Round($span.TotalSeconds)))
}

function Format-WinToolActivityWhen {
    param($Started)
    if ($null -eq $Started) { return "" }
    $stamp = [datetime]$Started
    $time = $stamp.ToString("h:mm tt", [System.Globalization.CultureInfo]::GetCultureInfo("en-US"))
    if ($stamp.Date -eq [datetime]::Now.Date) {
        return (Get-WinToolText "activity.today" $time)
    }
    $date = $stamp.ToString("d MMM yyyy", [System.Globalization.CultureInfo]::GetCultureInfo("en-US"))
    return (Get-WinToolText "activity.meta" $date $time)
}

function Format-WinToolActivityCount {
    param($Run)
    $parts = New-Object System.Collections.Generic.List[string]
    $parts.Add((Get-WinToolCountText "activity.count.completed" ([int]$Run.Completed))) | Out-Null
    $parts.Add((Get-WinToolCountText "activity.count.warning" ([int]$Run.Warnings))) | Out-Null
    $parts.Add((Get-WinToolCountText "activity.count.error" ([int]$Run.Errors))) | Out-Null
    if ([int]$Run.Skipped -gt 0) {
        $parts.Add((Get-WinToolCountText "activity.count.skipped" ([int]$Run.Skipped))) | Out-Null
    }
    return ($parts.ToArray() -join ", ")
}

function Test-WinToolActivityRunVisible {
    param(
        $Run,
        [string]$Filter = "all"
    )
    if ($null -eq $Run) { return $false }
    switch ([string]$Filter) {
        "warnings" { return ([int]$Run.Warnings -gt 0 -or [int]$Run.Errors -gt 0) }
        "errors" { return ([int]$Run.Errors -gt 0) }
        default { return $true }
    }
}

function Test-WinToolActivityStepVisible {
    param(
        $Step,
        [string]$Filter = "all"
    )
    $status = [string](Get-WinToolNote -Object $Step -Name "Status" -Default "ok")
    switch ([string]$Filter) {
        "warnings" { return ($status -eq "warn" -or $status -eq "error") }
        "errors" { return ($status -eq "error") }
        default { return $true }
    }
}

function Format-WinToolActivityReport {
    param(
        $Run = @(),
        [string]$Filter = "all"
    )
    $items = @($Run)
    if ($items.Count -eq 0) {
        $items = @(Get-WinToolActivityRun)
    }
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($item in $items) {
        if (-not (Test-WinToolActivityRunVisible -Run $item -Filter $Filter)) {
            continue
        }
        if ($lines.Count -gt 0) {
            $lines.Add("") | Out-Null
        }
        $lines.Add([string]$item.Title) | Out-Null
        $when = Format-WinToolActivityWhen -Started $item.Started
        $duration = Format-WinToolActivityDuration -Started $item.Started -Ended $item.Ended
        if (-not [string]::IsNullOrWhiteSpace($when) -and -not [string]::IsNullOrWhiteSpace($duration)) {
            $lines.Add((Get-WinToolText "activity.meta" $when $duration)) | Out-Null
        }
        elseif (-not [string]::IsNullOrWhiteSpace($when)) {
            $lines.Add($when) | Out-Null
        }
        $lines.Add((Format-WinToolActivityCount -Run $item)) | Out-Null
        if (-not [string]::IsNullOrWhiteSpace([string]$item.Summary)) {
            $lines.Add([string]$item.Summary) | Out-Null
        }
        foreach ($step in $item.Steps) {
            if (-not (Test-WinToolActivityStepVisible -Step $step -Filter $Filter)) {
                continue
            }
            $tag = "OK  "
            $status = [string]$step.Status
            if ($status -eq "warn") { $tag = "WARN" }
            elseif ($status -eq "error") { $tag = "FAIL" }
            elseif ($status -eq "skipped") { $tag = "SKIP" }
            elseif ($status -eq "running") { $tag = "RUN " }
            $line = "  " + $tag + "  " + [string]$step.Message
            if (-not [string]::IsNullOrWhiteSpace([string]$step.Detail)) {
                $line = $line + "  " + [string]$step.Detail
            }
            $lines.Add($line) | Out-Null
        }
    }
    if ($lines.Count -eq 0) {
        if ($Filter -eq "all") {
            return (Get-WinToolText "activity.empty")
        }
        return (Get-WinToolText "activity.emptyFilter")
    }
    return ($lines.ToArray() -join [Environment]::NewLine)
}
# endregion

# region src/Private/Console.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# WinTool is a window app, so the PowerShell console that starts it is hidden
# once the window is on screen. -ShowConsole (or WINTOOL_SHOW_CONSOLE=1) keeps
# it visible for debugging. Startup errors always bring the console back.
# A console that was already hidden (powershell -WindowStyle Hidden -File, or
# the hidden relaunch) is detached on close. Showing it and then exiting paints
# a taskbar button for a moment. A console the user could already see, such as
# irm | iex, is shown again and left open.
$script:WinToolConsoleHidden = $false
$script:WinToolConsoleRestore = $false

function Test-WinToolShowConsole {
    if ($script:WinToolShowConsole) {
        return $true
    }
    return ($env:WINTOOL_SHOW_CONSOLE -eq "1")
}

function Get-WinToolConsoleMode {
    param(
        [bool]$ShowConsole,
        [bool]$Unattended,
        [string]$TerminalSession,
        [string]$HiddenChild
    )
    # show: leave the console alone.
    # hide: hide this console while the window is open.
    # relaunch: the console belongs to Windows Terminal, which cannot be hidden
    #           from here, so WinTool starts again in its own hidden console.
    if ($ShowConsole -or $Unattended) {
        return "show"
    }
    if ($HiddenChild -eq "1") {
        return "hide"
    }
    if (-not [string]::IsNullOrWhiteSpace($TerminalSession)) {
        return "relaunch"
    }
    return "hide"
}

function Get-WinToolCurrentConsoleMode {
    return Get-WinToolConsoleMode -ShowConsole (Test-WinToolShowConsole) -Unattended ([bool]$script:WinToolUnattended) -TerminalSession ([string]$env:WT_SESSION) -HiddenChild ([string]$env:WINTOOL_HIDDEN)
}

function Initialize-WinToolConsoleApi {
    if ($null -ne ("WinToolConsoleApi" -as [type])) {
        return $true
    }
    if (-not (Test-WinToolWindows)) {
        return $false
    }
    try {
        Add-Type -TypeDefinition (Get-WinToolConsoleApiSource) -Language CSharp -ErrorAction Stop
        return $true
    }
    catch {
        return $false
    }
}

function Get-WinToolConsoleApiSource {
    return @"
using System;
using System.Runtime.InteropServices;
using System.Text;

public static class WinToolConsoleApi
{
    public delegate bool EnumWindowsProc(IntPtr handle, IntPtr param);

    [DllImport("kernel32.dll")]
    public static extern IntPtr GetConsoleWindow();

    [DllImport("user32.dll")]
    public static extern bool ShowWindow(IntPtr handle, int command);

    [DllImport("user32.dll", CharSet = CharSet.Unicode)]
    public static extern IntPtr FindWindow(string className, string windowName);

    [DllImport("user32.dll")]
    public static extern bool SetForegroundWindow(IntPtr handle);

    [DllImport("user32.dll")]
    public static extern bool IsIconic(IntPtr handle);

    [DllImport("user32.dll")]
    public static extern bool IsWindowVisible(IntPtr handle);

    [DllImport("user32.dll")]
    public static extern bool AllowSetForegroundWindow(int processId);

    [DllImport("user32.dll")]
    public static extern bool EnumWindows(EnumWindowsProc callback, IntPtr param);

    [DllImport("user32.dll", CharSet = CharSet.Unicode)]
    public static extern int GetWindowText(IntPtr handle, StringBuilder buffer, int maxCount);

    [DllImport("user32.dll", CharSet = CharSet.Unicode)]
    public static extern int GetClassName(IntPtr handle, StringBuilder buffer, int maxCount);

    [DllImport("user32.dll", EntryPoint = "GetWindowLongW", SetLastError = true)]
    private static extern int GetWindowLongW(IntPtr handle, int index);

    [DllImport("user32.dll", EntryPoint = "SetWindowLongW", SetLastError = true)]
    private static extern int SetWindowLongW(IntPtr handle, int index, int value);

    [DllImport("user32.dll", SetLastError = true)]
    private static extern bool SetWindowPos(IntPtr handle, IntPtr insertAfter, int x, int y, int width, int height, uint flags);

    [DllImport("kernel32.dll", SetLastError = true)]
    public static extern bool FreeConsole();

    const int ExStyleIndex = -20;
    const int ToolWindowStyle = 0x80;
    const int AppWindowStyle = 0x40000;
    const uint FrameChanged = 0x0037;
    static int savedExStyle;
    static bool savedExStyleReady;

    static void ApplyExStyle(IntPtr handle, int value)
    {
        SetWindowLongW(handle, ExStyleIndex, value);
        SetWindowPos(handle, IntPtr.Zero, 0, 0, 0, 0, FrameChanged);
    }

    public static void KeepOffTaskbar(IntPtr handle)
    {
        if (handle == IntPtr.Zero) { return; }
        int ex = GetWindowLongW(handle, ExStyleIndex);
        if (!savedExStyleReady)
        {
            savedExStyle = ex;
            savedExStyleReady = true;
        }
        int updated = (ex | ToolWindowStyle) & ~AppWindowStyle;
        if (updated != ex) { ApplyExStyle(handle, updated); }
    }

    public static void RestoreTaskbarStyle(IntPtr handle)
    {
        if (handle == IntPtr.Zero) { return; }
        int ex;
        if (savedExStyleReady) { ex = savedExStyle; }
        else
        {
            ex = GetWindowLongW(handle, ExStyleIndex);
            ex = (ex & ~ToolWindowStyle) | AppWindowStyle;
        }
        ApplyExStyle(handle, ex);
    }

    public static void DetachHiddenConsole()
    {
        FreeConsole();
        try
        {
            Console.SetOut(System.IO.TextWriter.Null);
            Console.SetError(System.IO.TextWriter.Null);
        }
        catch
        {
        }
    }

    public static IntPtr FindWinToolWindow()
    {
        IntPtr found = IntPtr.Zero;
        EnumWindows(delegate(IntPtr handle, IntPtr param)
        {
            if (!IsWindowVisible(handle)) { return true; }
            StringBuilder title = new StringBuilder(64);
            if (GetWindowText(handle, title, title.Capacity) <= 0) { return true; }
            if (!string.Equals(title.ToString(), "WinTool", StringComparison.Ordinal)) { return true; }
            StringBuilder cls = new StringBuilder(128);
            if (GetClassName(handle, cls, cls.Capacity) <= 0) { return true; }
            if (!cls.ToString().StartsWith("HwndWrapper[", StringComparison.Ordinal)) { return true; }
            found = handle;
            return false;
        }, IntPtr.Zero);
        return found;
    }

    [DllImport("user32.dll")]
    public static extern IntPtr GetAncestor(IntPtr handle, uint flags);

    [StructLayout(LayoutKind.Sequential)]
    public struct WinToolRect
    {
        public int Left;
        public int Top;
        public int Right;
        public int Bottom;
    }

    [DllImport("user32.dll")]
    public static extern bool GetWindowRect(IntPtr handle, out WinToolRect rect);

    [DllImport("user32.dll", SetLastError = true)]
    public static extern bool SetLayeredWindowAttributes(IntPtr handle, uint colorKey, byte alpha, uint flags);

    const int LayeredStyle = 0x80000;
    const uint AlphaFlag = 0x2;

    public static bool SetWindowAlpha(IntPtr handle, byte alpha)
    {
        if (handle == IntPtr.Zero) { return false; }
        int ex = GetWindowLongW(handle, ExStyleIndex);
        if (alpha < 255)
        {
            if ((ex & LayeredStyle) == 0) { ApplyExStyle(handle, ex | LayeredStyle); }
            return SetLayeredWindowAttributes(handle, 0, alpha, AlphaFlag);
        }
        if ((ex & LayeredStyle) != 0)
        {
            SetLayeredWindowAttributes(handle, 0, 255, AlphaFlag);
            ApplyExStyle(handle, ex & ~LayeredStyle);
        }
        return true;
    }

    public static string GetWindowClassName(IntPtr handle)
    {
        if (handle == IntPtr.Zero) { return ""; }
        StringBuilder name = new StringBuilder(256);
        if (GetClassName(handle, name, name.Capacity) <= 0) { return ""; }
        return name.ToString();
    }

    public static string GetWindowRectText(IntPtr handle)
    {
        WinToolRect rect;
        if (handle == IntPtr.Zero || !GetWindowRect(handle, out rect)) { return ""; }
        return rect.Left.ToString() + "," + rect.Top.ToString() + "," + rect.Right.ToString() + "," + rect.Bottom.ToString();
    }

    public static bool FocusWinToolWindow()
    {
        IntPtr handle = FindWinToolWindow();
        if (handle == IntPtr.Zero) { return false; }
        if (IsIconic(handle)) { ShowWindow(handle, 9); }
        else { ShowWindow(handle, 5); }
        SetForegroundWindow(handle);
        return true;
    }
}
"@
}

function Test-WinToolConsoleIsVisible {
    if (-not (Initialize-WinToolConsoleApi)) {
        return $false
    }
    try {
        $handle = [WinToolConsoleApi]::GetConsoleWindow()
        if ($handle -eq [IntPtr]::Zero) {
            return $false
        }
        return [bool][WinToolConsoleApi]::IsWindowVisible($handle)
    }
    catch {
        return $false
    }
}

function Test-WinToolConsoleShouldRestore {
    # Only a console the user was already looking at comes back. WinTool's own
    # hidden process exits instead, so restoring it would flash the taskbar.
    if ((Get-WinToolCurrentConsoleMode) -eq "show") {
        return $false
    }
    if (Test-WinToolOwnedHost) {
        return $false
    }
    return [bool]$script:WinToolConsoleRestore
}

function Set-WinToolConsoleVisible {
    param(
        [Parameter(Mandatory = $true)][bool]$Visible,
        [switch]$Force
    )
    if (-not (Initialize-WinToolConsoleApi)) {
        return $false
    }
    try {
        $handle = [WinToolConsoleApi]::GetConsoleWindow()
        if ($handle -eq [IntPtr]::Zero) {
            return $false
        }
        if ($Visible) {
            if (-not $Force -and -not (Test-WinToolConsoleShouldRestore)) {
                return $true
            }
            [WinToolConsoleApi]::RestoreTaskbarStyle($handle)
            $null = [WinToolConsoleApi]::ShowWindow($handle, 5)
            $script:WinToolConsoleHidden = $false
            return $true
        }
        # Remember a console that was actually on screen. A later hide, after
        # it is already hidden, must not clear that.
        if ([WinToolConsoleApi]::IsWindowVisible($handle)) {
            $script:WinToolConsoleRestore = $true
        }
        [WinToolConsoleApi]::KeepOffTaskbar($handle)
        $null = [WinToolConsoleApi]::ShowWindow($handle, 0)
        $script:WinToolConsoleHidden = $true
        return $true
    }
    catch {
        return $false
    }
}

function Hide-WinToolConsole {
    if ((Get-WinToolCurrentConsoleMode) -eq "show") {
        return
    }
    $null = Set-WinToolConsoleVisible -Visible $false
}

function Show-WinToolConsole {
    # Errors must be readable even when the console started hidden.
    $null = Set-WinToolConsoleVisible -Visible $true -Force
}

function Remove-WinToolHiddenConsole {
    # Drop a console this process is about to destroy, while the WinTool
    # window is still up, so Windows cannot put it on the taskbar.
    if (Test-WinToolConsoleShouldRestore) {
        return
    }
    if ((Get-WinToolCurrentConsoleMode) -eq "show") {
        return
    }
    if (-not (Initialize-WinToolConsoleApi)) {
        return
    }
    try {
        $handle = [WinToolConsoleApi]::GetConsoleWindow()
        if ($handle -ne [IntPtr]::Zero) {
            [WinToolConsoleApi]::KeepOffTaskbar($handle)
            $null = [WinToolConsoleApi]::ShowWindow($handle, 0)
        }
        [WinToolConsoleApi]::DetachHiddenConsole()
    }
    catch {
        $null = $_.Exception.Message
    }
    $script:WinToolConsoleHidden = $false
}

function Set-WinToolWindowAlpha {
    param(
        $Handle,
        [Parameter(Mandatory = $true)][byte]$Alpha
    )
    if (-not (Initialize-WinToolConsoleApi)) {
        return $false
    }
    if ($null -eq $Handle -or $Handle -eq [IntPtr]::Zero) {
        return $false
    }
    try {
        return [bool][WinToolConsoleApi]::SetWindowAlpha($Handle, $Alpha)
    }
    catch {
        $null = $_.Exception.Message
        return $false
    }
}

function Hide-WinToolWindowUntilRendered {
    param($Window)
    if ($null -eq $Window) {
        return
    }
    $Window.Opacity = 0
    $source = [System.Windows.Interop.HwndSource]::FromVisual($Window)
    if ($null -eq $source -or $source.Handle -eq [IntPtr]::Zero) {
        return
    }
    $null = Set-WinToolWindowAlpha -Handle $source.Handle -Alpha 0
}

function Show-WinToolWindowAfterRender {
    param($Window)
    if ($null -eq $Window) {
        return
    }
    $source = $null
    try { $source = [System.Windows.Interop.HwndSource]::FromVisual($Window) } catch { $null = $_.Exception.Message }
    if ($null -ne $source -and $source.Handle -ne [IntPtr]::Zero) {
        $null = Set-WinToolWindowAlpha -Handle $source.Handle -Alpha 255
    }
    $Window.Opacity = 1
}
# endregion

# region src/Private/Types.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT
#requires -Version 5.1

function Get-WinToolCSharpReference {
    param([type[]]$Type)
    $refs = New-Object System.Collections.Generic.List[string]
    $core = ($PSVersionTable.PSEdition -eq "Core")
    if ($core) {
        foreach ($name in @(
                "System.Runtime",
                "System.Collections",
                "System.Collections.Concurrent",
                "System.ComponentModel.Primitives",
                "System.ObjectModel",
                "netstandard",
                "System.Diagnostics.Process"
            )) {
            [void]$refs.Add($name)
        }
    }
    $types = New-Object System.Collections.Generic.List[type]
    if (-not $core) {
        [void]$types.Add([object])
        [void]$types.Add([System.ComponentModel.INotifyPropertyChanged])
    }
    foreach ($item in @($Type)) {
        if ($null -ne $item -and -not $types.Contains($item)) {
            [void]$types.Add($item)
        }
    }
    foreach ($item in $types) {
        try {
            $name = [string]$item.Assembly.GetName().Name
            if ($name -eq "System.Private.CoreLib" -or $name -eq "mscorlib") {
                if (-not $core) {
                    $location = [string]$item.Assembly.Location
                    if (-not [string]::IsNullOrWhiteSpace($location) -and (Test-Path -LiteralPath $location) -and -not $refs.Contains($location)) {
                        [void]$refs.Add($location)
                    }
                }
                continue
            }
            $location = [string]$item.Assembly.Location
            if (-not [string]::IsNullOrWhiteSpace($location) -and (Test-Path -LiteralPath $location)) {
                if (-not $refs.Contains($location)) {
                    [void]$refs.Add($location)
                }
            }
            elseif (-not [string]::IsNullOrWhiteSpace($name) -and -not $refs.Contains($name)) {
                [void]$refs.Add($name)
            }
        }
        catch {
            $null = $_.Exception.Message
        }
    }
    return @($refs.ToArray())
}

function Add-WinToolCSharpType {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        [Parameter(Mandatory = $true)][string]$TypeDefinition,
        [type[]]$ReferenceType
    )
    if ($null -ne ($Name -as [type])) {
        return $true
    }
    $stamp = Get-Date
    try {
        $refs = @(Get-WinToolCSharpReference -Type $ReferenceType)
        if ($refs.Count -gt 0) {
            Add-Type -TypeDefinition $TypeDefinition -ReferencedAssemblies $refs -Language CSharp -ErrorAction Stop
        }
        else {
            Add-Type -TypeDefinition $TypeDefinition -Language CSharp -ErrorAction Stop
        }
        Write-WinToolStartupMark -Name ("addType." + $Name) -Started $stamp
        return $true
    }
    catch {
        $null = $_.Exception.Message
        try {
            Write-WinToolLog -Message ((Get-WinToolText "msg.could-not-compile-n-n") -f $Name, $_.Exception.Message) -Level "warn"
        }
        catch {
            $null = $_.Exception.Message
        }
        Write-WinToolStartupMark -Name ("addType." + $Name + ".failed") -Started $stamp
        return $false
    }
}

function Initialize-WinToolCompiledType {
    $stamp = Get-Date
    try { $null = Initialize-WinToolConsoleApi } catch { $null = $_.Exception.Message }
    try { $null = Initialize-WinToolThemeEntryType } catch { $null = $_.Exception.Message }
    try { $null = Initialize-WinToolGlyphMap } catch { $null = $_.Exception.Message }
    try { $null = Initialize-WinToolGlyphDraw } catch { $null = $_.Exception.Message }
    try { $null = Initialize-WinToolProcessPipe } catch { $null = $_.Exception.Message }
    try { $null = Initialize-WinToolNativeMethod } catch { $null = $_.Exception.Message }
    try { $null = Initialize-WinToolFontLoader } catch { $null = $_.Exception.Message }
    Write-WinToolStartupMark -Name "compiledTypes" -Started $stamp
}

function Write-WinToolStartupMark {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        [datetime]$Started
    )
    if ($null -eq $script:WinToolStartupMarks) {
        $script:WinToolStartupMarks = [ordered]@{}
    }
    $elapsed = $null
    if ($null -ne $Started) {
        $elapsed = [int]((Get-Date) - $Started).TotalMilliseconds
    }
    elseif ($null -ne $script:WinToolStartupStamp) {
        $elapsed = [int]$script:WinToolStartupStamp.ElapsedMilliseconds
    }
    $script:WinToolStartupMarks[$Name] = $elapsed
}

function Write-WinToolStartupLog {
    $path = [string]$env:WINTOOL_STARTUP_LOG
    if ([string]::IsNullOrWhiteSpace($path) -or $null -eq $script:WinToolStartupMarks) {
        return
    }
    try {
        $lines = New-Object System.Collections.Generic.List[string]
        foreach ($key in @($script:WinToolStartupMarks.Keys)) {
            [void]$lines.Add(("{0}={1}" -f $key, $script:WinToolStartupMarks[$key]))
        }
        [System.IO.File]::WriteAllLines($path, $lines.ToArray())
    }
    catch {
        $null = $_.Exception.Message
    }
}

function Enter-WinToolUiWork {
    param([Parameter(Mandatory = $true)][string]$Name)
    if ($null -eq $script:WinToolUiWorkStack) {
        $script:WinToolUiWorkStack = New-Object System.Collections.Generic.List[string]
    }
    [void]$script:WinToolUiWorkStack.Add($Name)
    $script:WinToolUiWork = $Name
}

function Exit-WinToolUiWork {
    param([datetime]$Started, [string]$Name)
    if ($null -ne $Started -and -not [string]::IsNullOrWhiteSpace($Name)) {
        $elapsed = [int]((Get-Date) - $Started).TotalMilliseconds
        if ($Name.StartsWith("ui.") -and $elapsed -lt 50) {
            # Frequent UI ticks would drown the phase table.
        }
        else {
            Write-WinToolStartupMark -Name $Name -Started $Started
        }
    }
    if ($null -ne $script:WinToolUiWorkStack -and $script:WinToolUiWorkStack.Count -gt 0) {
        $script:WinToolUiWorkStack.RemoveAt($script:WinToolUiWorkStack.Count - 1)
        if ($script:WinToolUiWorkStack.Count -gt 0) {
            $script:WinToolUiWork = $script:WinToolUiWorkStack[$script:WinToolUiWorkStack.Count - 1]
        }
        else {
            $script:WinToolUiWork = $null
        }
    }
    else {
        $script:WinToolUiWork = $null
    }
}

function Invoke-WinToolMeasuredWork {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        [Parameter(Mandatory = $true)][scriptblock]$Script
    )
    $started = Get-Date
    Enter-WinToolUiWork -Name $Name
    try {
        return (& $Script)
    }
    finally {
        Exit-WinToolUiWork -Started $started -Name $Name
    }
}

function Start-WinToolDispatcherHeartbeat {
    if ($null -ne $script:WinToolDispatcherHeartbeat) {
        return
    }
    if ($null -eq $script:WinToolDispatcherGaps) {
        $script:WinToolDispatcherGaps = New-Object System.Collections.Generic.List[object]
    }
    $script:WinToolDispatcherBeat = [System.Diagnostics.Stopwatch]::StartNew()
    $script:WinToolDispatcherLastMs = 0
    $timer = New-Object System.Windows.Threading.DispatcherTimer
    $timer.Interval = [TimeSpan]::FromMilliseconds(50)
    Register-WinToolUiEvent -Control $timer -EventName "Tick" -Name "Dispatcher heartbeat" -Action {
        $now = 0
        if ($null -ne $script:WinToolDispatcherBeat) { $now = [int]$script:WinToolDispatcherBeat.ElapsedMilliseconds }
        $gap = $now - [int]$script:WinToolDispatcherLastMs
        $script:WinToolDispatcherLastMs = $now
        if ($gap -ge 50) {
            $work = [string]$script:WinToolUiWork
            if ($work -eq "Dispatcher heartbeat" -or [string]::IsNullOrWhiteSpace($work)) {
                $work = "(idle or unknown)"
            }
            if ($null -eq $script:WinToolDispatcherGaps) {
                $script:WinToolDispatcherGaps = New-Object System.Collections.Generic.List[object]
            }
            [void]$script:WinToolDispatcherGaps.Add([pscustomobject]@{
                    AtMs  = $now
                    GapMs = $gap
                    Work  = $work
                })
        }
    }
    $timer.Start()
    $script:WinToolDispatcherHeartbeat = $timer
}

function Stop-WinToolDispatcherHeartbeat {
    $timer = $script:WinToolDispatcherHeartbeat
    $script:WinToolDispatcherHeartbeat = $null
    if ($null -ne $timer) {
        try { $timer.Stop() } catch { $null = $_.Exception.Message }
    }
}

function Get-WinToolDispatcherGap {
    if ($null -eq $script:WinToolDispatcherGaps) {
        return , @()
    }
    return , $script:WinToolDispatcherGaps.ToArray()
}

function Write-WinToolStartupPhaseTable {
    Write-Output "----- startup phase table -----"
    Write-Output ("{0,-42} {1,8}" -f "Phase", "ms")
    if ($null -ne $script:WinToolStartupMarks) {
        foreach ($key in @($script:WinToolStartupMarks.Keys)) {
            Write-Output ("{0,-42} {1,8}" -f [string]$key, $script:WinToolStartupMarks[$key])
        }
    }
    Write-Output "----- dispatcher gaps of 50 ms or more -----"
    $gaps = @(@(Get-WinToolDispatcherGap) | Where-Object { $null -ne $_ })
    if ($gaps.Count -eq 0) {
        Write-Output "(none)"
        return
    }
    Write-Output ("{0,8} {1,8}  {2}" -f "AtMs", "GapMs", "Work")
    foreach ($gap in $gaps) {
        Write-Output ("{0,8} {1,8}  {2}" -f $gap.AtMs, $gap.GapMs, $gap.Work)
    }
    $max = ($gaps | Measure-Object -Property GapMs -Maximum).Maximum
    Write-Output ("Dispatcher gap count: {0}; max: {1} ms." -f $gaps.Count, $max)
}

function Import-WinToolAppxModule {
    if ($script:WinToolAppxModuleReady) {
        return
    }
    if ($PSVersionTable.PSEdition -eq "Core") {
        try {
            Import-Module Appx -UseWindowsPowerShell -WarningAction SilentlyContinue -ErrorAction Stop
            $script:WinToolAppxModuleReady = $true
            return
        }
        catch {
            $null = $_.Exception.Message
        }
    }
    try {
        Import-Module Appx -ErrorAction SilentlyContinue
    }
    catch {
        $null = $_.Exception.Message
    }
    $script:WinToolAppxModuleReady = $true
}

function Import-WinToolDismModule {
    if ($script:WinToolDismModuleReady) {
        return
    }
    if ($PSVersionTable.PSEdition -eq "Core") {
        try {
            Import-Module DISM -UseWindowsPowerShell -WarningAction SilentlyContinue -ErrorAction Stop
            $script:WinToolDismModuleReady = $true
            return
        }
        catch {
            $null = $_.Exception.Message
        }
    }
    try {
        Import-Module DISM -ErrorAction SilentlyContinue
    }
    catch {
        $null = $_.Exception.Message
    }
    $script:WinToolDismModuleReady = $true
}

function Initialize-WinToolFontLoader {
    return (Add-WinToolCSharpType -Name "WinToolFontLoader" -ReferenceType @([object]) -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
public static class WinToolFontLoader {
    [DllImport("gdi32.dll", CharSet = CharSet.Unicode)]
    public static extern int AddFontResource(string file);
}
"@)
}
