function Get-WinToolFontDocument {
    return (Get-WinToolCachedPayloadObject -Name "Fonts")
}

function Get-WinToolOhMyPoshDocument {
    return (Get-WinToolCachedPayloadObject -Name "OmpThemes")
}

function Select-WinToolFont {
    param(
        $Font,
        [string]$Query,
        [bool]$NerdOnly = $false,
        [bool]$PlainOnly = $false
    )
    $matched = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($Font)) {
        $isNerd = $false
        if ($null -ne $item.PSObject.Properties["nerd"] -and $item.nerd) {
            $isNerd = $true
        }
        if ($NerdOnly -and -not $isNerd) {
            continue
        }
        if ($PlainOnly -and $isNerd) {
            continue
        }
        $haystack = (([string]$item.name) + " " + ([string]$item.face) + " " + ([string]$item.id))
        if (Test-WinToolTextMatch -Haystack $haystack -Query $Query) {
            $matched.Add($item)
        }
    }
    return $matched.ToArray()
}

function Get-WinToolOhMyPoshThemeFile {
    param(
        [string]$PromptStyle
    )
    $themeFile = "jandedobbeleer.omp.json"
    if (-not [string]::IsNullOrWhiteSpace($PromptStyle)) {
        if ($PromptStyle.EndsWith(".omp.json")) {
            $themeFile = $PromptStyle
        }
        else {
            $themeFile = $PromptStyle + ".omp.json"
        }
    }
    return $themeFile
}

function Get-WinToolPromptScript {
    param(
        [Parameter(Mandatory = $true)][string]$PromptId,
        [bool]$TerminalIcons = $true,
        [string]$PromptStyle = "",
        [bool]$PsReadLine = $false,
        [bool]$Zoxide = $false
    )
    # The same text goes into the Windows PowerShell 5.1 and PowerShell 7
    # profiles. Every block is wrapped so a missing tool, an old module, or a
    # missing variable never prints an error when a terminal opens.
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add("# Added by WinTool. Delete this block, or run WinTool again, to change it.")
    # Prompt and zoxide init only run in a real interactive console (Windows
    # Terminal, conhost, or the VS Code terminal). A script host, a remote
    # session, or TERM=dumb gets none, and empty init output is never run.
    $lines.Add('$wintoolInteractive = $false')
    $lines.Add('try {')
    $lines.Add('    $wintoolInteractive = [Environment]::UserInteractive -and ([string]$env:TERM -ne "dumb") -and (@("ConsoleHost", "Visual Studio Code Host") -contains [string]$Host.Name)')
    $lines.Add('}')
    $lines.Add('catch { $wintoolInteractive = $false }')
    if ($TerminalIcons) {
        $lines.Add('try {')
        $lines.Add('    if (Get-Module -ListAvailable -Name Terminal-Icons) {')
        $lines.Add('        Import-Module Terminal-Icons -ErrorAction Stop')
        $lines.Add('    }')
        $lines.Add('}')
        $lines.Add('catch { $null = $_ }')
    }
    if ($PsReadLine) {
        # Windows PowerShell 5.1 ships PSReadLine 2.0, which has neither
        # option. PredictionSource came in 2.1 and PredictionViewStyle in 2.2.
        # Predictions also refuse to start when output is redirected.
        $lines.Add('try {')
        $lines.Add('    $wintoolReadLine = $null')
        $lines.Add('    if (-not [Console]::IsOutputRedirected) { $wintoolReadLine = Get-Command -Name Set-PSReadLineOption -ErrorAction Ignore }')
        $lines.Add('    if ($null -ne $wintoolReadLine -and $wintoolReadLine.Parameters.ContainsKey("PredictionSource")) {')
        $lines.Add('        Set-PSReadLineOption -PredictionSource History -ErrorAction Stop -WarningAction SilentlyContinue')
        $lines.Add('    }')
        $lines.Add('    if ($null -ne $wintoolReadLine -and $wintoolReadLine.Parameters.ContainsKey("PredictionViewStyle")) {')
        $lines.Add('        Set-PSReadLineOption -PredictionViewStyle ListView -ErrorAction Stop -WarningAction SilentlyContinue')
        $lines.Add('    }')
        $lines.Add('}')
        $lines.Add('catch { $null = $_ }')
    }
    if ($Zoxide) {
        $lines.Add('try {')
        $lines.Add('    $wintoolZoxide = $null')
        $lines.Add('    if ($wintoolInteractive) { $wintoolZoxide = Get-Command -Name zoxide -CommandType Application -ErrorAction Ignore | Select-Object -First 1 }')
        $lines.Add('    if ($wintoolInteractive -and $null -eq $wintoolZoxide) {')
        $lines.Add('        foreach ($wintoolPath in @(([string]$env:LOCALAPPDATA + "\Microsoft\WinGet\Links\zoxide.exe"), ([string]$env:USERPROFILE + "\.cargo\bin\zoxide.exe"), ([string]$env:LOCALAPPDATA + "\Programs\zoxide\bin\zoxide.exe"))) {')
        $lines.Add('            if (-not [string]::IsNullOrWhiteSpace($wintoolPath) -and (Test-Path -LiteralPath $wintoolPath)) { $wintoolZoxide = Get-Command -Name $wintoolPath -ErrorAction Ignore; break }')
        $lines.Add('        }')
        $lines.Add('    }')
        $lines.Add('    if ($null -ne $wintoolZoxide) {')
        $lines.Add('        $global:LASTEXITCODE = 0')
        $lines.Add('        $wintoolInit = (& $wintoolZoxide.Source init powershell 2>$null | Out-String)')
        $lines.Add('        if ($LASTEXITCODE -eq 0 -and -not [string]::IsNullOrWhiteSpace($wintoolInit)) { Invoke-Expression $wintoolInit }')
        $lines.Add('    }')
        $lines.Add('}')
        $lines.Add('catch { $null = $_ }')
    }
    if ($PromptId -eq "starship") {
        $lines.Add('try {')
        $lines.Add('    $wintoolStarship = $null')
        $lines.Add('    if ($wintoolInteractive) { $wintoolStarship = Get-Command -Name starship -CommandType Application -ErrorAction Ignore | Select-Object -First 1 }')
        $lines.Add('    if ($wintoolInteractive -and $null -eq $wintoolStarship) {')
        $lines.Add('        foreach ($wintoolPath in @(([string]$env:ProgramFiles + "\starship\bin\starship.exe"), ([string]$env:LOCALAPPDATA + "\Programs\starship\bin\starship.exe"), ([string]$env:LOCALAPPDATA + "\Microsoft\WinGet\Links\starship.exe"), ([string]$env:USERPROFILE + "\.cargo\bin\starship.exe"))) {')
        $lines.Add('            if (-not [string]::IsNullOrWhiteSpace($wintoolPath) -and (Test-Path -LiteralPath $wintoolPath)) { $wintoolStarship = Get-Command -Name $wintoolPath -ErrorAction Ignore; break }')
        $lines.Add('        }')
        $lines.Add('    }')
        $lines.Add('    if ($null -ne $wintoolStarship) {')
        $lines.Add('        $global:LASTEXITCODE = 0')
        $lines.Add('        $wintoolInit = (& $wintoolStarship.Source init powershell 2>$null | Out-String)')
        $lines.Add('        if ($LASTEXITCODE -eq 0 -and -not [string]::IsNullOrWhiteSpace($wintoolInit)) { Invoke-Expression $wintoolInit }')
        $lines.Add('    }')
        $lines.Add('}')
        $lines.Add('catch { $null = $_ }')
    }
    elseif ($PromptId -eq "oh-my-posh") {
        $themeFile = Get-WinToolOhMyPoshThemeFile -PromptStyle $PromptStyle
        # POSH_THEMES_PATH is not set by newer Oh My Posh builds, so WinTool
        # saves the theme under %LOCALAPPDATA%\WinTool\themes during setup and
        # also looks in the older theme folders.
        # oh-my-posh init needs "pwsh" for PowerShell Core 6+ and "powershell" for Windows PowerShell 5.1.
        $lines.Add('try {')
        $lines.Add('    $wintoolPosh = $null')
        $lines.Add('    if ($wintoolInteractive) { $wintoolPosh = Get-Command -Name oh-my-posh -CommandType Application -ErrorAction Ignore | Select-Object -First 1 }')
        $lines.Add('    if ($wintoolInteractive -and $null -eq $wintoolPosh) {')
        $lines.Add('        foreach ($wintoolPath in @(([string]$env:LOCALAPPDATA + "\Programs\oh-my-posh\bin\oh-my-posh.exe"), ([string]$env:ProgramFiles + "\oh-my-posh\bin\oh-my-posh.exe"), ([string]${env:ProgramFiles(x86)} + "\oh-my-posh\bin\oh-my-posh.exe"), ([string]$env:LOCALAPPDATA + "\Microsoft\WinGet\Links\oh-my-posh.exe"))) {')
        $lines.Add('            if (-not [string]::IsNullOrWhiteSpace($wintoolPath) -and (Test-Path -LiteralPath $wintoolPath)) { $wintoolPosh = Get-Command -Name $wintoolPath -ErrorAction Ignore; break }')
        $lines.Add('        }')
        $lines.Add('    }')
        $lines.Add('    if ($null -ne $wintoolPosh) {')
        $lines.Add('        $wintoolShell = "pwsh"')
        $lines.Add('        if ($PSVersionTable.PSEdition -ne "Core") { $wintoolShell = "powershell" }')
        $lines.Add('        $wintoolTheme = $null')
        $lines.Add('        foreach ($wintoolFolder in @([string]$env:POSH_THEMES_PATH, ([string]$env:LOCALAPPDATA + "\WinTool\themes"), ([string]$env:LOCALAPPDATA + "\Programs\oh-my-posh\themes"), ([string]$env:ProgramFiles + "\oh-my-posh\themes"), ([string]${env:ProgramFiles(x86)} + "\oh-my-posh\themes"))) {')
        $lines.Add('            if ([string]::IsNullOrWhiteSpace($wintoolFolder)) { continue }')
        $lines.Add('            $wintoolCandidate = Join-Path $wintoolFolder "' + $themeFile + '"')
        $lines.Add('            if (Test-Path -LiteralPath $wintoolCandidate) { $wintoolTheme = $wintoolCandidate; break }')
        $lines.Add('        }')
        $lines.Add('        $global:LASTEXITCODE = 0')
        $lines.Add('        $wintoolInit = $null')
        $lines.Add('        if ($null -ne $wintoolTheme) {')
        $lines.Add('            $wintoolInit = (& $wintoolPosh.Source init $wintoolShell --config $wintoolTheme 2>$null | Out-String)')
        $lines.Add('        }')
        $lines.Add('        else {')
        $lines.Add('            $wintoolInit = (& $wintoolPosh.Source init $wintoolShell 2>$null | Out-String)')
        $lines.Add('        }')
        $lines.Add('        if ($LASTEXITCODE -eq 0 -and -not [string]::IsNullOrWhiteSpace($wintoolInit)) { Invoke-Expression $wintoolInit }')
        $lines.Add('    }')
        $lines.Add('}')
        $lines.Add('catch { $null = $_ }')
    }
    elseif ($PromptId -eq "powerline-go") {
        $styleArgs = @(Get-WinToolPromptVariantArgument -Variant (Get-WinToolPromptVariant -PromptId $PromptId -PromptStyle $PromptStyle))
        $argText = ""
        foreach ($arg in $styleArgs) { $argText += " '" + $arg + "'" }
        $lines.Add('if ($wintoolInteractive) {')
        $lines.Add('    function global:prompt {')
        $lines.Add('        $wintoolExit = $LASTEXITCODE')
        $lines.Add('        try {')
        $lines.Add('            $tool = [string]$env:LOCALAPPDATA + "\WinTool\bin\powerline-go.exe"')
        $lines.Add('            if (Test-Path -LiteralPath $tool) {')
        $lines.Add('                $global:LASTEXITCODE = 0')
        $lines.Add('                $wintoolLine = ((& $tool -error $wintoolExit -shell bare' + $argText + ') -join "")')
        $lines.Add('                if ($LASTEXITCODE -eq 0 -and -not [string]::IsNullOrWhiteSpace($wintoolLine)) { return $wintoolLine }')
        $lines.Add('            }')
        $lines.Add('        }')
        $lines.Add('        catch { $null = $_ }')
        $lines.Add('        return "PS $($executionContext.SessionState.Path.CurrentLocation)> "')
        $lines.Add('    }')
        $lines.Add('}')
    }
    else {
        $lines.Add("# The prompt for this setup runs inside WSL, not in this PowerShell profile.")
    }
    return ($lines -join "`r`n")
}

function Update-WinToolManagedBlock {
    param(
        [AllowEmptyString()][string]$Text,
        [Parameter(Mandatory = $true)][string]$Begin,
        [Parameter(Mandatory = $true)][string]$End,
        [Parameter(Mandatory = $true)][string]$Body
    )
    $block = $Begin + "`r`n" + $Body.Trim() + "`r`n" + $End
    $pattern = "(?s)" + [regex]::Escape($Begin) + ".*?" + [regex]::Escape($End)
    if ($Text -match $pattern) {
        $evaluator = [System.Text.RegularExpressions.MatchEvaluator]{
            param($found)
            if ($null -eq $found) {
                return $block
            }
            return $block
        }.GetNewClosure()
        return [regex]::Replace($Text, $pattern, $evaluator)
    }
    $prefix = [string]$Text
    if ($prefix.Length -gt 0 -and -not $prefix.EndsWith("`n")) {
        $prefix += "`r`n"
    }
    if ($prefix.Length -gt 0) {
        $prefix += "`r`n"
    }
    return $prefix + $block + "`r`n"
}

function Get-WinToolShellProfilePath {
    param(
        [Parameter(Mandatory = $true)][ValidateSet("powershell", "pwsh")][string]$HostName
    )
    $documents = [Environment]::GetFolderPath("MyDocuments")
    if ($HostName -eq "pwsh") {
        return (Join-Path $documents "PowerShell/Microsoft.PowerShell_profile.ps1")
    }
    return (Join-Path $documents "WindowsPowerShell/Microsoft.PowerShell_profile.ps1")
}

function Get-WinToolTerminalSettingsPath {
    if ([string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        return $null
    }
    $candidates = @(
        (Join-Path $env:LOCALAPPDATA "Packages/Microsoft.WindowsTerminal_8wekyb3d8bbwe/LocalState/settings.json"),
        (Join-Path $env:LOCALAPPDATA "Microsoft/Windows Terminal/settings.json")
    )
    foreach ($candidate in $candidates) {
        if (Test-Path -LiteralPath $candidate) {
            return $candidate
        }
    }
    $directories = @(
        (Join-Path $env:LOCALAPPDATA "Packages/Microsoft.WindowsTerminal_8wekyb3d8bbwe/LocalState"),
        (Join-Path $env:LOCALAPPDATA "Microsoft/Windows Terminal")
    )
    foreach ($directory in $directories) {
        if (Test-Path -LiteralPath $directory) {
            return (Join-Path $directory "settings.json")
        }
    }
    return $null
}

function ConvertTo-WinToolFontFace {
    param(
        [Parameter(Mandatory = $true)][string]$RegistryName
    )
    $face = $RegistryName -replace '\s*\((TrueType|OpenType)\)\s*$', ''
    return $face.Trim()
}

function Add-WinToolTerminalFont {
    param(
        [Parameter(Mandatory = $true)]$Settings,
        [Parameter(Mandatory = $true)][string]$Face,
        [int]$Size = 12
    )
    if ($null -eq $Settings.PSObject.Properties["profiles"]) {
        $Settings | Add-Member -NotePropertyName "profiles" -NotePropertyValue ([pscustomobject]@{})
    }
    $profiles = $Settings.profiles
    if ($null -eq $profiles.PSObject.Properties["defaults"]) {
        $profiles | Add-Member -NotePropertyName "defaults" -NotePropertyValue ([pscustomobject]@{})
    }
    $defaults = $profiles.defaults
    # Only face and size change; other font settings (features, weight,
    # axes) the user already has are kept.
    $font = Get-WinToolNote -Object $defaults -Name "font"
    if ($null -eq $font -or $font -isnot [System.Management.Automation.PSCustomObject]) {
        $font = [pscustomobject]@{}
        $defaults | Add-Member -NotePropertyName "font" -NotePropertyValue $font -Force
    }
    $font | Add-Member -NotePropertyName "face" -NotePropertyValue $Face -Force
    $font | Add-Member -NotePropertyName "size" -NotePropertyValue $Size -Force
    if ($null -eq $defaults.PSObject.Properties["fontFace"]) {
        $defaults | Add-Member -NotePropertyName "fontFace" -NotePropertyValue $Face
    }
    else {
        $defaults.fontFace = $Face
    }
    return $Settings
}

$script:WinToolLigatureFeatures = [ordered]@{ calt = 1; liga = 1 }

function Set-WinToolFontFeatureObject {
    param(
        [Parameter(Mandatory = $true)]$Font
    )
    # Adds calt=1 and liga=1 to font.features and keeps every other feature.
    $features = Get-WinToolNote -Object $Font -Name "features"
    if ($null -eq $features -or $features -isnot [System.Management.Automation.PSCustomObject]) {
        $features = [pscustomobject]@{}
        $Font | Add-Member -NotePropertyName "features" -NotePropertyValue $features -Force
    }
    foreach ($key in $script:WinToolLigatureFeatures.Keys) {
        $features | Add-Member -NotePropertyName $key -NotePropertyValue ([int]$script:WinToolLigatureFeatures[$key]) -Force
    }
}

function Add-WinToolTerminalLigature {
    param(
        [Parameter(Mandatory = $true)]$Settings
    )
    # Turns on font ligatures for every Windows Terminal profile: the shared
    # profiles.defaults.font.features gets calt and liga, and any profile
    # with its own features list (which would hide the default) gets them too.
    $profiles = $null
    if ($null -ne $Settings.PSObject.Properties["profiles"]) { $profiles = $Settings.PSObject.Properties["profiles"].Value }
    if ($null -ne $profiles -and $profiles -is [System.Array]) {
        # Old settings files keep profiles as a plain list.
        $profiles = [pscustomobject]@{ defaults = [pscustomobject]@{}; list = $profiles }
        $Settings | Add-Member -NotePropertyName "profiles" -NotePropertyValue $profiles -Force
    }
    if ($null -eq $profiles) {
        $profiles = [pscustomobject]@{}
        $Settings | Add-Member -NotePropertyName "profiles" -NotePropertyValue $profiles -Force
    }
    $defaults = Get-WinToolNote -Object $profiles -Name "defaults"
    if ($null -eq $defaults) {
        $defaults = [pscustomobject]@{}
        $profiles | Add-Member -NotePropertyName "defaults" -NotePropertyValue $defaults -Force
    }
    $font = Get-WinToolNote -Object $defaults -Name "font"
    if ($null -eq $font -or $font -isnot [System.Management.Automation.PSCustomObject]) {
        $font = [pscustomobject]@{}
        $defaults | Add-Member -NotePropertyName "font" -NotePropertyValue $font -Force
    }
    Set-WinToolFontFeatureObject -Font $font
    $count = 0
    foreach ($item in @(Get-WinToolNote -Object $profiles -Name "list" -Default @())) {
        if ($null -eq $item) { continue }
        $own = Get-WinToolNote -Object $item -Name "font"
        if ($null -eq $own -or $null -eq (Get-WinToolNote -Object $own -Name "features")) { continue }
        Set-WinToolFontFeatureObject -Font $own
        $count++
    }
    return $count
}

function Backup-WinToolTerminalSetting {
    param(
        [Parameter(Mandatory = $true)][string]$Path
    )
    if (-not (Test-Path -LiteralPath $Path)) {
        return
    }
    $backup = $Path + ".wintool-backup"
    if (-not (Test-Path -LiteralPath $backup)) {
        Copy-Item -LiteralPath $Path -Destination $backup -Force
        Write-WinToolLog -Message (Get-WinToolText "msg.saved-a-backup-of-terminal-settings-next-to-settings-jso") -Level "info"
    }
}

function Invoke-WinToolTerminalLigature {
    param(
        [string[]]$SettingsPath
    )
    $paths = @($SettingsPath | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    if ($paths.Count -eq 0) {
        $paths = @(Get-WinToolTerminalSettingsPathList)
    }
    if ($paths.Count -eq 0) {
        Write-WinToolLog -Message (Get-WinToolText "msg.windows-terminal-settings-were-not-found-open-terminal-o") -Level "warn"
        return $false
    }
    $any = $false
    $ownCount = 0
    foreach ($path in $paths) {
        $raw = "{}"
        if (Test-Path -LiteralPath $path) {
            $raw = [System.IO.File]::ReadAllText($path)
            if ([string]::IsNullOrWhiteSpace($raw)) { $raw = "{}" }
        }
        $settings = $null
        try {
            $settings = ConvertFrom-WinToolJsonText -Text $raw
        }
        catch {
            $settings = $null
        }
        if ($null -ne $settings -and (Test-WinToolSettingsLigatureMatch -Settings $settings)) {
            continue
        }
        $result = Set-WinToolJsoncPath -Text $raw -Name @("profiles", "defaults", "font", "features", "calt") -Value 1 -Kind "number"
        $raw = [string]$result.Text
        $changed = [bool]$result.Changed
        $result = Set-WinToolJsoncPath -Text $raw -Name @("profiles", "defaults", "font", "features", "liga") -Value 1 -Kind "number"
        $raw = [string]$result.Text
        if ([bool]$result.Changed) { $changed = $true }
        # Profiles with their own font.features hide the default, so they get calt and liga too.
        $listChanged = 0
        $again = $true
        $guard = 0
        while ($again -and $guard -lt 40) {
            $again = $false
            $guard++
            $root = Get-WinToolJsoncRootStart -Text $raw
            if ($null -eq $root) { break }
            $map = Get-WinToolJsoncObjectMap -Text $raw -Start ([int]$root)
            $profiles = Get-WinToolJsoncProperty -Object $map -Name "profiles"
            if ($null -eq $profiles -or [string]$profiles.Kind -ne "object") { break }
            $profileMap = Get-WinToolJsoncObjectMap -Text $raw -Start ([int]$profiles.ValueStart)
            $list = Get-WinToolJsoncProperty -Object $profileMap -Name "list"
            if ($null -eq $list -or [string]$list.Kind -ne "array") { break }
            foreach ($item in @(Get-WinToolJsoncArrayItem -Text $raw -Start ([int]$list.ValueStart))) {
                if ([string]$item.Kind -ne "object") { continue }
                $object = Get-WinToolJsoncObjectMap -Text $raw -Start ([int]$item.Start)
                $font = Get-WinToolJsoncProperty -Object $object -Name "font"
                if ($null -eq $font -or [string]$font.Kind -ne "object") { continue }
                $fontMap = Get-WinToolJsoncObjectMap -Text $raw -Start ([int]$font.ValueStart)
                $features = Get-WinToolJsoncProperty -Object $fontMap -Name "features"
                if ($null -eq $features -or [string]$features.Kind -ne "object") { continue }
                $featureMap = Get-WinToolJsoncObjectMap -Text $raw -Start ([int]$features.ValueStart)
                foreach ($key in @("calt", "liga")) {
                    $property = Get-WinToolJsoncProperty -Object $featureMap -Name $key
                    if ($null -ne $property) {
                        $current = $raw.Substring([int]$property.ValueStart, ([int]$property.ValueEnd - [int]$property.ValueStart)).Trim()
                        if ($current -eq "1") { continue }
                    }
                    $raw = Set-WinToolJsoncObjectLiteral -Text $raw -Object $featureMap -Name $key -Literal "1"
                    $changed = $true
                    $listChanged++
                    $again = $true
                    break
                }
                if ($again) { break }
            }
        }
        if ($listChanged -gt 0) { $ownCount += $listChanged }
        if ($changed) {
            Backup-WinToolTerminalSetting -Path $path
            $out = $raw
            if (-not $out.EndsWith("`n")) { $out += "`n" }
            Write-WinToolUtf8File -Path $path -Text $out
            $any = $true
        }
    }
    if ($any) {
        $message = "Turned on font ligatures (calt, liga) for all Windows Terminal profiles."
        if ($ownCount -gt 0) { $message += " Also updated " + $ownCount + " profile(s) with their own font features." }
        Write-WinToolLog -Message $message -Level "ok"
    }
    else {
        Write-WinToolLog -Message (Get-WinToolText "msg.font-ligatures-were-already-on") -Level "ok"
    }
    return $any
}

$script:WinToolSchemeColorKeys = @("black", "red", "green", "yellow", "blue", "purple", "cyan", "white", "brightBlack", "brightRed", "brightGreen", "brightYellow", "brightBlue", "brightPurple", "brightCyan", "brightWhite")

function Add-WinToolTerminalScheme {
    param(
        [Parameter(Mandatory = $true)]$Settings,
        [Parameter(Mandatory = $true)]$Scheme
    )
    # Windows Terminal ignores a scheme that lacks any of the 16 table colors,
    # so the full palette is written before a profile points at the name.
    $fields = [ordered]@{
        name = [string]$Scheme.name
        background = [string]$Scheme.background
        foreground = [string]$Scheme.foreground
        cursorColor = [string]$Scheme.cursor
        selectionBackground = [string]$Scheme.selection
    }
    $palette = Get-WinToolNote -Object $Scheme -Name "palette"
    foreach ($key in $script:WinToolSchemeColorKeys) {
        $value = [string](Get-WinToolNote -Object $palette -Name $key -Default "")
        if ([string]::IsNullOrWhiteSpace($value)) {
            throw (Get-WinToolText "msg.the-color-scheme-n-has-no-n-color" $Scheme.name $key)
        }
        $fields[$key] = $value
    }
    $entry = [pscustomobject]$fields
    $existing = @()
    if ($null -ne $Settings.PSObject.Properties["schemes"] -and $null -ne $Settings.schemes) {
        $existing = @($Settings.schemes)
    }
    $kept = New-Object System.Collections.Generic.List[object]
    foreach ($item in $existing) {
        if ([string]$item.name -ne [string]$entry.name) {
            $kept.Add($item)
        }
    }
    $kept.Add($entry)
    if ($null -eq $Settings.PSObject.Properties["schemes"]) {
        $Settings | Add-Member -NotePropertyName "schemes" -NotePropertyValue ($kept.ToArray())
    }
    else {
        $Settings.schemes = $kept.ToArray()
    }
    if ($null -eq $Settings.PSObject.Properties["profiles"]) {
        $Settings | Add-Member -NotePropertyName "profiles" -NotePropertyValue ([pscustomobject]@{})
    }
    if ($null -eq $Settings.profiles.PSObject.Properties["defaults"]) {
        $Settings.profiles | Add-Member -NotePropertyName "defaults" -NotePropertyValue ([pscustomobject]@{})
    }
    if ($null -eq $Settings.profiles.defaults.PSObject.Properties["colorScheme"]) {
        $Settings.profiles.defaults | Add-Member -NotePropertyName "colorScheme" -NotePropertyValue ([string]$entry.name)
    }
    else {
        $Settings.profiles.defaults.colorScheme = [string]$entry.name
    }
    return $Settings
}

function Save-WinToolOhMyPoshTheme {
    param(
        [Parameter(Mandatory = $true)][string]$ThemeFile,
        [switch]$SkipIfPresent
    )
    # Keeps a copy of the theme where the profile can always find it.
    if ([string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        return $null
    }
    $folder = Join-Path $env:LOCALAPPDATA "WinTool\themes"
    $target = Join-Path $folder $ThemeFile
    $part = $target + ".part"
    if ($SkipIfPresent -and (Test-Path -LiteralPath $target) -and (Get-Item -LiteralPath $target).Length -gt 2) {
        return $target
    }
    try {
        if (-not (Test-Path -LiteralPath $folder)) {
            New-Item -ItemType Directory -Path $folder -Force | Out-Null
        }
        [Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
        $url = "https://raw.githubusercontent.com/JanDeDobbeleer/oh-my-posh/main/themes/" + [uri]::EscapeDataString($ThemeFile)
        Invoke-WebRequest -Uri $url -OutFile $part -UseBasicParsing -TimeoutSec 30
        if (-not (Test-Path -LiteralPath $part) -or (Get-Item -LiteralPath $part).Length -le 2) {
            throw (Get-WinToolText "msg.downloaded-theme-file-was-empty")
        }
        Move-Item -LiteralPath $part -Destination $target -Force
        if ($null -ne $script:WinToolOmpThemeCache) {
            $script:WinToolOmpThemeCache.Remove($ThemeFile)
        }
        Write-WinToolLog -Message (Get-WinToolText "msg.saved-the-oh-my-posh-theme-to-n" $target) -Level "ok"
        return $target
    }
    catch {
        Remove-Item -LiteralPath $part -Force -ErrorAction SilentlyContinue
        if (Test-Path -LiteralPath $target) {
            Write-WinToolLog -Message (Get-WinToolText "msg.could-not-refresh-the-oh-my-posh-theme-so-the-saved-copy" $($_.Exception.Message)) -Level "warn"
            return $target
        }
        Write-WinToolLog -Message (Get-WinToolText "msg.could-not-download-the-oh-my-posh-theme-n-so-the-default" $ThemeFile $($_.Exception.Message)) -Level "warn"
        return $null
    }
}

function Write-WinToolShellProfile {
    param(
        [Parameter(Mandatory = $true)][string]$PromptId,
        [bool]$TerminalIcons = $true,
        [string]$PromptStyle = "",
        [bool]$PsReadLine = $false,
        [bool]$Zoxide = $false,
        [switch]$RefreshTheme,
        [string[]]$ProfilePath
    )
    $themeChanged = $false
    if ($PromptId -eq "oh-my-posh") {
        $themeFile = Get-WinToolOhMyPoshThemeFile -PromptStyle $PromptStyle
        $before = $false
        if (-not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
            $themePath = Join-Path $env:LOCALAPPDATA ("WinTool\themes\" + $themeFile)
            $before = (Test-Path -LiteralPath $themePath)
        }
        if ($RefreshTheme) {
            $saved = Save-WinToolOhMyPoshTheme -ThemeFile $themeFile
        }
        else {
            $saved = Save-WinToolOhMyPoshTheme -ThemeFile $themeFile -SkipIfPresent
        }
        if ($RefreshTheme -and $null -ne $saved) {
            $themeChanged = $true
        }
        elseif (-not $before -and $null -ne $saved) {
            $themeChanged = $true
        }
    }
    $body = Get-WinToolPromptScript -PromptId $PromptId -TerminalIcons $TerminalIcons -PromptStyle $PromptStyle -PsReadLine $PsReadLine -Zoxide $Zoxide
    $paths = @($ProfilePath | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    if ($paths.Count -eq 0) {
        $paths = @(
            (Get-WinToolShellProfilePath -HostName "powershell"),
            (Get-WinToolShellProfilePath -HostName "pwsh")
        )
    }
    $profileChanged = $false
    foreach ($path in $paths) {
        $directory = Split-Path -Parent $path
        if (-not (Test-Path -LiteralPath $directory)) {
            New-Item -ItemType Directory -Path $directory -Force | Out-Null
        }
        $existing = ""
        if (Test-Path -LiteralPath $path) {
            $existing = [System.IO.File]::ReadAllText($path)
        }
        $updated = Update-WinToolManagedBlock -Text $existing -Begin $script:WinToolProfileBegin -End $script:WinToolProfileEnd -Body $body
        if ($updated -eq $existing) {
            continue
        }
        Write-WinToolUtf8File -Path $path -Text $updated -Bom
        Write-WinToolLog -Message (Get-WinToolText "msg.updated-n" $path) -Level "ok"
        $profileChanged = $true
    }
    if (-not $profileChanged -and -not $themeChanged) {
        Write-WinToolLog -Message (Get-WinToolText "msg.the-powershell-profiles-were-already-up-to-date") -Level "ok"
    }
    elseif (-not $profileChanged -and $themeChanged) {
        Write-WinToolLog -Message (Get-WinToolText "msg.refreshed-the-oh-my-posh-theme-the-powershell-profiles-w") -Level "ok"
    }
    return ($profileChanged -or $themeChanged)
}

function ConvertTo-WinToolFontToken {
    param(
        [AllowEmptyString()][string]$Text
    )
    return ([string]$Text).ToLowerInvariant().Replace(" ", "").Replace("-", "").Replace("_", "")
}

function Find-WinToolInstalledFontFile {
    param(
        [Parameter(Mandatory = $true)][string]$Token,
        [object[]]$Entry
    )
    # Entries are registry font values: Name like "CaskaydiaCoveNerdFont-Regular
    # (TrueType)", Data the file. The regular style is preferred, and the
    # proportional Nerd Font variant is skipped when another one exists.
    if ($null -eq $Entry) {
        $Entry = @(Get-WinToolRegisteredFont)
    }
    $want = ConvertTo-WinToolFontToken -Text $Token
    if ([string]::IsNullOrWhiteSpace($want)) {
        return $null
    }
    $hits = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($Entry)) {
        $name = ConvertTo-WinToolFontToken -Text ([string]$item.Name)
        $file = ConvertTo-WinToolFontToken -Text ([System.IO.Path]::GetFileName([string]$item.Data))
        if ($name.Contains($want) -or $file.Contains($want)) {
            $hits.Add($item)
        }
    }
    if ($hits.Count -eq 0) {
        return $null
    }
    $best = $null
    $bestScore = -1
    foreach ($item in $hits) {
        $text = ConvertTo-WinToolFontToken -Text ([string]$item.Name)
        $score = 0
        if ($text.Contains("regular")) { $score += 2 }
        if (-not $text.Contains("propo")) { $score += 1 }
        # Mono is the terminal face. Proportional and Propo stay usable, just behind it.
        if ($text.Contains("mono") -and -not $text.Contains("propo")) { $score += 1 }
        if ($score -gt $bestScore) {
            $best = $item
            $bestScore = $score
        }
    }
    return $best
}

function Get-WinToolRegisteredFont {
    if (-not (Test-WinToolWindows)) {
        return @()
    }
    if ($null -ne $script:WinToolRegisteredFontCache) {
        return @($script:WinToolRegisteredFontCache)
    }
    $list = New-Object System.Collections.Generic.List[object]
    $sources = @(
        @{ Key = "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts"; Folder = (Join-Path $env:windir "Fonts"); Source = "HKLM" },
        @{ Key = "HKCU:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts"; Folder = (Join-Path $env:LOCALAPPDATA "Microsoft\Windows\Fonts"); Source = "HKCU" }
    )
    foreach ($source in $sources) {
        if (-not (Test-Path -LiteralPath $source.Key)) {
            continue
        }
        $item = Get-Item -LiteralPath $source.Key
        foreach ($name in @($item.GetValueNames())) {
            if ([string]::IsNullOrWhiteSpace([string]$name)) {
                continue
            }
            $data = [string]$item.GetValue($name)
            if (-not [string]::IsNullOrWhiteSpace($data) -and -not [System.IO.Path]::IsPathRooted($data)) {
                $data = Join-Path $source.Folder $data
            }
            $list.Add([pscustomobject]@{ Name = [string]$name; Data = $data; Source = [string]$source.Source })
        }
    }
    $script:WinToolRegisteredFontCache = $list.ToArray()
    return @($script:WinToolRegisteredFontCache)
}

function Get-WinToolFontFamilyName {
    param(
        [string]$Path
    )
    # The family name inside the file is what Terminal needs in "face".
    if ([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path)) {
        return $null
    }
    try {
        Add-Type -AssemblyName PresentationCore
        $glyph = New-Object System.Windows.Media.GlyphTypeface ([uri]$Path)
        $names = $glyph.Win32FamilyNames
        $english = [System.Globalization.CultureInfo]::GetCultureInfo("en-US")
        if ($names.ContainsKey($english)) {
            return [string]$names[$english]
        }
        foreach ($value in $names.Values) {
            return [string]$value
        }
    }
    catch {
        $null = $_.Exception.Message
    }
    return $null
}

function Reset-WinToolFontResolution {
    # Drop cached faces after a font is installed or removed. The theme list
    # rebuilds its pictures the next time the preview font changes.
    $script:WinToolRegisteredFontCache = $null
    $script:WinToolLoadedFontCache = $null
    $script:WinToolGlyphCache = $null
    $script:WinToolFileFamilyCache = $null
    $script:WinToolResolvedFontMap = $null
    $script:WinToolPreviewFontChain = $null
    $script:WinToolPreviewFontChainKey = $null
    $script:WinToolThemePreviewFontKey = $null
    Reset-WinToolPreviewDrawCache
}

function Reset-WinToolPreviewDrawCache {
    # Outline and picture caches are filled while painting. Drop them when a
    # font is installed or a test wants a cold measurement.
    if ($null -ne ("WinToolGlyphDraw" -as [type])) { [WinToolGlyphDraw]::Clear() }
    $script:WinToolPreviewImageCache = @{}
    $script:WinToolCoveredTextCache = @{}
    $script:WinToolLivePreviewCache = @{}
    $script:WinToolThemeImageByKey = @{}
    $script:WinToolLastPreviewDrawn = @()
}

function Get-WinToolTextCode {
    param(
        [AllowEmptyString()][string]$Text
    )
    # One UTF-32 codepoint per item, so an emoji is not split into surrogates.
    $codes = New-Object System.Collections.Generic.List[int]
    $chars = ([string]$Text).ToCharArray()
    for ($index = 0; $index -lt $chars.Length; $index++) {
        $char = $chars[$index]
        if ([char]::IsHighSurrogate($char) -and ($index + 1) -lt $chars.Length -and [char]::IsLowSurrogate($chars[$index + 1])) {
            $codes.Add([char]::ConvertToUtf32($char, $chars[$index + 1]))
            $index++
        }
        else {
            $codes.Add([int]$char)
        }
    }
    return $codes.ToArray()
}

function ConvertTo-WinToolGlyphFallback {
    param(
        [int]$Code
    )
    # Used only when no loaded face has the codepoint. The result is ASCII,
    # so Consolas can draw it and the preview never shows an empty box.
    if ($null -eq $script:WinToolGlyphFallback) {
        $map = @{}
        # code=ascii, one row each. A nested array would be flattened by PowerShell.
        $rows = @"
00BB=>
03BB=L
2039=<
203A=>
2261==
2302=^
2500=-
250C=+
256D=+
2591=.
2592=:
2593=#
25B3=^
25B6=>
25C9=*
25CE=o
2665=<3
276F=>
279C=>
27A4=>
2B22=*
E0A0=git
E0B0=>
E0B1=>
E0B2=<
E0B4=>
E0B6=<
E0B8=>
E0BA=<
E0C4=>
E0C5=<
E0C6=>
E0C7=<
E0D7=/
E70F=ps
E718=js
E795=>
E7AD=py
F07B=/
F07C=/
F105=>
F126=git
F418=git
F432=>
F43A=:
F489=.
1F3E0=home
1F4AC=msg
1F600=:)
"@
        foreach ($row in ($rows -split "`n")) {
            $line = $row.Trim()
            if ([string]::IsNullOrWhiteSpace($line)) { continue }
            $splitAt = $line.IndexOf("=")
            $map[[Convert]::ToInt32($line.Substring(0, $splitAt), 16)] = $line.Substring($splitAt + 1)
        }
        $script:WinToolGlyphFallback = $map
    }
    $key = [int]$Code
    if ($script:WinToolGlyphFallback.ContainsKey($key)) {
        return [string]$script:WinToolGlyphFallback[$key]
    }
    if (($key -ge 0xE000 -and $key -le 0xF8FF) -or $key -gt 0xFFFF) {
        return ">"
    }
    return $null
}

function Add-WinToolPreviewSampleValue {
    param(
        $Value,
        $List
    )
    if ($null -eq $Value -or $Value -is [string] -or $Value -is [ValueType]) { return }
    if ($Value -is [System.Collections.IEnumerable]) {
        foreach ($item in @($Value)) {
            Add-WinToolPreviewSampleValue -Value $item -List $List
        }
        return
    }
    foreach ($property in @($Value.PSObject.Properties)) {
        $name = [string]$property.Name
        if (($name -eq "text" -or $name -eq "Text") -and $property.Value -is [string] -and -not [string]::IsNullOrEmpty([string]$property.Value)) {
            [void]$List.Add([string]$property.Value)
        }
        else {
            Add-WinToolPreviewSampleValue -Value $property.Value -List $List
        }
    }
}

function Get-WinToolPreviewSampleText {
    # Every string the prompt previews draw, including the folder and file
    # icons on the live sample. Callers use this to check glyph coverage.
    $list = New-Object System.Collections.Generic.List[string]
    Add-WinToolPreviewSampleValue -Value (Get-WinToolOhMyPoshDocument) -List $list
    Add-WinToolPreviewSampleValue -Value (Get-WinToolTerminalCatalog) -List $list
    [void]$list.Add([string][char]0xF07B)
    [void]$list.Add([string][char]0xF489)
    [void]$list.Add([string][char]0xE0B0)
    return $list.ToArray()
}

function Get-WinToolGlyphFamilyName {
    param(
        $Glyph,
        [string]$Table = "family",
        [switch]$All
    )
    # Every stored family name when -All is set. The file URI has to use the
    # one WPF accepts, and the two name tables do not always agree.
    if ($null -eq $Glyph) {
        if ($All) { return @() }
        return $null
    }
    # The file URI wants the Win32 name more often than the typographic one.
    if ($All) { $tables = @($Glyph.Win32FamilyNames, $Glyph.FamilyNames) }
    elseif ($Table -eq "win32") { $tables = @($Glyph.Win32FamilyNames) }
    else { $tables = @($Glyph.FamilyNames) }
    $found = New-Object System.Collections.Generic.List[string]
    foreach ($names in $tables) {
        if ($null -eq $names) { continue }
        if (-not $All) {
            $english = [System.Globalization.CultureInfo]::GetCultureInfo("en-US")
            if ($names.ContainsKey($english)) { return [string]$names[$english] }
            foreach ($value in $names.Values) { return [string]$value }
            return $null
        }
        foreach ($value in @($names.Values)) {
            $name = [string]$value
            if ([string]::IsNullOrWhiteSpace($name)) { continue }
            if (-not $found.Contains($name)) { [void]$found.Add($name) }
        }
    }
    if ($All) { return $found.ToArray() }
    return $null
}

function Get-WinToolTypefaceGlyph {
    param($Typeface)
    if ($null -eq $Typeface) { return $null }
    $loaded = $null
    $ok = $false
    try {
        $ok = $Typeface.TryGetGlyphTypeface([ref]$loaded)
    }
    catch {
        $null = $_.Exception.Message
        return $null
    }
    if (-not $ok -or $null -eq $loaded) { return $null }
    return $loaded
}

function Initialize-WinToolGlyphMap {
    # PowerShell's call into CharacterToGlyphMap is unreliable on 5.1.
    # Glyph 0 is the font's empty box, so a codepoint that maps to it is missing.
    if ($null -ne ("WinToolGlyphMap" -as [type])) { return }
    Add-Type -AssemblyName PresentationCore
    $null = Add-WinToolCSharpType -Name "WinToolGlyphMap" -ReferenceType @([object], [System.Windows.Media.GlyphTypeface]) -TypeDefinition @"
using System.Windows.Media;
public static class WinToolGlyphMap {
    public static bool Has(GlyphTypeface face, int code) {
        if (face == null) return false;
        ushort index;
        return face.CharacterToGlyphMap.TryGetValue(code, out index) && index > 0;
    }
}
"@
}

function Test-WinToolGlyphMapped {
    param(
        $Glyph,
        [int]$Code
    )
    if ($null -eq $Glyph -or -not (Test-WinToolWindows)) { return $false }
    Initialize-WinToolGlyphMap
    return [WinToolGlyphMap]::Has($Glyph, [int]$Code)
}

function Initialize-WinToolGlyphDraw {
    # GlyphRun and GetGlyphOutline live here so previews can paint a file
    # face without going through FontFamily by name.
    if ($null -ne ("WinToolGlyphDraw" -as [type])) { return }
    Add-Type -AssemblyName PresentationCore
    Add-Type -AssemblyName WindowsBase
    $null = Add-WinToolCSharpType -Name "WinToolGlyphDraw" -ReferenceType @([object], [System.Windows.Media.GlyphTypeface], [System.Windows.Point]) -TypeDefinition @"
using System;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Media;
public static class WinToolGlyphDraw {
    static readonly Dictionary<string, Dictionary<int, bool>> OutlineCache = new Dictionary<string, Dictionary<int, bool>>(StringComparer.OrdinalIgnoreCase);

    static string FaceKey(GlyphTypeface face) {
        if (face == null) return "";
        try {
            Uri uri = face.FontUri;
            if (uri != null) return uri.ToString();
        }
        catch {
        }
        return "h:" + face.GetHashCode().ToString();
    }

    public static void Clear() {
        OutlineCache.Clear();
    }

    public static bool HasOutline(GlyphTypeface face, int code) {
        if (face == null) return false;
        string key = FaceKey(face);
        Dictionary<int, bool> map;
        if (!OutlineCache.TryGetValue(key, out map)) {
            map = new Dictionary<int, bool>();
            OutlineCache[key] = map;
        }
        bool cached;
        if (map.TryGetValue(code, out cached)) return cached;
        bool drawn = MeasureOutline(face, code);
        map[code] = drawn;
        return drawn;
    }

    static bool MeasureOutline(GlyphTypeface face, int code) {
        ushort index;
        if (!face.CharacterToGlyphMap.TryGetValue(code, out index) || index == 0) return false;
        try {
            Geometry geometry = face.GetGlyphOutline(index, 12.0, 12.0);
            if (geometry == null || geometry.IsEmpty()) return false;
            Rect bounds = geometry.Bounds;
            return bounds.Width > 0.15 || bounds.Height > 0.15;
        }
        catch {
            return false;
        }
    }

    public static GlyphRun MakeRun(GlyphTypeface face, int[] codes, double emSize, double x, double y) {
        if (face == null || codes == null || codes.Length == 0 || emSize <= 0) return null;
        List<ushort> indices = new List<ushort>();
        List<double> advances = new List<double>();
        for (int i = 0; i < codes.Length; i++) {
            ushort index;
            if (!face.CharacterToGlyphMap.TryGetValue(codes[i], out index) || index == 0) continue;
            indices.Add(index);
            advances.Add(face.AdvanceWidths[index] * emSize);
        }
        if (indices.Count == 0) return null;
        return new GlyphRun(
            face,
            0,
            false,
            emSize,
            1.0f,
            indices,
            new Point(x, y),
            advances,
            null,
            null,
            null,
            null,
            null,
            null);
    }

    public static double Measure(GlyphTypeface face, int[] codes, double emSize) {
        if (face == null || codes == null || emSize <= 0) return 0;
        double width = 0;
        for (int i = 0; i < codes.Length; i++) {
            ushort index;
            if (!face.CharacterToGlyphMap.TryGetValue(codes[i], out index) || index == 0) continue;
            width += face.AdvanceWidths[index] * emSize;
        }
        return width;
    }

    public static double LineHeight(GlyphTypeface face, double emSize) {
        if (face == null || emSize <= 0) return emSize;
        double height = face.Height * emSize;
        if (height <= 0) return emSize * 1.2;
        return height;
    }

    public static double Baseline(GlyphTypeface face, double emSize) {
        if (face == null || emSize <= 0) return emSize * 0.8;
        double baseline = face.Baseline * emSize;
        if (baseline <= 0) return emSize * 0.8;
        return baseline;
    }
}
"@
}

function Test-WinToolGlyphDrawable {
    param(
        $Glyph,
        [int]$Code
    )
    # A cmap hit is not enough: some faces reserve a private-use slot and
    # still draw an empty box. Spaces are advance-only and have no outline.
    if (-not (Test-WinToolGlyphMapped -Glyph $Glyph -Code $Code)) { return $false }
    if ($Code -eq 0x20 -or $Code -eq 0xA0 -or $Code -eq 0x3000) { return $true }
    Initialize-WinToolGlyphDraw
    return [WinToolGlyphDraw]::HasOutline($Glyph, [int]$Code)
}

function Test-WinToolSameFontFile {
    param(
        $Glyph,
        [string]$Path
    )
    # TryGetGlyphTypeface can hand back a different installed face. The preview
    # only keeps a family whose glyph file is the one that was opened.
    if ($null -eq $Glyph -or [string]::IsNullOrWhiteSpace($Path)) { return $false }
    $fontUri = $null
    try { $fontUri = $Glyph.FontUri } catch { $null = $_.Exception.Message; return $false }
    if ($null -eq $fontUri -or -not $fontUri.IsFile) { return $false }
    try {
        $left = [System.IO.Path]::GetFullPath($fontUri.LocalPath)
        $right = [System.IO.Path]::GetFullPath($Path)
        return $left.Equals($right, [System.StringComparison]::OrdinalIgnoreCase)
    }
    catch {
        $null = $_.Exception.Message
        return $false
    }
}

function Get-WinToolFontFolderUri {
    param(
        [Parameter(Mandatory = $true)][string]$Path
    )
    # WPF wants the folder, with a trailing slash, as the base URI.
    $full = [System.IO.Path]::GetFullPath($Path)
    $folder = [System.IO.Path]::GetDirectoryName($full)
    $slash = [System.IO.Path]::DirectorySeparatorChar
    if (-not $folder.EndsWith([string]$slash) -and -not $folder.EndsWith("/")) {
        $folder = $folder + $slash
    }
    return New-Object System.Uri -ArgumentList $folder, ([System.UriKind]::Absolute)
}

function Test-WinToolFileTypeface {
    param(
        [string]$Path,
        [string]$FamilyName
    )
    if ([string]::IsNullOrWhiteSpace($Path) -or [string]::IsNullOrWhiteSpace($FamilyName)) { return $null }
    if ($null -eq $script:WinToolFileFamilyCache) { $script:WinToolFileFamilyCache = @{} }
    $full = [System.IO.Path]::GetFullPath($Path)
    $fileName = [System.IO.Path]::GetFileName($full)
    $baseUri = $null
    try {
        $baseUri = Get-WinToolFontFolderUri -Path $full
    }
    catch {
        $null = $_.Exception.Message
        return $null
    }
    # Folder URI plus ./file.ttf#Family is the documented WPF form. ./#Family
    # loads any face in that folder and is the fallback when the file name
    # is not accepted.
    $forms = @(
        ("./" + $fileName + "#" + $FamilyName),
        ("./#" + $FamilyName)
    )
    foreach ($form in $forms) {
        $familyKey = $full + "|" + $form
        $family = $null
        if ($script:WinToolFileFamilyCache.ContainsKey($familyKey)) {
            $family = $script:WinToolFileFamilyCache[$familyKey]
        }
        else {
            try {
                $family = New-Object System.Windows.Media.FontFamily -ArgumentList $baseUri, $form
            }
            catch {
                $null = $_.Exception.Message
                $family = $null
            }
            # FontFamily is not freezable. The object itself is the cache.
            $script:WinToolFileFamilyCache[$familyKey] = $family
        }
        if ($null -eq $family) { continue }
        $typeface = $null
        $drawn = $null
        try {
            $typeface = New-Object System.Windows.Media.Typeface(
                $family,
                [System.Windows.FontStyles]::Normal,
                [System.Windows.FontWeights]::Normal,
                [System.Windows.FontStretches]::Normal)
            $drawn = Get-WinToolTypefaceGlyph -Typeface $typeface
        }
        catch {
            $null = $_.Exception.Message
            $drawn = $null
        }
        if ($null -eq $drawn) { continue }
        if (-not (Test-WinToolSameFontFile -Glyph $drawn -Path $Path)) { continue }
        if ($drawn.CanFreeze) {
            try { $drawn.Freeze() } catch { $null = $_.Exception.Message }
        }
        return [pscustomobject]@{ Family = $family; Typeface = $typeface; Glyph = $drawn }
    }
    return $null
}

function New-WinToolLoadedFont {
    param(
        [Parameter(Mandatory = $true)][string]$Path,
        [bool]$Nerd = $false,
        [string]$Id = "",
        [string]$Face = "",
        [string]$Name = "",
        [string]$Source = ""
    )
    # WPF does not see per-user fonts by family name. The face is opened
    # from the file, and FontFamily uses the folder URI plus ./file.ttf#Name.
    if ([string]::IsNullOrWhiteSpace($Path) -or -not (Test-Path -LiteralPath $Path)) { return $null }
    if ($null -eq $script:WinToolLoadedFontCache) { $script:WinToolLoadedFontCache = @{} }
    $cacheKey = $Path + "|" + $Id
    if ($script:WinToolLoadedFontCache.ContainsKey($cacheKey)) {
        return $script:WinToolLoadedFontCache[$cacheKey]
    }
    $record = $null
    try {
        Add-Type -AssemblyName PresentationCore
        if ($null -eq $script:WinToolGlyphCache) { $script:WinToolGlyphCache = @{} }
        $glyph = $null
        if ($script:WinToolGlyphCache.ContainsKey($Path)) {
            $glyph = $script:WinToolGlyphCache[$Path]
        }
        else {
            $glyph = New-Object System.Windows.Media.GlyphTypeface ([uri]$Path)
            $script:WinToolGlyphCache[$Path] = $glyph
        }
        if ($glyph.CanFreeze) {
            try { $glyph.Freeze() } catch { $null = $_.Exception.Message }
        }
        $loadedFace = $null
        foreach ($familyName in @(Get-WinToolGlyphFamilyName -Glyph $glyph -All)) {
            $loadedFace = Test-WinToolFileTypeface -Path $Path -FamilyName $familyName
            if ($null -ne $loadedFace) { break }
        }
        if ($null -eq $loadedFace) { throw (Get-WinToolText "msg.the-font-file-did-not-load") }
        $family = $loadedFace.Family
        $typeface = $loadedFace.Typeface
        $drawn = $loadedFace.Glyph
        $record = [pscustomobject]@{
            Id = $Id
            Face = $Face
            Name = $Name
            Path = $Path
            Source = $Source
            FamilyName = ""
            Family = $family
            Typeface = $typeface
            Glyph = $drawn
            Nerd = [bool]$Nerd
        }
        try {
            $record.FamilyName = [string](Get-WinToolGlyphFamilyName -Glyph $glyph -Table "win32")
            if ([string]::IsNullOrWhiteSpace([string]$record.FamilyName)) {
                $record.FamilyName = [string](Get-WinToolGlyphFamilyName -Glyph $glyph -Table "family")
            }
        }
        catch {
            $null = $_.Exception.Message
        }
    }
    catch {
        $null = $_.Exception.Message
        $record = $null
    }
    $script:WinToolLoadedFontCache[$cacheKey] = $record
    return $record
}

function Test-WinToolNerdFontRecord {
    param(
        $Record,
        [string]$RegistryName
    )
    if ($null -eq $Record) { return $false }
    $blob = ConvertTo-WinToolFontToken -Text (([string]$Record.FamilyName) + " " + $RegistryName + " " + [System.IO.Path]::GetFileName([string]$Record.Path))
    return $blob.Contains("nerd")
}

function Get-WinToolResolvedFontMap {
    if ($null -ne $script:WinToolResolvedFontMap) { return $script:WinToolResolvedFontMap }
    $map = @{}
    if (Test-WinToolWindows) {
        $registered = @(Get-WinToolRegisteredFont)
        $fonts = @(Get-WinToolNote -Object (Get-WinToolFontDocument) -Name "fonts" -Default @())
        foreach ($extra in @($script:WinToolExtraFont)) {
            if ($null -ne $extra) { $fonts += $extra }
        }
        foreach ($font in $fonts) {
            $match = [string](Get-WinToolNote -Object $font -Name "match" -Default "")
            if ([string]::IsNullOrWhiteSpace($match)) { $match = [string]$font.face }
            $found = Find-WinToolInstalledFontFile -Token $match -Entry $registered
            if ($null -eq $found) { continue }
            $nerd = ($null -ne $font.PSObject.Properties["nerd"] -and [bool]$font.nerd)
            $loaded = New-WinToolLoadedFont -Path ([string]$found.Data) -Nerd $nerd -Id ([string]$font.id) -Face ([string]$font.face) -Name ([string]$font.name) -Source ([string]$found.Source)
            if ($null -eq $loaded) { continue }
            if ($nerd -and -not (Test-WinToolNerdFontRecord -Record $loaded -RegistryName ([string]$found.Name))) { continue }
            $map[[string]$font.id] = $loaded
        }
    }
    $script:WinToolResolvedFontMap = $map
    return $map
}

function Get-WinToolResolvableFont {
    # Catalog rows whose font file opened. The dropdown lists only these.
    $map = Get-WinToolResolvedFontMap
    $rows = New-Object System.Collections.Generic.List[object]
    foreach ($font in @(Get-WinToolActiveFont)) {
        if ($map.ContainsKey([string]$font.id)) { [void]$rows.Add($font) }
    }
    return $rows.ToArray()
}

function Test-WinToolFontResolve {
    param(
        [Parameter(Mandatory = $true)][string]$Id
    )
    return (Get-WinToolResolvedFontMap).ContainsKey($Id)
}

function Get-WinToolSystemFont {
    param(
        [Parameter(Mandatory = $true)][string]$Token,
        [Parameter(Mandatory = $true)][string]$FileName
    )
    if (-not (Test-WinToolWindows)) { return $null }
    $path = ""
    $source = "HKLM"
    $found = Find-WinToolInstalledFontFile -Token $Token
    if ($null -ne $found -and -not [string]::IsNullOrWhiteSpace([string]$found.Data) -and (Test-Path -LiteralPath ([string]$found.Data))) {
        $path = [string]$found.Data
        $source = [string]$found.Source
    }
    if ([string]::IsNullOrWhiteSpace($path)) {
        $candidate = Join-Path (Join-Path $env:windir "Fonts") $FileName
        if (Test-Path -LiteralPath $candidate) { $path = $candidate }
    }
    if ([string]::IsNullOrWhiteSpace($path)) { return $null }
    return (New-WinToolLoadedFont -Path $path -Nerd $false -Id $Token -Face $Token -Name $Token -Source $source)
}

function Get-WinToolBestNerdFont {
    # Prefer CaskaydiaCove Nerd Font Mono, then the proportional Cove face,
    # then any other installed Nerd Font.
    $map = Get-WinToolResolvedFontMap
    $best = $null
    $bestScore = -1
    foreach ($id in @($map.Keys)) {
        $record = $map[$id]
        if ($null -eq $record -or -not $record.Nerd) { continue }
        $family = [string]$record.FamilyName
        $score = 1
        if ($family -eq "CaskaydiaCove Nerd Font Mono") { $score += 100 }
        elseif ($family -eq "CaskaydiaCove Nerd Font") { $score += 80 }
        elseif ([string]$id -eq "cascadiacode-nf") { $score += 60 }
        elseif ([string]$id -eq "cascadiamono-nf") { $score += 40 }
        if ($family.IndexOf("Mono", [System.StringComparison]::OrdinalIgnoreCase) -ge 0 -and $family.IndexOf("Propo", [System.StringComparison]::OrdinalIgnoreCase) -lt 0) {
            $score += 10
        }
        if ($score -gt $bestScore) {
            $best = $record
            $bestScore = $score
        }
    }
    return $best
}

function Get-WinToolPreviewFontKey {
    $selectedId = ""
    if ($null -ne $script:WinToolTerminalChoice) { $selectedId = [string]$script:WinToolTerminalChoice.fontId }
    $bestPath = ""
    $best = Get-WinToolBestNerdFont
    if ($null -ne $best) { $bestPath = [string]$best.Path }
    return ($selectedId + "|" + $bestPath)
}

function Get-WinToolPreviewFontChain {
    # Selected Nerd Font, then the best installed Nerd Font, then faces that
    # cover symbols, emoji, and ASCII. Missing codepoints are substituted.
    $key = Get-WinToolPreviewFontKey
    if ($key -eq [string]$script:WinToolPreviewFontChainKey -and $null -ne $script:WinToolPreviewFontChain) {
        return @($script:WinToolPreviewFontChain)
    }
    $list = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    $selectedId = ""
    if ($null -ne $script:WinToolTerminalChoice) { $selectedId = [string]$script:WinToolTerminalChoice.fontId }
    $map = Get-WinToolResolvedFontMap
    $candidates = New-Object System.Collections.Generic.List[object]
    if (-not [string]::IsNullOrWhiteSpace($selectedId) -and $map.ContainsKey($selectedId)) {
        [void]$candidates.Add($map[$selectedId])
    }
    $bestNerd = Get-WinToolBestNerdFont
    if ($null -ne $bestNerd) { [void]$candidates.Add($bestNerd) }
    foreach ($systemFont in @(
            (Get-WinToolSystemFont -Token "Segoe UI Symbol" -FileName "seguisym.ttf"),
            (Get-WinToolSystemFont -Token "Segoe UI Emoji" -FileName "seguiemj.ttf"),
            (Get-WinToolSystemFont -Token "Consolas" -FileName "consola.ttf")
        )) {
        if ($null -ne $systemFont) { [void]$candidates.Add($systemFont) }
    }
    foreach ($record in $candidates) {
        $path = [string]$record.Path
        if ([string]::IsNullOrWhiteSpace($path) -or $seen.ContainsKey($path)) { continue }
        $seen[$path] = $true
        [void]$list.Add($record)
    }
    if ($list.Count -eq 0 -and (Test-WinToolWindows)) {
        try {
            Add-Type -AssemblyName PresentationCore
            $family = [System.Windows.Media.FontFamily]::new("Consolas")
            $typeface = New-Object System.Windows.Media.Typeface(
                $family,
                [System.Windows.FontStyles]::Normal,
                [System.Windows.FontWeights]::Normal,
                [System.Windows.FontStretches]::Normal)
            $glyph = Get-WinToolTypefaceGlyph -Typeface $typeface
            if ($null -ne $glyph) {
                [void]$list.Add([pscustomobject]@{
                    Id = "Consolas"; Face = "Consolas"; Name = "Consolas"; Path = "Consolas"; Source = "name"
                    FamilyName = "Consolas"; Family = $family; Typeface = $typeface; Glyph = $glyph; Nerd = $false
                })
            }
        }
        catch {
            $null = $_.Exception.Message
        }
    }
    $script:WinToolPreviewFontChain = $list.ToArray()
    $script:WinToolPreviewFontChainKey = $key
    return @($script:WinToolPreviewFontChain)
}

function Split-WinToolCoveredText {
    param(
        [AllowEmptyString()][string]$Text
    )
    # Break the text into runs that each fit one loaded face. A codepoint no
    # face can draw is replaced with ASCII before it becomes an empty box.
    $result = New-Object System.Collections.Generic.List[object]
    if ([string]::IsNullOrEmpty($Text)) { return @() }
    if ($null -eq $script:WinToolCoveredTextCache) { $script:WinToolCoveredTextCache = @{} }
    $coverKey = (Get-WinToolPreviewFontKey) + "`n" + $Text
    if ($script:WinToolCoveredTextCache.ContainsKey($coverKey)) {
        return @($script:WinToolCoveredTextCache[$coverKey])
    }
    $chain = @(Get-WinToolPreviewFontChain)
    $builder = New-Object System.Text.StringBuilder
    $current = $null
    foreach ($code in @(Get-WinToolTextCode -Text $Text)) {
        $privateUse = ($code -ge 0xE000 -and $code -le 0xF8FF)
        $face = $null
        foreach ($item in $chain) {
            # A system face can claim a private-use slot and still draw an empty
            # box. Those icons stay only when the face is a Nerd Font.
            if ($privateUse -and -not $item.Nerd) { continue }
            if (Test-WinToolGlyphDrawable -Glyph $item.Glyph -Code $code) { $face = $item; break }
        }
        $chunk = [char]::ConvertFromUtf32($code)
        if ($null -eq $face) {
            $chunk = ConvertTo-WinToolGlyphFallback -Code $code
            if ([string]::IsNullOrEmpty($chunk)) { $chunk = ">" }
            foreach ($item in $chain) {
                $fits = $true
                foreach ($part in @(Get-WinToolTextCode -Text $chunk)) {
                    if (-not (Test-WinToolGlyphDrawable -Glyph $item.Glyph -Code $part)) { $fits = $false; break }
                }
                if ($fits) { $face = $item; break }
            }
            if ($null -eq $face -and $chain.Count -gt 0) { $face = $chain[$chain.Count - 1] }
        }
        if ($null -eq $face) { continue }
        $same = ($null -ne $current -and [string]$current.Path -eq [string]$face.Path)
        if (-not $same) {
            if ($builder.Length -gt 0 -and $null -ne $current) {
                [void]$result.Add([pscustomobject]@{
                    Text = $builder.ToString()
                    Path = [string]$current.Path
                    Family = $current.Family
                    Typeface = $current.Typeface
                    Glyph = $current.Glyph
                })
            }
            [void]$builder.Clear()
            $current = $face
        }
        [void]$builder.Append($chunk)
    }
    if ($builder.Length -gt 0 -and $null -ne $current) {
        [void]$result.Add([pscustomobject]@{
            Text = $builder.ToString()
            Path = [string]$current.Path
            Family = $current.Family
            Typeface = $current.Typeface
            Glyph = $current.Glyph
        })
    }
    $pieces = $result.ToArray()
    if ($script:WinToolCoveredTextCache.Count -lt 1024) {
        $script:WinToolCoveredTextCache[$coverKey] = $pieces
    }
    return $pieces
}

function Test-WinToolPreviewTextCovered {
    param(
        [AllowEmptyString()][string]$Text
    )
    if ([string]::IsNullOrEmpty($Text)) { return $true }
    $pieces = @(Split-WinToolCoveredText -Text $Text)
    if ($pieces.Count -eq 0) { return $false }
    foreach ($piece in $pieces) {
        $pieceText = [string]$piece.Text
        if ([string]::IsNullOrEmpty($pieceText)) { return $false }
        foreach ($code in @(Get-WinToolTextCode -Text $pieceText)) {
            if (-not (Test-WinToolGlyphDrawable -Glyph $piece.Glyph -Code $code)) { return $false }
        }
    }
    return $true
}

function Sync-WinToolPreviewGlyphCache {
    # Fill the outline cache for the visible theme samples and the live
    # preview alphabet so a later click does not call GetGlyphOutline.
    $builder = New-Object System.Text.StringBuilder
    foreach ($row in @($script:WinToolTerminalRows)) {
        if ($null -eq $row) { continue }
        foreach ($segment in @($row.Preview)) {
            if ($null -ne $segment) { [void]$builder.Append([string]$segment.Text) }
        }
    }
    [void]$builder.Append(" PowerShell 7 Ubuntu on WSL zsh fish git status On branch main Changes not staged for commit: modified: src/app.ts const same = (a, b) => a === b || a >= b; cd wintool z wintool ls assets build data src wintool.ps1 head -1 ")
    if ($builder.Length -eq 0) { return }
    $null = Split-WinToolCoveredText -Text $builder.ToString()
}

function Resolve-WinToolInstalledFontFace {
    param(
        [Parameter(Mandatory = $true)][string]$Face,
        [string]$Match
    )
    # Returns the face to write into Terminal settings, or $null (with a
    # warning) when the font is not installed.
    $chosen = $Face
    if (-not [string]::IsNullOrWhiteSpace($Match) -and (Test-WinToolWindows)) {
        $found = Find-WinToolInstalledFontFile -Token $Match
        if ($null -eq $found) {
            Write-WinToolLog -Message ((Get-WinToolText "msg.n-is-not-installed-so-the-windows-terminal-font-was-left") -f $Face) -Level "warn"
            return $null
        }
        $family = Get-WinToolFontFamilyName -Path ([string]$found.Data)
        if (-not [string]::IsNullOrWhiteSpace($family)) {
            $chosen = $family
        }
        if ($chosen -ne $Face) {
            Write-WinToolLog -Message (Get-WinToolText "msg.using-the-installed-font-name-n" $chosen) -Level "info"
        }
    }
    return $chosen
}

function Invoke-WinToolTerminalFont {
    param(
        [Parameter(Mandatory = $true)][string]$Face,
        [string]$Match,
        [int]$Size = 12,
        [string[]]$SettingsPath
    )
    if ($Size -lt 6 -or $Size -gt 48) { $Size = 12 }
    $chosen = Resolve-WinToolInstalledFontFace -Face $Face -Match $Match
    if ($null -eq $chosen) {
        return $false
    }
    $paths = @($SettingsPath | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    if ($paths.Count -eq 0) {
        $paths = @(Get-WinToolTerminalSettingsPathList)
    }
    if ($paths.Count -eq 0) {
        Write-WinToolLog -Message (Get-WinToolText "msg.windows-terminal-settings-were-not-found-open-terminal-o-2") -Level "warn"
        return $false
    }
    $any = $false
    foreach ($path in $paths) {
        $raw = "{}"
        if (Test-Path -LiteralPath $path) {
            $raw = [System.IO.File]::ReadAllText($path)
            if ([string]::IsNullOrWhiteSpace($raw)) { $raw = "{}" }
        }
        $settings = $null
        try {
            $settings = ConvertFrom-WinToolJsonText -Text $raw
        }
        catch {
            $settings = $null
        }
        if ($null -ne $settings -and (Test-WinToolSettingsFontMatch -Settings $settings -Face $chosen -Size $Size)) {
            continue
        }
        $result = Set-WinToolJsoncPath -Text $raw -Name @("profiles", "defaults", "font", "face") -Value $chosen -Kind "string"
        $raw = [string]$result.Text
        $changed = [bool]$result.Changed
        $result = Set-WinToolJsoncPath -Text $raw -Name @("profiles", "defaults", "font", "size") -Value $Size -Kind "number"
        $raw = [string]$result.Text
        if ([bool]$result.Changed) { $changed = $true }
        $root = Get-WinToolJsoncRootStart -Text $raw
        if ($null -ne $root) {
            $map = Get-WinToolJsoncObjectMap -Text $raw -Start ([int]$root)
            $profiles = Get-WinToolJsoncProperty -Object $map -Name "profiles"
            if ($null -ne $profiles -and [string]$profiles.Kind -eq "object") {
                $profileMap = Get-WinToolJsoncObjectMap -Text $raw -Start ([int]$profiles.ValueStart)
                $defaults = Get-WinToolJsoncProperty -Object $profileMap -Name "defaults"
                if ($null -ne $defaults -and [string]$defaults.Kind -eq "object") {
                    $defaultsMap = Get-WinToolJsoncObjectMap -Text $raw -Start ([int]$defaults.ValueStart)
                    $legacy = Get-WinToolJsoncProperty -Object $defaultsMap -Name "fontFace"
                    if ($null -ne $legacy) {
                        $wanted = ConvertTo-WinToolJsonString -Text $chosen
                        $current = $raw.Substring([int]$legacy.ValueStart, ([int]$legacy.ValueEnd - [int]$legacy.ValueStart))
                        if ($current.Trim() -ne $wanted) {
                            $raw = Set-WinToolJsoncObjectLiteral -Text $raw -Object $defaultsMap -Name "fontFace" -Literal $wanted
                            $changed = $true
                        }
                    }
                }
            }
        }
        if ($changed) {
            Backup-WinToolTerminalSetting -Path $path
            $out = $raw
            if (-not $out.EndsWith("`n")) { $out += "`n" }
            Write-WinToolUtf8File -Path $path -Text $out
            $any = $true
        }
    }
    if ($any) {
        Write-WinToolLog -Message ((Get-WinToolText "msg.set-the-windows-terminal-font-to-n-n-pt") -f $chosen, $Size) -Level "ok"
    }
    else {
        Write-WinToolLog -Message ((Get-WinToolText "msg.windows-terminal-already-uses-n-n-pt") -f $chosen, $Size) -Level "ok"
    }
    return $any
}

function Invoke-WinToolTerminalScheme {
    param(
        [Parameter(Mandatory = $true)][string]$SchemeId,
        [string[]]$SettingsPath
    )
    $scheme = $null
    foreach ($item in @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "schemes" -Default @())) {
        if ([string]$item.id -eq $SchemeId) {
            $scheme = $item
            break
        }
    }
    if ($null -eq $scheme) {
        Write-WinToolLog -Message (Get-WinToolText "msg.unknown-color-scheme-n" $SchemeId) -Level "warn"
        return $false
    }
    $paths = @($SettingsPath | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_) })
    if ($paths.Count -eq 0) {
        $paths = @(Get-WinToolTerminalSettingsPathList)
    }
    if ($paths.Count -eq 0) {
        Write-WinToolLog -Message (Get-WinToolText "msg.windows-terminal-settings-were-not-found-so-the-color-sc") -Level "warn"
        return $false
    }
    $any = $false
    foreach ($path in $paths) {
        $raw = "{}"
        if (Test-Path -LiteralPath $path) {
            $raw = [System.IO.File]::ReadAllText($path)
            if ([string]::IsNullOrWhiteSpace($raw)) { $raw = "{}" }
        }
        $settings = $null
        try {
            $settings = ConvertFrom-WinToolJsonText -Text $raw
        }
        catch {
            $settings = $null
        }
        if ($null -ne $settings -and (Test-WinToolSettingsSchemeMatch -Settings $settings -Scheme $scheme)) {
            continue
        }
        $result = Set-WinToolJsoncColorScheme -Text $raw -Scheme $scheme
        if ([bool]$result.Changed) {
            Backup-WinToolTerminalSetting -Path $path
            $out = [string]$result.Text
            if (-not $out.EndsWith("`n")) { $out += "`n" }
            Write-WinToolUtf8File -Path $path -Text $out
            $any = $true
        }
    }
    if ($any) {
        Write-WinToolLog -Message (Get-WinToolText "msg.set-the-windows-terminal-color-scheme-to-n" $($scheme.name)) -Level "ok"
    }
    else {
        Write-WinToolLog -Message ((Get-WinToolText "msg.the-color-scheme-n-was-already-set") -f [string]$scheme.name) -Level "ok"
    }
    return $any
}

function Invoke-WinToolStarshipPreset {
    param(
        [Parameter(Mandatory = $true)][string]$Preset
    )
    Sync-WinToolProcessPath
    $command = Get-Command -Name "starship" -CommandType Application -ErrorAction SilentlyContinue | Select-Object -First 1
    if ($null -eq $command) {
        foreach ($candidate in @(
                ([string]$env:ProgramFiles + "\starship\bin\starship.exe"),
                ([string]$env:LOCALAPPDATA + "\Programs\starship\bin\starship.exe"),
                ([string]$env:LOCALAPPDATA + "\Microsoft\WinGet\Links\starship.exe"),
                ([string]$env:USERPROFILE + "\.cargo\bin\starship.exe")
            )) {
            if (-not [string]::IsNullOrWhiteSpace($candidate) -and (Test-Path -LiteralPath $candidate)) {
                $command = Get-Command -Name $candidate -ErrorAction SilentlyContinue
                break
            }
        }
    }
    if ($null -eq $command) {
        Write-WinToolLog -Message (Get-WinToolText "msg.starship-is-not-on-path-yet-so-the-preset-was-skipped") -Level "warn"
        return
    }
    $directory = Join-Path $env:USERPROFILE ".config"
    if (-not (Test-Path -LiteralPath $directory)) {
        New-Item -ItemType Directory -Path $directory -Force | Out-Null
    }
    $destination = Join-Path $directory "starship.toml"
    $global:LASTEXITCODE = 0
    & $command.Source preset $Preset -o $destination
    if ($LASTEXITCODE -ne 0 -or -not (Test-Path -LiteralPath $destination)) {
        Write-WinToolLog -Message ((Get-WinToolText "msg.starship-could-not-apply-the-preset-n-exit-n") -f $Preset, $LASTEXITCODE) -Level "warn"
        return
    }
    Write-WinToolLog -Message (Get-WinToolText "msg.wrote-the-starship-preset-to-n" $destination) -Level "ok"
}

function Get-WinToolFontInstallStep {
    param(
        [Parameter(Mandatory = $true)]$Font
    )
    # Nerd Fonts come from the official ryanoasis/nerd-fonts release. Plain
    # fonts come from their own GitHub releases, or from winget only when the
    # id was checked in winget-pkgs (fonts.json keeps just those).
    $name = [string]$Font.name
    $wingetId = [string](Get-WinToolNote -Object $Font -Name "wingetId" -Default "")
    $asset = [string](Get-WinToolNote -Object $Font -Name "asset" -Default "")
    $github = Get-WinToolNote -Object $Font -Name "github"
    if (-not [string]::IsNullOrWhiteSpace($asset)) {
        $release = [string](Get-WinToolNote -Object $Font -Name "release" -Default "")
        if ([string]::IsNullOrWhiteSpace($release)) {
            $release = [string](Get-WinToolNote -Object (Get-WinToolFontDocument) -Name "nerdFontsRelease" -Default "v3.5.1")
        }
        return @([pscustomobject]@{ Type = "font-download"; Label = ("Download " + $name); Release = $release; Asset = $asset; Face = [string]$Font.face; FontId = [string]$Font.id })
    }
    if ($null -ne $github) {
        return @([pscustomobject]@{ Type = "font-download"; Label = ("Download " + $name); Repo = [string]$github.repo; AssetPattern = [string]$github.asset; Files = @($github.files); Face = [string]$Font.face; FontId = [string]$Font.id })
    }
    if (-not [string]::IsNullOrWhiteSpace($wingetId)) {
        return @([pscustomobject]@{ Type = "winget"; Label = ("Install " + $name); WingetId = $wingetId; Scope = "" })
    }
    return @()
}

function Get-WinToolFontDownloadScript {
    param(
        [Parameter(Mandatory = $true)]$Step
    )
    # Two kinds of source: a Nerd Fonts release zip (fixed release and file
    # name), or the latest release of a font's own GitHub repository, found
    # by a file name pattern. Fonts go to the user's font folder and are
    # registered for the user, then loaded so Terminal sees them right away.
    $url = ""
    $release = [string](Get-WinToolNote -Object $Step -Name "Release" -Default "")
    $asset = [string](Get-WinToolNote -Object $Step -Name "Asset" -Default "")
    if (-not [string]::IsNullOrWhiteSpace($asset)) {
        $url = "https://github.com/ryanoasis/nerd-fonts/releases/download/" + $release + "/" + $asset
    }
    $repo = [string](Get-WinToolNote -Object $Step -Name "Repo" -Default "")
    $pattern = [string](Get-WinToolNote -Object $Step -Name "AssetPattern" -Default "")
    if ([string]::IsNullOrWhiteSpace($url) -and ([string]::IsNullOrWhiteSpace($repo) -or [string]::IsNullOrWhiteSpace($pattern))) {
        throw (Get-WinToolText "msg.the-font-download-needs-a-nerd-fonts-asset-or-a-github-r")
    }
    $files = @(Get-WinToolNote -Object $Step -Name "Files" -Default @())
    $fileText = (@($files | ForEach-Object { ConvertTo-WinToolSingleQuoted -Text ([string]$_) })) -join ", "
    $lines = New-Object System.Collections.Generic.List[string]
    $lines.Add('$ErrorActionPreference = "Stop"')
    $lines.Add('[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12')
    $lines.Add('Add-Type -AssemblyName System.IO.Compression.FileSystem')
    $lines.Add('$url = ' + (ConvertTo-WinToolSingleQuoted -Text $url))
    $lines.Add('$repo = ' + (ConvertTo-WinToolSingleQuoted -Text $repo))
    $lines.Add('$pattern = ' + (ConvertTo-WinToolSingleQuoted -Text $pattern))
    $lines.Add('$wanted = @(' + $fileText + ')')
    $body = @'
if ([string]::IsNullOrWhiteSpace($url)) {
    $latest = Invoke-RestMethod -Uri ("https://api.github.com/repos/" + $repo + "/releases/latest") -Headers @{ "User-Agent" = "WinTool" } -UseBasicParsing
    $match = @($latest.assets | Where-Object { [string]$_.name -like $pattern })
    if ($match.Count -eq 0) {
        throw ("The latest " + $repo + " release has no file named like " + $pattern + ".")
    }
    $url = [string]$match[0].browser_download_url
    Write-Output ("Downloading " + [string]$match[0].name + " from " + $repo + " " + [string]$latest.tag_name)
}
else {
    Write-Output ("Downloading " + $url)
}
$name = [IO.Path]::GetFileName(([uri]$url).AbsolutePath)
$zip = Join-Path $env:TEMP ("WinTool-" + $name)
$folder = Join-Path $env:TEMP ("WinTool-" + [IO.Path]::GetFileNameWithoutExtension($name))
Invoke-WebRequest -Uri $url -OutFile $zip -UseBasicParsing
if (Test-Path -LiteralPath $folder) { Remove-Item -LiteralPath $folder -Recurse -Force }
[IO.Compression.ZipFile]::ExtractToDirectory($zip, $folder)
$all = @(Get-ChildItem -LiteralPath $folder -Recurse -File | Where-Object { @(".ttf", ".otf", ".ttc") -contains $_.Extension.ToLowerInvariant() })
$picked = @{}
foreach ($file in $all) {
    $take = ($wanted.Count -eq 0)
    foreach ($want in $wanted) {
        if ($file.Name -like $want) { $take = $true }
    }
    if ($take -and -not $picked.ContainsKey($file.Name.ToLowerInvariant())) {
        $picked[$file.Name.ToLowerInvariant()] = $file
    }
}
if ($picked.Count -eq 0) {
    throw ("No font files were found in " + $name + ".")
}
if (-not ("WinToolFontLoader" -as [type])) {
    Add-Type -TypeDefinition 'using System; using System.Runtime.InteropServices; public static class WinToolFontLoader { [DllImport("gdi32.dll", CharSet = CharSet.Unicode)] public static extern int AddFontResource(string file); }'
}
$dest = Join-Path $env:LOCALAPPDATA "Microsoft\Windows\Fonts"
if (-not (Test-Path -LiteralPath $dest)) { New-Item -ItemType Directory -Path $dest -Force | Out-Null }
$key = "HKCU:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Fonts"
if (-not (Test-Path -LiteralPath $key)) { New-Item -Path $key -Force | Out-Null }
foreach ($file in $picked.Values) {
    $target = Join-Path $dest $file.Name
    Copy-Item -LiteralPath $file.FullName -Destination $target -Force
    $label = [IO.Path]::GetFileNameWithoutExtension($file.Name) + " (TrueType)"
    New-ItemProperty -LiteralPath $key -Name $label -Value $target -PropertyType String -Force | Out-Null
    $null = [WinToolFontLoader]::AddFontResource($target)
}
Remove-Item -LiteralPath $zip -Force -ErrorAction SilentlyContinue
Remove-Item -LiteralPath $folder -Recurse -Force -ErrorAction SilentlyContinue
Write-Output ("Installed " + $picked.Count + " font files from " + $name)
'@
    $lines.Add($body)
    return ($lines -join [Environment]::NewLine)
}

function Get-WinToolToolDownloadScript {
    param(
        [Parameter(Mandatory = $true)][string]$Url,
        [Parameter(Mandatory = $true)][string]$FileName
    )
    $text = @'
$ErrorActionPreference = "Stop"
[Net.ServicePointManager]::SecurityProtocol = [Net.ServicePointManager]::SecurityProtocol -bor [Net.SecurityProtocolType]::Tls12
$url = "URL"
$name = "FILENAME"
$dest = Join-Path $env:LOCALAPPDATA "WinTool\bin"
if (-not (Test-Path -LiteralPath $dest)) { New-Item -ItemType Directory -Path $dest -Force | Out-Null }
$path = Join-Path $dest $name
$part = $path + ".part"
try {
    Invoke-WebRequest -Uri $url -OutFile $part -UseBasicParsing -TimeoutSec 60
    Move-Item -LiteralPath $part -Destination $path -Force
}
finally {
    Remove-Item -LiteralPath $part -Force -ErrorAction SilentlyContinue
}
Write-Output ("Downloaded " + $path)
'@
    return $text.Replace("URL", $Url).Replace("FILENAME", $FileName)
}

function Get-WinToolSimpleTerminalChoice {
    $catalog = Get-WinToolTerminalCatalog
    $simple = Get-WinToolNote -Object $catalog -Name "simple"
    return [pscustomobject]@{
        prompt = [string](Get-WinToolNote -Object $simple -Name "prompt" -Default "oh-my-posh")
        promptStyle = [string](Get-WinToolNote -Object $simple -Name "promptStyle" -Default "jandedobbeleer")
        fontId = [string](Get-WinToolNote -Object $simple -Name "fontId" -Default "cascadiacode-nf")
        schemeId = [string](Get-WinToolNote -Object $simple -Name "schemeId" -Default "wintool-night")
        terminalIcons = [bool](Get-WinToolNote -Object $simple -Name "terminalIcons" -Default $true)
        psReadLine = [bool](Get-WinToolNote -Object $simple -Name "psReadLine" -Default $true)
        zoxide = [bool](Get-WinToolNote -Object $simple -Name "zoxide" -Default $false)
        fzf = [bool](Get-WinToolNote -Object $simple -Name "fzf" -Default $false)
        hideStartupBanner = [bool](Test-WinToolHideStartupBanner -Selection $simple)
        fontSize = [int](Get-WinToolNote -Object $simple -Name "fontSize" -Default 12)
    }
}

function Get-WinToolTerminalSummary {
    param(
        [Parameter(Mandatory = $true)]$Selection,
        $Cache,
        [switch]$Update
    )
    if ($null -eq $Cache) {
        $Cache = Get-WinToolPackageCache
    }
    $plan = @(Get-WinToolTerminalPlan -Selection $Selection)
    $chips = @(Get-WinToolSummaryChip -Step $plan -Cache $Cache -Selection $Selection -Update:$Update)
    $lines = New-Object System.Collections.Generic.List[string]
    foreach ($chip in $chips) {
        $kind = [string]$chip.Kind
        if ($kind -eq "add") {
            $lines.Add("Install " + [string]$chip.Text)
        }
        elseif ($kind -eq "have") {
            $lines.Add("Already installed: " + [string]$chip.Text)
        }
        elseif ($kind -eq "set") {
            $lines.Add("Already set: " + [string]$chip.Text)
        }
        elseif ($kind -eq "update") {
            $lines.Add("Update " + [string]$chip.Text)
        }
        else {
            $lines.Add("Change " + [string]$chip.Text)
        }
    }
    if ($lines.Count -eq 0) {
        foreach ($step in $plan) {
            $lines.Add([string]$step.Label)
        }
    }
    return $lines.ToArray()
}

function Get-WinToolTerminalPlan {
    param(
        [Parameter(Mandatory = $true)]$Selection
    )
    $catalog = Get-WinToolTerminalCatalog
    $promptId = [string](Get-WinToolNote -Object $Selection -Name "prompt" -Default "")
    if ([string]::IsNullOrWhiteSpace($promptId)) {
        $promptId = [string](Get-WinToolNote -Object $Selection -Name "Prompt" -Default "oh-my-posh")
    }
    $promptStyle = [string](Get-WinToolNote -Object $Selection -Name "promptStyle" -Default "")
    $fontId = [string](Get-WinToolNote -Object $Selection -Name "fontId" -Default "")
    if ([string]::IsNullOrWhiteSpace($fontId)) {
        $fontId = [string](Get-WinToolNote -Object $Selection -Name "FontId" -Default "")
    }
    $schemeId = [string](Get-WinToolNote -Object $Selection -Name "schemeId" -Default "")
    $icons = Get-WinToolNote -Object $Selection -Name "terminalIcons"
    if ($null -eq $icons) { $icons = $true }
    $psReadLine = Get-WinToolNote -Object $Selection -Name "psReadLine"
    if ($null -eq $psReadLine) { $psReadLine = $false }
    $zoxide = Get-WinToolNote -Object $Selection -Name "zoxide"
    if ($null -eq $zoxide) { $zoxide = $false }
    $fzf = Get-WinToolNote -Object $Selection -Name "fzf"
    if ($null -eq $fzf) { $fzf = $false }
    $hideBanner = Test-WinToolHideStartupBanner -Selection $Selection
    $wsl = Get-WinToolNote -Object $Selection -Name "wsl"
    if ($null -eq $wsl) { $wsl = $false }
    $zsh = Get-WinToolNote -Object $Selection -Name "zsh"
    if ($null -eq $zsh) { $zsh = $false }

    $prompt = $null
    foreach ($item in @(Get-WinToolNote -Object $catalog -Name "prompts" -Default @())) {
        if ([string]$item.id -eq $promptId) {
            $prompt = $item
            break
        }
    }
    if ($null -eq $prompt) {
        throw (Get-WinToolText "msg.unknown-terminal-prompt-n" $promptId)
    }
    $shellKind = [string](Get-WinToolNote -Object $prompt -Name "shell" -Default "powershell")
    if ($shellKind -like "wsl-*") {
        $wsl = $true
        $zsh = $true
    }

    $font = $null
    # Fonts added by the online refresh live in $script:WinToolExtraFont.
    $fontRows = @(Get-WinToolNote -Object (Get-WinToolFontDocument) -Name "fonts" -Default @()) + @($script:WinToolExtraFont | Where-Object { $null -ne $_ })
    foreach ($item in $fontRows) {
        if ([string]$item.id -eq $fontId) {
            $font = $item
            break
        }
    }
    if ($null -eq $font) {
        throw (Get-WinToolText "msg.unknown-terminal-font-n" $fontId)
    }
    $scheme = $null
    foreach ($item in @(Get-WinToolNote -Object $catalog -Name "schemes" -Default @())) {
        if ([string]$item.id -eq $schemeId) {
            $scheme = $item
            break
        }
    }

    $components = Get-WinToolNote -Object $catalog -Name "components"
    $steps = New-Object System.Collections.Generic.List[object]
    [void]$steps.Add([pscustomobject]@{ Type = "winget"; Label = (Get-WinToolText "msg.install-windows-terminal"); WingetId = [string]$components.windowsTerminal; Scope = "" })
    [void]$steps.Add([pscustomobject]@{ Type = "winget"; Label = (Get-WinToolText "msg.install-powershell-7"); WingetId = [string]$components.powerShell; Scope = "" })
    $promptWinget = [string](Get-WinToolNote -Object $prompt -Name "wingetId" -Default "")
    if (-not [string]::IsNullOrWhiteSpace($promptWinget)) {
        [void]$steps.Add([pscustomobject]@{ Type = "winget"; Label = ("Install " + [string]$prompt.name); WingetId = $promptWinget; Scope = "" })
    }
    foreach ($fontStep in @(Get-WinToolFontInstallStep -Font $font)) {
        [void]$steps.Add($fontStep)
    }
    $fontSize = 12
    $sizeValue = Get-WinToolNote -Object $Selection -Name "fontSize"
    if ($null -ne $sizeValue -and [int]$sizeValue -ge 6 -and [int]$sizeValue -le 48) { $fontSize = [int]$sizeValue }
    $fontLabel = "Set the Windows Terminal font to " + [string]$font.name
    if ($fontSize -ne 12) { $fontLabel += " " + $fontSize + " pt" }
    [void]$steps.Add([pscustomobject]@{ Type = "font"; Label = $fontLabel; Face = [string]$font.face; Match = [string]$font.match; Size = $fontSize })
    [void]$steps.Add([pscustomobject]@{ Type = "ligatures"; Label = (Get-WinToolText "msg.turn-on-font-ligatures-in-windows-terminal-for-all-profi") })
    [void]$steps.Add((Get-WinToolTerminalBannerStep -Undo:(-not $hideBanner)))
    if ($null -ne $scheme) {
        [void]$steps.Add([pscustomobject]@{ Type = "scheme"; Label = ("Set the Windows Terminal color scheme to " + [string]$scheme.name); SchemeId = [string]$scheme.id })
    }
    if ($promptId -eq "starship" -and -not [string]::IsNullOrWhiteSpace($promptStyle)) {
        [void]$steps.Add([pscustomobject]@{ Type = "starship-preset"; Label = ("Apply the Starship preset " + $promptStyle); Preset = $promptStyle })
    }
    if ($promptId -eq "powerline-go") {
        [void]$steps.Add([pscustomobject]@{ Type = "tool-download"; Label = (Get-WinToolText "msg.download-powerline-go"); Url = [string](Get-WinToolNote -Object $prompt -Name "downloadUrl" -Default ""); FileName = "powerline-go.exe" })
    }
    foreach ($extra in @(Get-WinToolNote -Object $catalog -Name "extras" -Default @())) {
        $extraId = [string]$extra.id
        $enabled = $false
        if ($extraId -eq "terminal-icons") { $enabled = [bool]$icons }
        elseif ($extraId -eq "psreadline") { $enabled = [bool]$psReadLine }
        elseif ($extraId -eq "zoxide") { $enabled = [bool]$zoxide }
        elseif ($extraId -eq "fzf") { $enabled = [bool]$fzf }
        if ($enabled -and [string]$extra.kind -eq "winget") {
            [void]$steps.Add([pscustomobject]@{ Type = "winget"; Label = ("Install " + [string]$extra.name); WingetId = [string]$extra.wingetId; Scope = "" })
        }
    }
    if ([bool]$icons) {
        [void]$steps.Add([pscustomobject]@{ Type = "module"; Label = (Get-WinToolText "msg.install-terminal-icons-for-windows-powershell"); Name = "Terminal-Icons"; Host = "powershell" })
        [void]$steps.Add([pscustomobject]@{ Type = "module"; Label = (Get-WinToolText "msg.install-terminal-icons-for-powershell-7"); Name = "Terminal-Icons"; Host = "pwsh" })
    }
    if ([bool]$psReadLine) {
        # 5.1 ships PSReadLine 2.0, too old for history predictions.
        [void]$steps.Add([pscustomobject]@{ Type = "module"; Label = (Get-WinToolText "msg.update-psreadline-for-windows-powershell"); Name = "PSReadLine"; Host = "powershell"; Module = "PSReadLine" })
    }
    [void]$steps.Add([pscustomobject]@{ Type = "profile"; Label = (Get-WinToolText "msg.update-powershell-profiles"); Prompt = $promptId; PromptStyle = $promptStyle; TerminalIcons = [bool]$icons; PsReadLine = [bool]$psReadLine; Zoxide = [bool]$zoxide })
    if ([bool]$wsl) {
        $distro = [string](Get-WinToolNote -Object $Selection -Name "wslDistro" -Default "Ubuntu")
        $withShell = ([bool]$zsh -or $shellKind -like "wsl-*")
        foreach ($wslStep in @(Get-WinToolWslStep -Distro $distro -PromptId $promptId -PromptStyle $promptStyle -Font $font -Install $true -Shell $withShell)) {
            if ([string]$wslStep.Type -eq "wsl-shell") {
                $wslStep | Add-Member -NotePropertyName "HideStartupBanner" -NotePropertyValue $hideBanner
            }
            [void]$steps.Add($wslStep)
        }
    }
    return $steps.ToArray()
}

# Prompt preview: a list of colored segments that approximates what the
# chosen prompt and theme look like. Oh My Posh themes are read from their
# JSON (palette, segment colors, powerline or diamond style); other prompts
# use the small samples in terminal.json "previews".
$script:WinToolPreviewNamedColor = @{
    black = "#0C0C0C"; red = "#C50F1F"; green = "#13A10E"; yellow = "#C19C00"; blue = "#0037DA"; magenta = "#881798"; cyan = "#3A96DD"; white = "#CCCCCC"
    darkGray = "#767676"; lightBlack = "#767676"; lightRed = "#E74856"; lightGreen = "#16C60C"; lightYellow = "#F9F1A5"; lightBlue = "#3B78FF"; lightMagenta = "#B4009E"; lightCyan = "#61D6D6"; lightWhite = "#F2F2F2"
}

$script:WinToolPreviewSampleText = @{
    path = "~/src"; git = "main"; session = "user"; time = "23:14"; executiontime = "12ms"
    node = "20.11"; python = "3.12"; go = "1.22"; dotnet = "8.0"; rust = "1.79"; java = "21"
    shell = "pwsh"; battery = "87%"; az = "dev"; aws = "dev"; kubectl = "dev"; docker = "dev"
}

function ConvertTo-WinToolPreviewColor {
    param(
        [AllowEmptyString()][string]$Value,
        $Palette
    )
    $text = [string]$Value
    for ($depth = 0; $depth -lt 3 -and $text.StartsWith("p:"); $depth++) {
        $text = [string](Get-WinToolNote -Object $Palette -Name $text.Substring(2) -Default "")
    }
    if ($text -match '^#([0-9A-Fa-f]{6})([0-9A-Fa-f]{2})?$') {
        return ("#" + $Matches[1].ToUpperInvariant())
    }
    if ($text -match '^#([0-9A-Fa-f])([0-9A-Fa-f])([0-9A-Fa-f])$') {
        return ("#" + $Matches[1] + $Matches[1] + $Matches[2] + $Matches[2] + $Matches[3] + $Matches[3]).ToUpperInvariant()
    }
    if ($script:WinToolPreviewNamedColor.ContainsKey($text)) {
        return $script:WinToolPreviewNamedColor[$text]
    }
    return $null
}

function New-WinToolPreviewSegment {
    param(
        [AllowEmptyString()][string]$Text,
        [string]$Foreground,
        [string]$Background
    )
    $fg = $null
    $bg = $null
    if (-not [string]::IsNullOrWhiteSpace($Foreground)) { $fg = $Foreground }
    if (-not [string]::IsNullOrWhiteSpace($Background)) { $bg = $Background }
    return [pscustomobject]@{ Text = $Text; Foreground = $fg; Background = $bg }
}

function Get-WinToolOmpPreviewSegment {
    param(
        [Parameter(Mandatory = $true)]$Theme
    )
    $palette = Get-WinToolNote -Object $Theme -Name "palette"
    $parts = New-Object System.Collections.Generic.List[object]
    foreach ($block in @(Get-WinToolNote -Object $Theme -Name "blocks" -Default @())) {
        if ([string](Get-WinToolNote -Object $block -Name "type" -Default "prompt") -ne "prompt") { continue }
        if ([string](Get-WinToolNote -Object $block -Name "alignment" -Default "left") -eq "right") { continue }
        foreach ($segment in @(Get-WinToolNote -Object $block -Name "segments" -Default @())) {
            if ($parts.Count -ge 4) { break }
            $type = [string](Get-WinToolNote -Object $segment -Name "type" -Default "")
            $text = ""
            if ($script:WinToolPreviewSampleText.ContainsKey($type)) {
                $text = [string]$script:WinToolPreviewSampleText[$type]
            }
            elseif ($type -eq "text") {
                $template = [string](Get-WinToolNote -Object $segment -Name "template" -Default "")
                if (-not $template.Contains("{{")) { $text = $template.Trim() }
            }
            if ([string]::IsNullOrWhiteSpace($text)) { continue }
            $style = [string](Get-WinToolNote -Object $segment -Name "style" -Default "plain")
            $background = ConvertTo-WinToolPreviewColor -Value ([string](Get-WinToolNote -Object $segment -Name "background" -Default "")) -Palette $palette
            $foreground = ConvertTo-WinToolPreviewColor -Value ([string](Get-WinToolNote -Object $segment -Name "foreground" -Default "")) -Palette $palette
            if ($style -eq "plain") { $background = $null }
            $parts.Add([pscustomobject]@{
                Text = $text
                Foreground = $foreground
                Background = $background
                Style = $style
                Symbol = [string](Get-WinToolNote -Object $segment -Name "powerline_symbol" -Default ([string][char]0xE0B0))
                Leading = [string](Get-WinToolNote -Object $segment -Name "leading_diamond" -Default "")
                Trailing = [string](Get-WinToolNote -Object $segment -Name "trailing_diamond" -Default "")
            })
        }
        if ($parts.Count -gt 0) { break }
    }
    $result = New-Object System.Collections.Generic.List[object]
    $parentBackground = $null
    $parentForeground = $null
    for ($index = 0; $index -lt $parts.Count; $index++) {
        $part = $parts[$index]
        $markup = @{ Palette = $palette; SegmentForeground = $part.Foreground; SegmentBackground = $part.Background; ParentForeground = $parentForeground; ParentBackground = $parentBackground }
        if ($index + 1 -lt $parts.Count) { $markup.ChildBackground = $parts[$index + 1].Background }
        if ($null -ne $part.Background) { $parentBackground = $part.Background }
        $parentForeground = $part.Foreground
        $nextBackground = $null
        if ($index + 1 -lt $parts.Count) { $nextBackground = $parts[$index + 1].Background }
        if ($null -eq $part.Background) {
            foreach ($piece in @(Split-WinToolOmpMarkup -Text ($part.Text + " ") -Foreground $part.Foreground @markup)) { $result.Add($piece) }
            continue
        }
        if ($part.Style -eq "diamond" -and -not [string]::IsNullOrEmpty($part.Leading)) {
            foreach ($piece in @(Split-WinToolOmpMarkup -Text $part.Leading -Foreground $part.Background @markup)) { $result.Add($piece) }
        }
        foreach ($piece in @(Split-WinToolOmpMarkup -Text (" " + $part.Text + " ") -Foreground $part.Foreground -Background $part.Background @markup)) { $result.Add($piece) }
        if ($part.Style -eq "powerline") {
            foreach ($piece in @(Split-WinToolOmpMarkup -Text $part.Symbol -Foreground $part.Background -Background $nextBackground @markup)) { $result.Add($piece) }
        }
        elseif ($part.Style -eq "diamond" -and -not [string]::IsNullOrEmpty($part.Trailing)) {
            foreach ($piece in @(Split-WinToolOmpMarkup -Text $part.Trailing -Foreground $part.Background @markup)) { $result.Add($piece) }
        }
    }
    return $result.ToArray()
}

function Get-WinToolPromptPreview {
    param(
        [string]$PromptId,
        [string]$PromptStyle,
        $Theme
    )
    $catalog = Get-WinToolTerminalCatalog
    $previews = Get-WinToolNote -Object $catalog -Name "previews"
    if ($PromptId -eq "oh-my-posh" -and $null -ne $Theme) {
        $segments = @(Get-WinToolOmpPreviewSegment -Theme $Theme)
        if ($segments.Count -gt 0) {
            return $segments
        }
    }
    if ($PromptId -eq "oh-my-posh") {
        # Without the theme file, use the sample stored in omp-themes.json.
        foreach ($row in @(Get-WinToolNote -Object (Get-WinToolOhMyPoshDocument) -Name "themes" -Default @())) {
            if ([string]$row.id -ne $PromptStyle) { continue }
            $segments = @(ConvertTo-WinToolPreviewSegmentList -Item @(Get-WinToolNote -Object $row -Name "preview" -Default @()))
            if ($segments.Count -gt 0) { return $segments }
        }
    }
    if ($PromptId -eq "starship") {
        foreach ($preset in @(Get-WinToolNote -Object $catalog -Name "starshipPresets" -Default @())) {
            if ([string]$preset.id -ne $PromptStyle) { continue }
            $list = New-Object System.Collections.Generic.List[object]
            foreach ($item in @(Get-WinToolNote -Object $preset -Name "preview" -Default @())) {
                $fg = [string](Get-WinToolNote -Object $item -Name "fg" -Default "")
                if ([string]::IsNullOrWhiteSpace($fg)) { $fg = [string](Get-WinToolNote -Object $item -Name "color" -Default "") }
                $list.Add((New-WinToolPreviewSegment -Text ([string]$item.text) -Foreground $fg -Background ([string](Get-WinToolNote -Object $item -Name "bg" -Default ""))))
            }
            if ($list.Count -gt 0) {
                return (Add-WinToolPreviewSeparator -Segments $list.ToArray())
            }
        }
    }
    $variant = Get-WinToolPromptVariant -PromptId $PromptId -PromptStyle $PromptStyle
    if ($null -ne $variant) {
        $list = New-Object System.Collections.Generic.List[object]
        foreach ($item in @(Get-WinToolNote -Object $variant -Name "preview" -Default @())) {
            $list.Add((New-WinToolPreviewSegment -Text ([string]$item.text) -Foreground ([string](Get-WinToolNote -Object $item -Name "fg" -Default "")) -Background ([string](Get-WinToolNote -Object $item -Name "bg" -Default ""))))
        }
        if ($list.Count -gt 0) {
            return (Add-WinToolPreviewSeparator -Segments $list.ToArray())
        }
    }
    $key = $PromptId
    if ($PromptId -eq "oh-my-zsh" -and $null -ne $previews -and $null -ne $previews.PSObject.Properties[("oh-my-zsh:" + $PromptStyle)]) {
        $key = "oh-my-zsh:" + $PromptStyle
    }
    $sample = @(Get-WinToolNote -Object $previews -Name $key -Default @())
    if ($sample.Count -eq 0) {
        $sample = @(Get-WinToolNote -Object $previews -Name "oh-my-posh" -Default @())
    }
    $out = New-Object System.Collections.Generic.List[object]
    foreach ($item in $sample) {
        $out.Add((New-WinToolPreviewSegment -Text ([string]$item.text) -Foreground ([string](Get-WinToolNote -Object $item -Name "fg" -Default "")) -Background ([string](Get-WinToolNote -Object $item -Name "bg" -Default ""))))
    }
    return (Add-WinToolPreviewSeparator -Segments $out.ToArray())
}

function Get-WinToolPromptVariantList {
    param(
        [AllowEmptyString()][string]$PromptId
    )
    # The styles a prompt offers (data/terminal.json "promptVariants").
    if ([string]::IsNullOrWhiteSpace($PromptId)) { return @() }
    $variants = Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "promptVariants"
    if ($null -eq $variants -or $null -eq $variants.PSObject.Properties[$PromptId]) { return @() }
    return @($variants.PSObject.Properties[$PromptId].Value | Where-Object { $null -ne $_ })
}

function Get-WinToolPromptVariant {
    param(
        [AllowEmptyString()][string]$PromptId,
        [AllowEmptyString()][string]$PromptStyle
    )
    # The chosen style, or the prompt's first style when the id is unknown.
    $rows = @(Get-WinToolPromptVariantList -PromptId $PromptId)
    if ($rows.Count -eq 0) { return $null }
    foreach ($row in $rows) {
        if ([string]$row.id -eq $PromptStyle) { return $row }
    }
    return $rows[0]
}

function Get-WinToolPromptVariantSetting {
    param(
        $Variant
    )
    # Lines that go into ~/.zshrc for Spaceship and Pure. Only plain words,
    # spaces, and = : . _ - are allowed so nothing can break out into a shell.
    $out = New-Object System.Collections.Generic.List[string]
    foreach ($line in @(Get-WinToolNote -Object $Variant -Name "settings" -Default @())) {
        $text = [string]$line
        if ($text -match '^[A-Za-z0-9_:=. -]+$') { $out.Add($text) }
    }
    return $out.ToArray()
}

function Get-WinToolPromptVariantArgument {
    param(
        $Variant
    )
    # powerline-go flags such as "-theme gruvbox" or "-mode flat".
    $out = New-Object System.Collections.Generic.List[string]
    foreach ($arg in @(Get-WinToolNote -Object $Variant -Name "args" -Default @())) {
        $text = [string]$arg
        if ($text -match '^-?[A-Za-z0-9._-]+$') { $out.Add($text) }
    }
    return $out.ToArray()
}

function Test-WinToolPreviewSeparator {
    param(
        [AllowEmptyString()][string]$Text
    )
    $trim = ([string]$Text).Trim()
    if ($trim.Length -ne 1) { return $false }
    $code = [int][char]$trim
    return (($code -ge 0xE0B0 -and $code -le 0xE0D4) -or $code -eq 0x25B6 -or $code -eq 0x25C0)
}

function Add-WinToolPreviewSeparator {
    param(
        [object[]]$Segments
    )
    # Where a colored block ends and the next part has another background (or
    # none), put a Powerline arrow between them unless the data already has one.
    $list = @($Segments | Where-Object { $null -ne $_ })
    $out = New-Object System.Collections.Generic.List[object]
    for ($i = 0; $i -lt $list.Count; $i++) {
        $item = $list[$i]
        $out.Add($item)
        $bg = [string]$item.Background
        if ([string]::IsNullOrWhiteSpace($bg) -or (Test-WinToolPreviewSeparator -Text ([string]$item.Text))) { continue }
        $nextBg = ""
        if ($i + 1 -lt $list.Count) {
            $next = $list[$i + 1]
            if (Test-WinToolPreviewSeparator -Text ([string]$next.Text)) { continue }
            $nextBg = [string]$next.Background
        }
        if ($nextBg -eq $bg) { continue }
        $out.Add((New-WinToolPreviewSegment -Text ([string][char]0xE0B0) -Foreground $bg -Background $nextBg))
    }
    return $out.ToArray()
}

function Get-WinToolOmpThemeFileName {
    param(
        [AllowEmptyString()][string]$ThemeId,
        [object[]]$Themes
    )
    foreach ($theme in @($Themes)) {
        if ($null -ne $theme -and [string]$theme.id -eq $ThemeId) {
            $file = [string](Get-WinToolNote -Object $theme -Name "file" -Default "")
            if (-not [string]::IsNullOrWhiteSpace($file)) { return $file }
        }
    }
    if ([string]::IsNullOrWhiteSpace($ThemeId)) {
        return "jandedobbeleer.omp.json"
    }
    return (Get-WinToolOhMyPoshThemeFile -PromptStyle $ThemeId)
}

function Read-WinToolCachedOmpTheme {
    param(
        [Parameter(Mandatory = $true)][string]$File
    )
    # Memory first, then the copy under %LOCALAPPDATA%\WinTool\themes.
    if ($null -eq $script:WinToolOmpThemeCache) {
        $script:WinToolOmpThemeCache = @{}
    }
    if ($script:WinToolOmpThemeCache.ContainsKey($File)) {
        return $script:WinToolOmpThemeCache[$File]
    }
    if ([string]::IsNullOrWhiteSpace($env:LOCALAPPDATA) -or $File -notmatch '^[A-Za-z0-9._-]+$') {
        return $null
    }
    $path = Join-Path $env:LOCALAPPDATA ("WinTool\themes\" + $File)
    if (-not (Test-Path -LiteralPath $path)) {
        return $null
    }
    try {
        $theme = ConvertFrom-WinToolJsonText -Text ([System.IO.File]::ReadAllText($path))
        $script:WinToolOmpThemeCache[$File] = $theme
        return $theme
    }
    catch {
        return $null
    }
}

function Get-WinToolSummaryRow {
    # Joins the summary lines into a few rows ("a - b - c") so the summary
    # card keeps a fixed height.
    param(
        [AllowEmptyCollection()][string[]]$Line,
        [int]$Count = 3
    )
    $items = @($Line | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    if ($items.Count -eq 0) {
        return @()
    }
    if ($Count -lt 1) { $Count = 1 }
    $perRow = [int][Math]::Ceiling($items.Count / [double]$Count)
    $separator = " " + [string][char]0x00B7 + " "
    $rows = New-Object System.Collections.Generic.List[string]
    for ($start = 0; $start -lt $items.Count; $start += $perRow) {
        $end = [Math]::Min($items.Count, $start + $perRow) - 1
        $rows.Add((($items[$start..$end]) -join $separator))
    }
    return $rows.ToArray()
}

# Advanced Terminal page helpers. They only read the catalogs, so the tests
# can check them without a window.

$script:WinToolPromptEngineColor = @{
    "oh-my-posh" = "#2F74C0"; "starship" = "#C2185B"; "powerline-go" = "#0E8FB0"
    "powerlevel10k" = "#4B6584"; "pure" = "#9C27B0"; "spaceship" = "#6B4FBB"
    "oh-my-zsh" = "#2E9E55"; "tide" = "#0E7490"
}

function Get-WinToolPromptEngineInfo {
    param(
        [Parameter(Mandatory = $true)]$Prompt,
        [int]$OhMyPoshCount = -1
    )
    # Group, the short line under the name ("WSL - zsh - 6 styles"), and the
    # icon color for one prompt engine.
    $catalog = Get-WinToolTerminalCatalog
    $id = [string]$Prompt.id
    $shellKind = [string](Get-WinToolNote -Object $Prompt -Name "shell" -Default "powershell")
    $group = "PowerShell"
    $where = "PowerShell"
    if ($shellKind -like "wsl-*") {
        $group = "WSL Ubuntu"
        $where = "WSL " + [string][char]0x00B7 + " " + $shellKind.Substring(4)
    }
    $count = ""
    if ($id -eq "oh-my-posh") {
        $total = $OhMyPoshCount
        if ($total -lt 0) { $total = @(Get-WinToolNote -Object (Get-WinToolOhMyPoshDocument) -Name "themes" -Default @()).Count }
        $count = [string]$total + " themes"
    }
    elseif ($id -eq "starship") {
        $count = [string]@(Get-WinToolNote -Object $catalog -Name "starshipPresets" -Default @()).Count + " presets"
    }
    elseif ($id -eq "oh-my-zsh") {
        $count = [string]@(Get-WinToolNote -Object $catalog -Name "omzThemes" -Default @()).Count + " themes"
    }
    else {
        $variants = @(Get-WinToolPromptVariantList -PromptId $id)
        if ($variants.Count -gt 0) { $count = [string]$variants.Count + " styles" }
    }
    $sub = $where
    if (-not [string]::IsNullOrWhiteSpace($count)) { $sub += " " + [string][char]0x00B7 + " " + $count }
    $color = "#5B6680"
    if ($script:WinToolPromptEngineColor.ContainsKey($id)) { $color = $script:WinToolPromptEngineColor[$id] }
    $runs = "Runs in PowerShell 7 and Windows PowerShell, no WSL needed."
    if ($shellKind -eq "wsl-zsh") { $runs = "Runs in zsh inside WSL Ubuntu." }
    elseif ($shellKind -eq "wsl-fish") { $runs = "Runs in Fish inside WSL Ubuntu." }
    return [pscustomobject]@{ Id = $id; Group = $group; Sub = $sub; Color = $color; Runs = $runs; Wsl = ($shellKind -like "wsl-*") }
}

function Get-WinToolThemeTitle {
    param(
        [AllowEmptyString()][string]$PromptId
    )
    # Card title and search hint for the theme column of one engine.
    if ($PromptId -eq "oh-my-posh") { return [pscustomobject]@{ Title = (Get-WinToolText "msg.oh-my-posh-theme"); Hint = (Get-WinToolText "msg.search-themes"); Noun = "themes" } }
    if ($PromptId -eq "starship") { return [pscustomobject]@{ Title = (Get-WinToolText "msg.starship-preset"); Hint = (Get-WinToolText "msg.search-presets"); Noun = "presets" } }
    if ($PromptId -eq "oh-my-zsh") { return [pscustomobject]@{ Title = (Get-WinToolText "msg.oh-my-zsh-theme"); Hint = (Get-WinToolText "msg.search-themes"); Noun = "themes" } }
    $name = $PromptId
    foreach ($prompt in @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "prompts" -Default @())) {
        if ([string]$prompt.id -eq $PromptId) { $name = [string]$prompt.name; break }
    }
    return [pscustomobject]@{ Title = ($name + " style"); Hint = "Search styles"; Noun = "styles" }
}

function Test-WinToolNerdGlyph {
    param(
        [AllowEmptyString()][string]$Text
    )
    # True when the text uses a Private Use Area glyph, which only shows with
    # a Nerd Font (or a Powerline-patched font).
    foreach ($char in ([string]$Text).ToCharArray()) {
        $code = [int]$char
        if (($code -ge 0xE000 -and $code -le 0xF8FF) -or [char]::IsSurrogate($char)) { return $true }
    }
    return $false
}

function New-WinToolThemeRow {
    param(
        [string]$Id,
        [string]$Name,
        [object[]]$Preview,
        $NerdFont,
        [string]$Description = ""
    )
    $segments = @($Preview | Where-Object { $null -ne $_ })
    $powerline = $null
    $nerd = $NerdFont
    if ($segments.Count -gt 0) {
        $powerline = (@($segments | Where-Object { -not [string]::IsNullOrWhiteSpace([string]$_.Background) }).Count -gt 0)
        if ($null -eq $nerd) {
            $nerd = (Test-WinToolNerdGlyph -Text ((@($segments | ForEach-Object { [string]$_.Text })) -join ""))
        }
    }
    return [pscustomobject]@{ Id = $Id; Name = $Name; Preview = $segments; Powerline = $powerline; NerdFont = $nerd; Description = $Description }
}

function Get-WinToolThemeRow {
    param(
        [AllowEmptyString()][string]$PromptId,
        [object[]]$OhMyPoshTheme
    )
    # Every theme, preset, or style the engine offers, with a sample prompt
    # line when one is known. Powerline and NerdFont stay $null when unknown.
    $catalog = Get-WinToolTerminalCatalog
    $rows = New-Object System.Collections.Generic.List[object]
    if ($PromptId -eq "oh-my-posh") {
        $themes = @($OhMyPoshTheme | Where-Object { $null -ne $_ })
        if ($themes.Count -eq 0) { $themes = @(Get-WinToolNote -Object (Get-WinToolOhMyPoshDocument) -Name "themes" -Default @()) }
        foreach ($theme in $themes) {
            # The catalog already has a color sample for every theme, so the
            # list does not open theme files when the engine is selected.
            $preview = @(ConvertTo-WinToolPreviewSegmentList -Item @(Get-WinToolNote -Object $theme -Name "preview" -Default @()))
            if ($preview.Count -eq 0) {
                $file = [string](Get-WinToolNote -Object $theme -Name "file" -Default "")
                if (-not [string]::IsNullOrWhiteSpace($file)) {
                    $json = Read-WinToolCachedOmpTheme -File $file
                    if ($null -ne $json) { $preview = @(Get-WinToolOmpPreviewSegment -Theme $json) }
                }
            }
            $rows.Add((New-WinToolThemeRow -Id ([string]$theme.id) -Name ([string]$theme.name) -Preview $preview -NerdFont $null))
        }
    }
    elseif ($PromptId -eq "starship") {
        foreach ($preset in @(Get-WinToolNote -Object $catalog -Name "starshipPresets" -Default @())) {
            $preview = @(ConvertTo-WinToolPreviewSegmentList -Item @(Get-WinToolNote -Object $preset -Name "preview" -Default @()))
            if ($preview.Count -eq 0) { $preview = @(Get-WinToolPromptPreview -PromptId "starship" -PromptStyle ([string]$preset.id)) }
            $nerd = Get-WinToolNote -Object $preset -Name "nerdFont"
            if ($null -ne $nerd) { $nerd = [bool]$nerd }
            $rows.Add((New-WinToolThemeRow -Id ([string]$preset.id) -Name ([string]$preset.name) -Preview $preview -NerdFont $nerd))
        }
    }
    elseif ($PromptId -eq "oh-my-zsh") {
        $previews = Get-WinToolNote -Object $catalog -Name "previews"
        foreach ($name in @(Get-WinToolNote -Object $catalog -Name "omzThemes" -Default @())) {
            $preview = @()
            if ($null -ne $previews) {
                $sample = Get-WinToolNote -Object $previews -Name ("oh-my-zsh:" + [string]$name) -Default $null
                if ($null -ne $sample) { $preview = @(ConvertTo-WinToolPreviewSegmentList -Item @($sample)) }
            }
            $rows.Add((New-WinToolThemeRow -Id ([string]$name) -Name ([string]$name) -Preview $preview -NerdFont $null))
        }
    }
    else {
        $previewMap = Get-WinToolNote -Object $catalog -Name "previews" -Default $null
        foreach ($variant in @(Get-WinToolPromptVariantList -PromptId $PromptId)) {
            $preview = @(ConvertTo-WinToolPreviewSegmentList -Item @(Get-WinToolNote -Object $variant -Name "preview" -Default @()))
            if ($preview.Count -eq 0 -and $null -ne $previewMap) {
                $sample = Get-WinToolNote -Object $previewMap -Name ($PromptId + ":" + [string]$variant.id) -Default $null
                if ($null -eq $sample) { $sample = Get-WinToolNote -Object $previewMap -Name $PromptId -Default $null }
                if ($null -ne $sample) { $preview = @(ConvertTo-WinToolPreviewSegmentList -Item @($sample)) }
            }
            if ($preview.Count -eq 0) { $preview = @(Get-WinToolPromptPreview -PromptId $PromptId -PromptStyle ([string]$variant.id)) }
            $about = [string](Get-WinToolNote -Object $variant -Name "description" -Default "")
            $rows.Add((New-WinToolThemeRow -Id ([string]$variant.id) -Name ([string]$variant.name) -Preview $preview -NerdFont $null -Description $about))
        }
    }
    return $rows.ToArray()
}

function Select-WinToolThemeRow {
    param(
        [AllowEmptyCollection()][object[]]$Row,
        [AllowEmptyString()][string]$Query = "",
        [AllowEmptyString()][string]$Filter = "all"
    )
    # Search and the All / Powerline / Minimal / No Nerd Font needed chips.
    $out = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($Row | Where-Object { $null -ne $_ })) {
        $hay = [string]$item.Name + " " + [string]$item.Id + " " + [string]$item.Description
        if (-not (Test-WinToolTextMatch -Haystack $hay -Query $Query)) { continue }
        if ($Filter -eq "powerline" -and $item.Powerline -ne $true) { continue }
        if ($Filter -eq "minimal" -and $item.Powerline -ne $false) { continue }
        if ($Filter -eq "no-nerd" -and $item.NerdFont -ne $false) { continue }
        $out.Add($item)
    }
    return $out.ToArray()
}

function Get-WinToolSummaryChip {
    param(
        [AllowEmptyCollection()][object[]]$Step,
        $Cache,
        $ConfigNeed,
        $Selection,
        [switch]$Update
    )
    # Short "+ install", "already installed", and "~ change" chips for the
    # action bar, one per thing, in plan order.
    if ($null -eq $Cache) {
        $Cache = Get-WinToolPackageCache
    }
    $need = $ConfigNeed
    if ($null -eq $need -and $null -ne $Selection) {
        try { $need = Get-WinToolCachedConfigNeed -Selection $Selection } catch { $need = $null }
    }
    $chips = New-Object System.Collections.Generic.List[object]
    $seen = @{}
    $add = {
        param($kind, $text)
        $key = $kind + "|" + $text
        if ([string]::IsNullOrWhiteSpace($text) -or $seen.ContainsKey($key)) { return }
        $seen[$key] = $true
        $chips.Add([pscustomobject]@{ Kind = $kind; Text = $text })
    }
    foreach ($item in @($Step | Where-Object { $null -ne $_ })) {
        $type = [string]$item.Type
        $label = [string]$item.Label
        $decision = $null
        if ($type -eq "winget" -or $type -eq "font-download" -or $type -eq "module") {
            $decision = Get-WinToolPlanStepDecision -Step $item -Cache $Cache -Update:$Update
        }
        switch ($type) {
            "winget" {
                $name = ($label -replace '^Install ', '')
                if ($null -ne $decision -and [string]$decision.Outcome -eq "already-had") { & $add "have" $name }
                elseif ($null -ne $decision -and [string]$decision.Outcome -eq "update") { & $add "update" $name }
                else { & $add "add" $name }
            }
            "font-download" {
                $name = ($label -replace '^Download ', '')
                if ($null -ne $decision -and [string]$decision.Outcome -eq "already-had") { & $add "have" $name }
                else { & $add "add" $name }
            }
            "tool-download" { & $add "add" ($label -replace '^Download ', '') }
            "wsl-install" { & $add "add" ("WSL " + [string]$item.Distro) }
            "module" {
                if ($label -match '^Install (.+?) for ') {
                    $name = $Matches[1]
                    if ($null -ne $decision -and [string]$decision.Outcome -eq "already-had") { & $add "have" $name }
                    elseif ($null -ne $decision -and [string]$decision.Outcome -eq "update") { & $add "update" $name }
                    else { & $add "add" $name }
                }
                elseif ($label -match '^Update (.+?) for ') {
                    $name = $Matches[1] + " predictions"
                    if ($null -ne $decision -and [string]$decision.Outcome -eq "already-had") { & $add "have" $name }
                    elseif ($null -ne $decision -and [string]$decision.Outcome -eq "update") { & $add "update" $name }
                    else { & $add "change" $name }
                }
                else { & $add "change" $label }
            }
            "font" {
                $text = "Terminal font"
                if ($null -ne $item.PSObject.Properties["Size"] -and [int]$item.Size -ne 12) { $text += " " + [int]$item.Size + " pt" }
                if ($null -ne $need -and -not [bool]$need.font) { & $add "set" $text }
                else { & $add "change" $text }
            }
            "ligatures" {
                if ($null -ne $need -and -not [bool]$need.ligatures) { & $add "set" "Font ligatures on" }
                else { & $add "change" "Font ligatures on" }
            }
            "banner" {
                if ([bool](Get-WinToolNote -Object $item -Name "Undo" -Default $false)) { $text = "Startup banner shown" }
                else { $text = "Startup banner hidden" }
                if ($null -ne $need -and -not [bool]$need.banner) { & $add "set" $text }
                else { & $add "change" $text }
            }
            "scheme" {
                $text = ($label -replace '^Set the Windows Terminal color scheme to ', 'Scheme ')
                if ($null -ne $need -and -not [bool]$need.scheme) { & $add "set" $text }
                else { & $add "change" $text }
            }
            "starship-preset" { & $add "change" ("Starship preset " + [string]$item.Preset) }
            "profile" {
                if ($null -ne $need -and -not [bool]$need.profile) { & $add "set" "PowerShell `$PROFILE" }
                else { & $add "change" "PowerShell `$PROFILE" }
            }
            "wsl-shell" {
                $text = $label -replace '^Install ', ''
                $style = ""
                if ($text -match '^(.*) \((.+) style\)$') { $text = $Matches[1]; $style = $Matches[2] }
                & $add "add" $text
                if (-not [string]::IsNullOrWhiteSpace($style)) { & $add "change" ($style + " style") }
            }
            "wsl-profile" { & $add "change" ("Font in the " + [string]$item.Distro + " profile") }
            default { & $add "change" $label }
        }
    }
    return $chips.ToArray()
}

function ConvertTo-WinToolPreviewSegmentList {
    param(
        [AllowEmptyCollection()][object[]]$Item
    )
    # Catalog samples ({ text, fg or color, bg }) as preview segments.
    $out = New-Object System.Collections.Generic.List[object]
    foreach ($entry in @($Item | Where-Object { $null -ne $_ })) {
        $fg = [string](Get-WinToolNote -Object $entry -Name "fg" -Default "")
        if ([string]::IsNullOrWhiteSpace($fg)) { $fg = [string](Get-WinToolNote -Object $entry -Name "color" -Default "") }
        $out.Add((New-WinToolPreviewSegment -Text ([string]$entry.text) -Foreground $fg -Background ([string](Get-WinToolNote -Object $entry -Name "bg" -Default ""))))
    }
    return $out.ToArray()
}

$script:WinToolPreviewTransparent = "#121826"

function Resolve-WinToolOmpMarkupColor {
    param(
        [AllowEmptyString()][string]$Value,
        $Palette,
        [string]$SegmentForeground,
        [string]$SegmentBackground,
        [string]$ParentForeground,
        [string]$ParentBackground,
        [string]$ChildBackground,
        [switch]$IsForeground
    )
    # Color names inside Oh My Posh markup: hex, palette, named colors, and
    # the keywords that point at the segment, its parent, or its child.
    $text = ([string]$Value).Trim()
    switch -Regex ($text) {
        '^$' { return $null }
        '^transparent$' { if ($IsForeground) { return $script:WinToolPreviewTransparent } return $null }
        '^foreground$' { return $SegmentForeground }
        '^background$' { return $SegmentBackground }
        '^parentForeground$' { return $ParentForeground }
        '^parentBackground$' { if ([string]::IsNullOrWhiteSpace($ParentBackground) -and $IsForeground) { return $script:WinToolPreviewTransparent } return $ParentBackground }
        '^childBackground$' { if ([string]::IsNullOrWhiteSpace($ChildBackground) -and $IsForeground) { return $script:WinToolPreviewTransparent } return $ChildBackground }
        '^childForeground$' { return $null }
    }
    return (ConvertTo-WinToolPreviewColor -Value $text -Palette $Palette)
}

function Split-WinToolOmpMarkup {
    param(
        [AllowEmptyString()][string]$Text,
        [string]$Foreground,
        [string]$Background,
        $Palette,
        [string]$SegmentForeground,
        [string]$SegmentBackground,
        [string]$ParentForeground,
        [string]$ParentBackground,
        [string]$ChildBackground
    )
    # Turns "<fg,bg>text</>" color tags into separate preview segments and
    # drops other tags such as <b> or <i>. Text outside tags keeps the
    # given colors.
    $out = New-Object System.Collections.Generic.List[object]
    $source = [string]$Text
    if (-not $source.Contains("<")) {
        $out.Add((New-WinToolPreviewSegment -Text $source -Foreground $Foreground -Background $Background))
        return $out.ToArray()
    }
    $colors = @{ Palette = $Palette; SegmentForeground = $SegmentForeground; SegmentBackground = $SegmentBackground; ParentForeground = $ParentForeground; ParentBackground = $ParentBackground; ChildBackground = $ChildBackground }
    $pattern = '<([^<>/]*)>(.*?)</[^<>]*>'
    $position = 0
    foreach ($match in [regex]::Matches($source, $pattern)) {
        if ($match.Index -gt $position) {
            $out.Add((New-WinToolPreviewSegment -Text $source.Substring($position, $match.Index - $position) -Foreground $Foreground -Background $Background))
        }
        $spec = $match.Groups[1].Value
        $inner = $match.Groups[2].Value
        $fg = $Foreground
        $bg = $Background
        if ($spec -notmatch '^(b|i|u|s|d|f|r|blink|reverse|dimmed)$') {
            $pair = $spec.Split(",")
            if ($pair.Count -ge 1 -and -not [string]::IsNullOrWhiteSpace($pair[0])) { $fg = Resolve-WinToolOmpMarkupColor -Value $pair[0] @colors -IsForeground }
            if ($pair.Count -ge 2) { $bg = Resolve-WinToolOmpMarkupColor -Value $pair[1] @colors }
        }
        $out.Add((New-WinToolPreviewSegment -Text $inner -Foreground $fg -Background $bg))
        $position = $match.Index + $match.Length
    }
    if ($position -lt $source.Length) {
        $out.Add((New-WinToolPreviewSegment -Text $source.Substring($position) -Foreground $Foreground -Background $Background))
    }
    # Anything left that still looks like a tag (an unclosed one) is dropped.
    $clean = New-Object System.Collections.Generic.List[object]
    foreach ($piece in $out.ToArray()) {
        $piece.Text = [regex]::Replace([string]$piece.Text, '</?[A-Za-z#][^<>]*>|</>', '')
        if ([string]::IsNullOrEmpty($piece.Text)) { continue }
        $clean.Add($piece)
    }
    return $clean.ToArray()
}
# endregion

# region src/Private/TerminalBanner.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT
# Hide or restore the startup banner in Windows Terminal, shortcuts, Git Bash,
# and WSL. settings.json is patched as JSONC so comments stay in the file.

function Skip-WinToolJsoncTrivia {
    param(
        [string]$Text,
        [int]$Index
    )
    $length = $Text.Length
    while ($Index -lt $length) {
        $char = $Text[$Index]
        if ($char -eq " " -or $char -eq "`t" -or $char -eq "`r" -or $char -eq "`n") {
            $Index++
            continue
        }
        if ($char -eq "/" -and ($Index + 1) -lt $length) {
            $next = $Text[$Index + 1]
            if ($next -eq "/") {
                $Index += 2
                while ($Index -lt $length -and $Text[$Index] -ne "`n") {
                    $Index++
                }
                continue
            }
            if ($next -eq "*") {
                $Index += 2
                while (($Index + 1) -lt $length -and -not ($Text[$Index] -eq "*" -and $Text[$Index + 1] -eq "/")) {
                    $Index++
                }
                if (($Index + 1) -lt $length) {
                    $Index += 2
                }
                else {
                    $Index = $length
                }
                continue
            }
        }
        break
    }
    return $Index
}

function Get-WinToolJsoncStringSpan {
    param(
        [string]$Text,
        [int]$Index
    )
    if ($Index -ge $Text.Length -or $Text[$Index] -ne '"') {
        return $null
    }
    $builder = New-Object System.Text.StringBuilder
    $escape = $false
    $cursor = $Index + 1
    $length = $Text.Length
    while ($cursor -lt $length) {
        $char = $Text[$cursor]
        if ($escape) {
            switch ($char) {
                "n" { [void]$builder.Append("`n") }
                "r" { [void]$builder.Append("`r") }
                "t" { [void]$builder.Append("`t") }
                default { [void]$builder.Append($char) }
            }
            $escape = $false
            $cursor++
            continue
        }
        if ($char -eq "\") {
            $escape = $true
            $cursor++
            continue
        }
        if ($char -eq '"') {
            return [pscustomobject]@{ Start = $Index; End = ($cursor + 1); Value = $builder.ToString() }
        }
        [void]$builder.Append($char)
        $cursor++
    }
    return $null
}

function Get-WinToolJsoncMatchEnd {
    param(
        [string]$Text,
        [int]$Index
    )
    if ($Index -ge $Text.Length) {
        return -1
    }
    $open = $Text[$Index]
    if ($open -ne "{" -and $open -ne "[") {
        return -1
    }
    $depth = 1
    $cursor = $Index + 1
    $length = $Text.Length
    while ($cursor -lt $length) {
        $cursor = Skip-WinToolJsoncTrivia -Text $Text -Index $cursor
        if ($cursor -ge $length) {
            break
        }
        $char = $Text[$cursor]
        if ($char -eq '"') {
            $span = Get-WinToolJsoncStringSpan -Text $Text -Index $cursor
            if ($null -eq $span) {
                break
            }
            $cursor = [int]$span.End
            continue
        }
        if ($char -eq "{" -or $char -eq "[") {
            $depth++
            $cursor++
            continue
        }
        if ($char -eq "}" -or $char -eq "]") {
            $depth--
            $cursor++
            if ($depth -eq 0) {
                return $cursor
            }
            continue
        }
        $cursor++
    }
    return -1
}

function Get-WinToolJsoncValueSpan {
    param(
        [string]$Text,
        [int]$Index
    )
    $Index = Skip-WinToolJsoncTrivia -Text $Text -Index $Index
    if ($Index -ge $Text.Length) {
        return $null
    }
    $char = $Text[$Index]
    if ($char -eq '"') {
        $span = Get-WinToolJsoncStringSpan -Text $Text -Index $Index
        if ($null -eq $span) {
            return $null
        }
        return [pscustomobject]@{ Start = $span.Start; End = $span.End; Kind = "string"; Value = $span.Value }
    }
    if ($char -eq "{" -or $char -eq "[") {
        $end = Get-WinToolJsoncMatchEnd -Text $Text -Index $Index
        if ($end -lt 0) {
            return $null
        }
        $kind = "object"
        if ($char -eq "[") {
            $kind = "array"
        }
        return [pscustomobject]@{ Start = $Index; End = $end; Kind = $kind; Value = $null }
    }
    $cursor = $Index
    while ($cursor -lt $Text.Length) {
        $char = $Text[$cursor]
        if ($char -eq "," -or $char -eq "}" -or $char -eq "]" -or $char -eq " " -or $char -eq "`t" -or $char -eq "`r" -or $char -eq "`n" -or $char -eq "/") {
            break
        }
        $cursor++
    }
    return [pscustomobject]@{ Start = $Index; End = $cursor; Kind = "primitive"; Value = $Text.Substring($Index, $cursor - $Index) }
}

function Get-WinToolJsoncObjectMap {
    param(
        [string]$Text,
        [int]$Start
    )
    if ($Start -ge $Text.Length -or $Text[$Start] -ne "{") {
        return $null
    }
    $end = Get-WinToolJsoncMatchEnd -Text $Text -Index $Start
    if ($end -lt 0) {
        return $null
    }
    $properties = New-Object System.Collections.Generic.List[object]
    $cursor = Skip-WinToolJsoncTrivia -Text $Text -Index ($Start + 1)
    while ($cursor -lt ($end - 1)) {
        if ($Text[$cursor] -eq "}") {
            break
        }
        if ($Text[$cursor] -ne '"') {
            break
        }
        $name = Get-WinToolJsoncStringSpan -Text $Text -Index $cursor
        if ($null -eq $name) {
            break
        }
        $cursor = Skip-WinToolJsoncTrivia -Text $Text -Index ([int]$name.End)
        if ($cursor -ge $Text.Length -or $Text[$cursor] -ne ":") {
            break
        }
        $value = Get-WinToolJsoncValueSpan -Text $Text -Index ($cursor + 1)
        if ($null -eq $value) {
            break
        }
        $properties.Add([pscustomobject]@{
            Name       = [string]$name.Value
            NameStart  = [int]$name.Start
            ValueStart = [int]$value.Start
            ValueEnd   = [int]$value.End
            Kind       = [string]$value.Kind
            Value      = $value.Value
        }) | Out-Null
        $cursor = Skip-WinToolJsoncTrivia -Text $Text -Index ([int]$value.End)
        if ($cursor -lt $Text.Length -and $Text[$cursor] -eq ",") {
            $cursor = Skip-WinToolJsoncTrivia -Text $Text -Index ($cursor + 1)
        }
    }
    return [pscustomobject]@{ Start = $Start; End = $end; Property = $properties.ToArray() }
}

function Get-WinToolJsoncObjectList {
    param(
        [string]$Text
    )
    $list = New-Object System.Collections.Generic.List[object]
    $cursor = 0
    $length = $Text.Length
    while ($cursor -lt $length) {
        $cursor = Skip-WinToolJsoncTrivia -Text $Text -Index $cursor
        if ($cursor -ge $length) {
            break
        }
        $char = $Text[$cursor]
        if ($char -eq '"') {
            $span = Get-WinToolJsoncStringSpan -Text $Text -Index $cursor
            if ($null -eq $span) {
                break
            }
            $cursor = [int]$span.End
            continue
        }
        if ($char -eq "{") {
            $object = Get-WinToolJsoncObjectMap -Text $Text -Start $cursor
            if ($null -ne $object) {
                $list.Add($object) | Out-Null
            }
            $cursor++
            continue
        }
        $cursor++
    }
    return $list.ToArray()
}

function Get-WinToolJsoncProperty {
    param(
        $Object,
        [string]$Name
    )
    if ($null -eq $Object) {
        return $null
    }
    foreach ($property in @($Object.Property)) {
        if ([string]$property.Name -eq $Name) {
            return $property
        }
    }
    return $null
}

function Get-WinToolJsoncObjectIndent {
    param(
        [string]$Text,
        $Object
    )
    $start = [int]$Object.Start
    $lineStart = $start
    while ($lineStart -gt 0 -and $Text[$lineStart - 1] -ne "`n") {
        $lineStart--
    }
    $pad = ""
    $cursor = $lineStart
    while ($cursor -lt $start -and ($Text[$cursor] -eq " " -or $Text[$cursor] -eq "`t")) {
        $pad += $Text[$cursor]
        $cursor++
    }
    $properties = @($Object.Property)
    if ($properties.Count -gt 0) {
        $nameStart = [int]$properties[0].NameStart
        $propLine = $nameStart
        while ($propLine -gt 0 -and $Text[$propLine - 1] -ne "`n") {
            $propLine--
        }
        $sameLine = $true
        $probe = $start + 1
        while ($probe -lt $nameStart) {
            if ($Text[$probe] -eq "`n") {
                $sameLine = $false
                break
            }
            $probe++
        }
        if (-not $sameLine) {
            $inner = ""
            $cursor = $propLine
            while ($cursor -lt $nameStart -and ($Text[$cursor] -eq " " -or $Text[$cursor] -eq "`t")) {
                $inner += $Text[$cursor]
                $cursor++
            }
            if (-not [string]::IsNullOrEmpty($inner)) {
                return $inner
            }
        }
    }
    return $pad + "  "
}

function Test-WinToolJsoncObjectIsCompact {
    param(
        [string]$Text,
        $Object
    )
    $properties = @($Object.Property)
    if ($properties.Count -eq 0) {
        return $true
    }
    $probe = [int]$Object.Start + 1
    $nameStart = [int]$properties[0].NameStart
    while ($probe -lt $nameStart) {
        if ($Text[$probe] -eq "`n") {
            return $false
        }
        $probe++
    }
    return $true
}

function Set-WinToolJsoncObjectString {
    param(
        [string]$Text,
        $Object,
        [string]$Name,
        [string]$Value
    )
    $encoded = ConvertTo-WinToolJsonString -Text $Value
    $property = Get-WinToolJsoncProperty -Object $Object -Name $Name
    if ($null -ne $property) {
        return $Text.Substring(0, [int]$property.ValueStart) + $encoded + $Text.Substring([int]$property.ValueEnd)
    }
    $afterOpen = [int]$Object.Start + 1
    $next = Skip-WinToolJsoncTrivia -Text $Text -Index $afterOpen
    $hasSibling = ($next -lt [int]$Object.End -and $Text[$next] -ne "}")
    if (Test-WinToolJsoncObjectIsCompact -Text $Text -Object $Object) {
        $insert = " " + (ConvertTo-WinToolJsonString -Text $Name) + ": " + $encoded
        if ($hasSibling) {
            $insert += ","
            if ($afterOpen -lt $Text.Length -and $Text[$afterOpen] -ne " " -and $Text[$afterOpen] -ne "`n" -and $Text[$afterOpen] -ne "`r") {
                $insert += " "
            }
        }
        return $Text.Substring(0, $afterOpen) + $insert + $Text.Substring($afterOpen)
    }
    $indent = Get-WinToolJsoncObjectIndent -Text $Text -Object $Object
    $insert = "`n" + $indent + (ConvertTo-WinToolJsonString -Text $Name) + ": " + $encoded
    if ($hasSibling) {
        $insert += ","
    }
    return $Text.Substring(0, $afterOpen) + $insert + $Text.Substring($afterOpen)
}

function Get-WinToolJsoncLiteralText {
    param(
        $Value,
        [string]$Kind = "string"
    )
    if ($Kind -eq "string") {
        return (ConvertTo-WinToolJsonString -Text ([string]$Value))
    }
    if ($Kind -eq "number") {
        if ($null -eq $Value) {
            return "0"
        }
        return ([string]$Value)
    }
    if ($Kind -eq "boolean") {
        if ($Value) { return "true" }
        return "false"
    }
    if ($Kind -eq "object") {
        if ([string]::IsNullOrWhiteSpace([string]$Value)) { return "{}" }
        return [string]$Value
    }
    if ($Kind -eq "array") {
        if ([string]::IsNullOrWhiteSpace([string]$Value)) { return "[]" }
        return [string]$Value
    }
    return [string]$Value
}

function Set-WinToolJsoncObjectLiteral {
    param(
        [string]$Text,
        $Object,
        [string]$Name,
        [string]$Literal
    )
    $property = Get-WinToolJsoncProperty -Object $Object -Name $Name
    if ($null -ne $property) {
        return $Text.Substring(0, [int]$property.ValueStart) + $Literal + $Text.Substring([int]$property.ValueEnd)
    }
    $afterOpen = [int]$Object.Start + 1
    $next = Skip-WinToolJsoncTrivia -Text $Text -Index $afterOpen
    $hasSibling = ($next -lt [int]$Object.End -and $Text[$next] -ne "}")
    if (Test-WinToolJsoncObjectIsCompact -Text $Text -Object $Object) {
        $insert = " " + (ConvertTo-WinToolJsonString -Text $Name) + ": " + $Literal
        if ($hasSibling) {
            $insert += ","
            if ($afterOpen -lt $Text.Length -and $Text[$afterOpen] -ne " " -and $Text[$afterOpen] -ne "`n" -and $Text[$afterOpen] -ne "`r") {
                $insert += " "
            }
        }
        return $Text.Substring(0, $afterOpen) + $insert + $Text.Substring($afterOpen)
    }
    $indent = Get-WinToolJsoncObjectIndent -Text $Text -Object $Object
    $insert = "`n" + $indent + (ConvertTo-WinToolJsonString -Text $Name) + ": " + $Literal
    if ($hasSibling) {
        $insert += ","
    }
    return $Text.Substring(0, $afterOpen) + $insert + $Text.Substring($afterOpen)
}

function Get-WinToolJsoncRootStart {
    param(
        [Parameter(Mandatory = $true)][string]$Text
    )
    $span = Get-WinToolJsoncValueSpan -Text $Text -Start 0
    if ($null -eq $span -or [string]$span.Kind -ne "object") {
        return $null
    }
    return [int]$span.Start
}

function Set-WinToolJsoncPath {
    param(
        [Parameter(Mandatory = $true)][string]$Text,
        [Parameter(Mandatory = $true)][string[]]$Name,
        $Value,
        [string]$Kind = "string"
    )
    $names = @($Name)
    if ($names.Count -lt 1) {
        throw (Get-WinToolText "msg.a-settings-path-needs-at-least-one-name")
    }
    $literal = Get-WinToolJsoncLiteralText -Value $Value -Kind $Kind
    $guard = 0
    while ($guard -lt 20) {
        $guard++
        $root = Get-WinToolJsoncRootStart -Text $Text
        if ($null -eq $root) {
            throw (Get-WinToolText "msg.the-settings-file-has-no-json-object-at-the-root")
        }
        $start = [int]$root
        $created = $false
        for ($index = 0; $index -lt ($names.Count - 1); $index++) {
            $map = Get-WinToolJsoncObjectMap -Text $Text -Start $start
            if ($null -eq $map) {
                throw (Get-WinToolText "msg.the-settings-file-is-not-a-valid-json-object")
            }
            $property = Get-WinToolJsoncProperty -Object $map -Name $names[$index]
            if ($null -eq $property) {
                $Text = Set-WinToolJsoncObjectLiteral -Text $Text -Object $map -Name $names[$index] -Literal "{}"
                $created = $true
                break
            }
            if ([string]$property.Kind -ne "object") {
                throw ((Get-WinToolText "msg.the-settings-property-n-is-not-an-object") -f $names[$index])
            }
            $start = [int]$property.ValueStart
        }
        if ($created) {
            continue
        }
        $map = Get-WinToolJsoncObjectMap -Text $Text -Start $start
        $existing = Get-WinToolJsoncProperty -Object $map -Name $names[$names.Count - 1]
        if ($null -ne $existing) {
            $current = $Text.Substring([int]$existing.ValueStart, ([int]$existing.ValueEnd - [int]$existing.ValueStart))
            if ($current.Trim() -eq $literal) {
                return [pscustomobject]@{ Text = $Text; Changed = $false }
            }
        }
        $Text = Set-WinToolJsoncObjectLiteral -Text $Text -Object $map -Name $names[$names.Count - 1] -Literal $literal
        return [pscustomobject]@{ Text = $Text; Changed = $true }
    }
    throw (Get-WinToolText "msg.could-not-write-the-settings-path")
}

function Get-WinToolJsoncArrayItem {
    param(
        [Parameter(Mandatory = $true)][string]$Text,
        [Parameter(Mandatory = $true)][int]$Start
    )
    $items = New-Object System.Collections.Generic.List[object]
    if ($Start -ge $Text.Length -or $Text[$Start] -ne "[") {
        return $items.ToArray()
    }
    $end = Get-WinToolJsoncMatchEnd -Text $Text -Index $Start
    if ($end -lt 0) {
        return $items.ToArray()
    }
    $cursor = Skip-WinToolJsoncTrivia -Text $Text -Index ($Start + 1)
    while ($cursor -lt ($end - 1)) {
        if ($Text[$cursor] -eq "]") {
            break
        }
        $value = Get-WinToolJsoncValueSpan -Text $Text -Index $cursor
        if ($null -eq $value) {
            break
        }
        $items.Add($value) | Out-Null
        $cursor = Skip-WinToolJsoncTrivia -Text $Text -Index ([int]$value.End)
        if ($cursor -lt $Text.Length -and $Text[$cursor] -eq ",") {
            $cursor = Skip-WinToolJsoncTrivia -Text $Text -Index ($cursor + 1)
        }
    }
    return $items.ToArray()
}

function Add-WinToolJsoncArrayItem {
    param(
        [Parameter(Mandatory = $true)][string]$Text,
        [Parameter(Mandatory = $true)][int]$Start,
        [Parameter(Mandatory = $true)][string]$Item
    )
    if ($Start -ge $Text.Length -or $Text[$Start] -ne "[") {
        throw (Get-WinToolText "msg.the-settings-path-is-not-a-json-array")
    }
    $end = Get-WinToolJsoncMatchEnd -Text $Text -Index $Start
    if ($end -lt 0) {
        throw (Get-WinToolText "msg.the-json-array-is-not-closed")
    }
    $close = $end - 1
    $items = @(Get-WinToolJsoncArrayItem -Text $Text -Start $Start)
    $closeLine = $Text.LastIndexOf("`n", $close)
    $closeIndent = ""
    if ($closeLine -ge 0) {
        $pad = $closeLine + 1
        while ($pad -lt $close -and ($Text[$pad] -eq " " -or $Text[$pad] -eq "`t")) {
            $closeIndent += $Text[$pad]
            $pad++
        }
    }
    $itemIndent = $closeIndent + "    "
    if ($items.Count -gt 0) {
        $first = $items[0]
        $line = $Text.LastIndexOf("`n", [int]$first.Start)
        if ($line -ge 0 -and $line -lt [int]$first.Start) {
            $itemIndent = $Text.Substring($line + 1, ([int]$first.Start - ($line + 1)))
        }
        $last = $items[$items.Count - 1]
        $insert = "," + "`n" + $itemIndent + $Item
        return $Text.Substring(0, [int]$last.End) + $insert + $Text.Substring([int]$last.End)
    }
    $trim = $close
    while ($trim -gt $Start -and ($Text[$trim - 1] -eq " " -or $Text[$trim - 1] -eq "`t")) {
        $trim--
    }
    $insert = $itemIndent + $Item + "`n" + $closeIndent
    if ($trim -eq $Start + 1) {
        $insert = "`n" + $insert
    }
    return $Text.Substring(0, $trim) + $insert + $Text.Substring($close)
}

function ConvertTo-WinToolJsoncCompactObject {
    param(
        [Parameter(Mandatory = $true)]$Field
    )
    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($key in $Field.Keys) {
        $parts.Add((ConvertTo-WinToolJsonString -Text ([string]$key)) + ": " + (ConvertTo-WinToolJsonString -Text ([string]$Field[$key]))) | Out-Null
    }
    return ("{ " + ($parts.ToArray() -join ", ") + " }")
}

function Get-WinToolJsoncSchemeEntry {

    param(
        [Parameter(Mandatory = $true)]$Scheme
    )
    $fields = [ordered]@{
        name = [string]$Scheme.name
        background = [string]$Scheme.background
        foreground = [string]$Scheme.foreground
        cursorColor = [string](Get-WinToolNote -Object $Scheme -Name "cursor" -Default (Get-WinToolNote -Object $Scheme -Name "cursorColor" -Default ""))
        selectionBackground = [string](Get-WinToolNote -Object $Scheme -Name "selection" -Default (Get-WinToolNote -Object $Scheme -Name "selectionBackground" -Default ""))
    }
    $palette = Get-WinToolNote -Object $Scheme -Name "palette"
    foreach ($key in $script:WinToolSchemeColorKeys) {
        $fromScheme = [string](Get-WinToolNote -Object $Scheme -Name $key -Default "")
        $value = $fromScheme
        if ([string]::IsNullOrWhiteSpace($value) -and $null -ne $palette) {
            $value = [string](Get-WinToolNote -Object $palette -Name $key -Default "")
        }
        if ([string]::IsNullOrWhiteSpace($value)) {
            throw (Get-WinToolText "msg.the-color-scheme-n-has-no-n-color" $Scheme.name $key)
        }
        $fields[$key] = $value
    }
    return $fields
}

function Set-WinToolJsoncColorScheme {
    param(
        [Parameter(Mandatory = $true)][string]$Text,
        [Parameter(Mandatory = $true)]$Scheme
    )
    $fields = Get-WinToolJsoncSchemeEntry -Scheme $Scheme
    $changed = $false
    $original = $Text
    $root = Get-WinToolJsoncRootStart -Text $Text
    if ($null -eq $root) {
        throw (Get-WinToolText "msg.the-settings-file-has-no-json-object-at-the-root")
    }
    $map = Get-WinToolJsoncObjectMap -Text $Text -Start ([int]$root)
    $schemes = Get-WinToolJsoncProperty -Object $map -Name "schemes"
    $itemText = ConvertTo-WinToolJsoncCompactObject -Field $fields
    if ($null -eq $schemes) {
        $Text = Set-WinToolJsoncObjectLiteral -Text $Text -Object $map -Name "schemes" -Literal ("[ " + $itemText + " ]")
        $changed = $true
    }
    else {
        if ([string]$schemes.Kind -ne "array") {
            throw (Get-WinToolText "msg.the-settings-property-schemes-is-not-an-array")
        }
        $items = @(Get-WinToolJsoncArrayItem -Text $Text -Start ([int]$schemes.ValueStart))
        $found = $null
        foreach ($item in $items) {
            if ([string]$item.Kind -ne "object") { continue }
            $object = Get-WinToolJsoncObjectMap -Text $Text -Start ([int]$item.Start)
            $nameProperty = Get-WinToolJsoncProperty -Object $object -Name "name"
            if ($null -eq $nameProperty) { continue }
            $nameText = $Text.Substring([int]$nameProperty.ValueStart, ([int]$nameProperty.ValueEnd - [int]$nameProperty.ValueStart)).Trim()
            if ($nameText -eq (ConvertTo-WinToolJsonString -Text ([string]$fields.name))) {
                $found = $object
                break
            }
        }
        if ($null -eq $found) {
            $Text = Add-WinToolJsoncArrayItem -Text $Text -Start ([int]$schemes.ValueStart) -Item $itemText
            $changed = $true
        }
        else {
            foreach ($key in $fields.Keys) {
                $wanted = Get-WinToolJsoncLiteralText -Value $fields[$key] -Kind "string"
                $property = Get-WinToolJsoncProperty -Object $found -Name $key
                if ($null -ne $property) {
                    $current = $Text.Substring([int]$property.ValueStart, ([int]$property.ValueEnd - [int]$property.ValueStart))
                    if ($current.Trim() -eq $wanted) {
                        continue
                    }
                }
                $Text = Set-WinToolJsoncObjectLiteral -Text $Text -Object $found -Name $key -Literal $wanted
                $changed = $true
                $root = Get-WinToolJsoncRootStart -Text $Text
                $map = Get-WinToolJsoncObjectMap -Text $Text -Start ([int]$root)
                $schemes = Get-WinToolJsoncProperty -Object $map -Name "schemes"
                $items = @(Get-WinToolJsoncArrayItem -Text $Text -Start ([int]$schemes.ValueStart))
                $found = $null
                foreach ($item in $items) {
                    if ([string]$item.Kind -ne "object") { continue }
                    $object = Get-WinToolJsoncObjectMap -Text $Text -Start ([int]$item.Start)
                    $nameProperty = Get-WinToolJsoncProperty -Object $object -Name "name"
                    if ($null -eq $nameProperty) { continue }
                    $nameText = $Text.Substring([int]$nameProperty.ValueStart, ([int]$nameProperty.ValueEnd - [int]$nameProperty.ValueStart)).Trim()
                    if ($nameText -eq (ConvertTo-WinToolJsonString -Text ([string]$fields.name))) {
                        $found = $object
                        break
                    }
                }
                if ($null -eq $found) {
                    throw (Get-WinToolText "msg.the-color-scheme-disappeared-while-it-was-being-updated")
                }
            }
        }
    }
    $result = Set-WinToolJsoncPath -Text $Text -Name @("profiles", "defaults", "colorScheme") -Value ([string]$fields.name) -Kind "string"
    if ([bool]$result.Changed) {
        $changed = $true
    }
    $next = [string]$result.Text
    if ($next -eq $original) {
        $changed = $false
    }
    return [pscustomobject]@{ Text = $next; Changed = $changed }
}

function Remove-WinToolJsoncObjectProperty {
    param(
        [string]$Text,
        $Object,
        [string]$Name
    )
    $property = Get-WinToolJsoncProperty -Object $Object -Name $Name
    if ($null -eq $property) {
        return $Text
    }
    $start = [int]$property.NameStart
    $end = [int]$property.ValueEnd
    $before = $start
    while ($before -gt [int]$Object.Start -and ($Text[$before - 1] -eq " " -or $Text[$before - 1] -eq "`t")) {
        $before--
    }
    if ($before -gt [int]$Object.Start -and ($Text[$before - 1] -eq "`n" -or $Text[$before - 1] -eq "`r")) {
        if ($Text[$before - 1] -eq "`n" -and $before -gt ([int]$Object.Start + 1) -and $Text[$before - 2] -eq "`r") {
            $before -= 2
        }
        else {
            $before--
        }
    }
    $after = Skip-WinToolJsoncTrivia -Text $Text -Index $end
    if ($after -lt [int]$Object.End -and $Text[$after] -eq ",") {
        $end = $after + 1
        $start = [int]$property.NameStart
        $before = $start
        while ($before -gt [int]$Object.Start -and ($Text[$before - 1] -eq " " -or $Text[$before - 1] -eq "`t")) {
            $before--
        }
        if ($before -gt [int]$Object.Start -and ($Text[$before - 1] -eq "`n" -or $Text[$before - 1] -eq "`r")) {
            if ($Text[$before - 1] -eq "`n" -and $before -gt ([int]$Object.Start + 1) -and $Text[$before - 2] -eq "`r") {
                $before -= 2
            }
            else {
                $before--
            }
        }
        return $Text.Substring(0, $before) + $Text.Substring($end)
    }
    $comma = $start
    while ($comma -gt [int]$Object.Start -and $Text[$comma - 1] -ne ",") {
        $comma--
    }
    if ($comma -gt [int]$Object.Start -and $Text[$comma - 1] -eq ",") {
        $before = $comma - 1
        while ($before -gt [int]$Object.Start -and ($Text[$before - 1] -eq " " -or $Text[$before - 1] -eq "`t")) {
            $before--
        }
        return $Text.Substring(0, $before) + $Text.Substring($end)
    }
    return $Text.Substring(0, $before) + $Text.Substring($end)
}

function Add-WinToolJsoncListItem {
    param(
        [string]$Text,
        [string]$Source,
        [string]$Commandline
    )
    $objects = @(Get-WinToolJsoncObjectList -Text $Text)
    $arrayStart = -1
    $arrayEnd = -1
    foreach ($object in $objects) {
        $list = Get-WinToolJsoncProperty -Object $object -Name "list"
        if ($null -ne $list -and [string]$list.Kind -eq "array") {
            $arrayStart = [int]$list.ValueStart
            $arrayEnd = [int]$list.ValueEnd
            break
        }
        $profiles = Get-WinToolJsoncProperty -Object $object -Name "profiles"
        if ($null -ne $profiles -and [string]$profiles.Kind -eq "array") {
            $arrayStart = [int]$profiles.ValueStart
            $arrayEnd = [int]$profiles.ValueEnd
            break
        }
    }
    if ($arrayStart -lt 0) {
        return $Text
    }
    $close = $arrayEnd - 1
    $innerStart = Skip-WinToolJsoncTrivia -Text $Text -Index ($arrayStart + 1)
    $empty = ($innerStart -ge $close)
    $indent = "      "
    $item = "{ " + (ConvertTo-WinToolJsonString -Text "source") + ": " + (ConvertTo-WinToolJsonString -Text $Source) + ", " + (ConvertTo-WinToolJsonString -Text "commandline") + ": " + (ConvertTo-WinToolJsonString -Text $Commandline) + " }"
    if ($empty) {
        return $Text.Substring(0, $arrayStart + 1) + "`n" + $indent + $item + "`n    " + $Text.Substring($close)
    }
    $probe = $close
    while ($probe -gt $arrayStart -and ($Text[$probe - 1] -eq " " -or $Text[$probe - 1] -eq "`t" -or $Text[$probe - 1] -eq "`r" -or $Text[$probe - 1] -eq "`n")) {
        $probe--
    }
    $comma = ""
    if ($probe -gt $arrayStart -and $Text[$probe - 1] -ne ",") {
        $comma = ","
    }
    $insert = $comma + "`n" + $indent + $item
    return $Text.Substring(0, $probe) + $insert + $Text.Substring($probe)
}

function Test-WinToolCommandToken {
    param(
        [string]$Commandline,
        [string]$Token
    )
    if ([string]::IsNullOrWhiteSpace($Commandline) -or [string]::IsNullOrWhiteSpace($Token)) {
        return $false
    }
    $pattern = '(?i)(?<=^|\s|")' + [regex]::Escape($Token) + '(?=\s|"|$)'
    return [regex]::IsMatch($Commandline, $pattern)
}

function Add-WinToolCommandToken {
    param(
        [string]$Commandline,
        [string]$Token
    )
    if ([string]::IsNullOrWhiteSpace($Token)) {
        return $Commandline
    }
    if (Test-WinToolCommandToken -Commandline $Commandline -Token $Token) {
        return $Commandline
    }
    $trimmed = ""
    if (-not [string]::IsNullOrWhiteSpace($Commandline)) {
        $trimmed = $Commandline.Trim()
    }
    if ([string]::IsNullOrWhiteSpace($trimmed)) {
        return $Token
    }
    if ($trimmed.StartsWith("-") -or $trimmed.StartsWith("/")) {
        return $Token + " " + $trimmed
    }
    if ($trimmed.StartsWith('"')) {
        $close = $trimmed.IndexOf('"', 1)
        if ($close -gt 0) {
            return ($trimmed.Substring(0, $close + 1) + " " + $Token + $trimmed.Substring($close + 1))
        }
    }
    $space = $trimmed.IndexOf(" ")
    if ($space -lt 0) {
        return $trimmed + " " + $Token
    }
    return $trimmed.Substring(0, $space) + " " + $Token + $trimmed.Substring($space)
}

function Remove-WinToolCommandToken {
    param(
        [string]$Commandline,
        [string]$Token
    )
    if ([string]::IsNullOrWhiteSpace($Commandline) -or -not (Test-WinToolCommandToken -Commandline $Commandline -Token $Token)) {
        return $Commandline
    }
    $updated = [regex]::Replace($Commandline, '(?i)(?<=^|\s|")' + [regex]::Escape($Token) + '(?=\s|"|$)', "")
    return [regex]::Replace($updated.Trim(), " {2,}", " ")
}

function Add-WinToolCmdClearCommand {
    param(
        [string]$Commandline
    )
    $line = $Commandline
    if ([string]::IsNullOrWhiteSpace($line)) {
        $line = "cmd.exe"
    }
    if ($line -match '(?i)/k(\s+"|\s+)cls(\s|&|"|$)') {
        return $line
    }
    if ($line -match '(?i)/(c)(\s|$)') {
        return $line
    }
    if ($line -match '(?i)/k\s*$') {
        return $line.TrimEnd() + " cls"
    }
    if ($line -match '(?i)/k\s+') {
        return [regex]::Replace($line, '(?i)/k\s+', "/k cls & ", 1)
    }
    return $line.TrimEnd() + " /k cls"
}

function Remove-WinToolCmdClearCommand {
    param(
        [string]$Commandline,
        [string]$Previous
    )
    if ($null -ne $Previous) {
        return $Previous
    }
    $line = $Commandline
    if ($line -match '(?i)^(.+?)\s+/k\s+cls$') {
        return $Matches[1]
    }
    if ($line -match '(?i)/k\s+cls\s*&\s*') {
        return [regex]::Replace($line, '(?i)/k\s+cls\s*&\s*', "/k ", 1)
    }
    return $line
}

function Add-WinToolVsDevNoLogo {
    param(
        [string]$Commandline
    )
    if (Test-WinToolCommandToken -Commandline $Commandline -Token "-no_logo") {
        return $Commandline
    }
    if ([string]::IsNullOrWhiteSpace($Commandline)) {
        return $Commandline
    }
    if ($Commandline -match '(?i)VsDevCmd\.bat') {
        return [regex]::Replace($Commandline, '(?i)(VsDevCmd\.bat)', { param($match) $match.Groups[1].Value + " -no_logo" }, 1)
    }
    return $Commandline.TrimEnd() + " -no_logo"
}

function Remove-WinToolVsDevNoLogo {
    param(
        [string]$Commandline,
        [string]$Previous
    )
    if ($null -ne $Previous) {
        return $Previous
    }
    return [regex]::Replace($Commandline, '(?i)\s+-no_logo(?=\s|"|$)', "", 1).Trim()
}

function Test-WinToolHideStartupBanner {
    param(
        $Selection
    )
    $flag = Get-WinToolNote -Object $Selection -Name "hideStartupBanner"
    if ($null -eq $flag) {
        return $true
    }
    return [bool]$flag
}

function Get-WinToolTerminalBannerKind {
    param(
        [string]$Name,
        [string]$Source,
        [string]$Commandline
    )
    $sourceText = [string]$Source
    $line = [string]$Commandline
    $label = [string]$Name
    if ($sourceText -match '(?i)Azure' -or $label -match '(?i)Azure Cloud Shell' -or $line -match '(?i)Azure') {
        return "azure"
    }
    if ($line -match '(?i)powershell_ise\.exe') {
        return "other"
    }
    $vsDev = ($line -match '(?i)VsDevCmd\.bat' -or $line -match '(?i)Enter-VsDevShell' -or $line -match '(?i)Launch-VsDevShell' -or $label -match '(?i)Developer (PowerShell|Command Prompt)')
    $isPwsh = ($line -match '(?i)(^|[\\/ "])pwsh(\.exe)?(\s|"|$)' -or $sourceText -match '(?i)PowershellCore')
    $isPowershell = ($line -match '(?i)(^|[\\/ "])powershell(\.exe)?(\s|"|$)' -or $sourceText -match '(?i)WindowsPowerShell' -or $label -match '(?i)^Windows PowerShell$')
    if ($vsDev -and ($isPwsh -or $isPowershell -or $label -match '(?i)Developer PowerShell')) {
        return "vsdev-ps"
    }
    if ($vsDev) {
        return "vsdev-cmd"
    }
    if ($isPwsh) {
        return "pwsh"
    }
    if ($isPowershell) {
        return "powershell"
    }
    if ($line -match '(?i)(^|[\\/ "])cmd(\.exe)?(\s|"|$)' -or $label -match '(?i)^Command Prompt$') {
        return "cmd"
    }
    if ($line -match '(?i)(git-bash|bash)\.exe' -or $label -match '(?i)Git Bash' -or $sourceText -match '(?i)GitBash') {
        return "gitbash"
    }
    if ($sourceText -match '(?i)\.Wsl$' -or $sourceText -match '(?i)Windows\.Terminal\.Wsl' -or $line -match '(?i)(^|[\\/ "])wsl(\.exe)?(\s|"|$)') {
        return "wsl"
    }
    return "other"
}

function Get-WinToolDefaultBannerCommandline {
    param(
        [string]$Kind,
        [string]$Commandline,
        [string]$Source
    )
    if (-not [string]::IsNullOrWhiteSpace($Commandline)) {
        return $Commandline
    }
    if ($Kind -eq "pwsh" -or $Source -match '(?i)PowershellCore') {
        return "pwsh.exe"
    }
    if ($Kind -eq "powershell" -or $Source -match '(?i)WindowsPowerShell') {
        return "powershell.exe"
    }
    if ($Kind -eq "cmd") {
        return "cmd.exe"
    }
    return $Commandline
}

function Get-WinToolBannerCommandline {
    param(
        [string]$Kind,
        [string]$Commandline,
        [string]$Source
    )
    $line = Get-WinToolDefaultBannerCommandline -Kind $Kind -Commandline $Commandline -Source $Source
    switch ($Kind) {
        "powershell" { return (Add-WinToolCommandToken -Commandline $line -Token "-NoLogo") }
        "pwsh" { return (Add-WinToolCommandToken -Commandline $line -Token "-NoLogo") }
        "vsdev-ps" {
            $updated = Add-WinToolCommandToken -Commandline $line -Token "-NoLogo"
            if ($updated -match '(?i)VsDevCmd\.bat') {
                $updated = Add-WinToolVsDevNoLogo -Commandline $updated
            }
            return $updated
        }
        "cmd" { return (Add-WinToolCmdClearCommand -Commandline $line) }
        "vsdev-cmd" { return (Add-WinToolVsDevNoLogo -Commandline $line) }
        default { return $Commandline }
    }
}

function Restore-WinToolBannerCommandline {
    param(
        [string]$Kind,
        [string]$Commandline,
        [string]$Previous
    )
    if ($null -ne $Previous) {
        return $Previous
    }
    switch ($Kind) {
        "powershell" { return (Remove-WinToolCommandToken -Commandline $Commandline -Token "-NoLogo") }
        "pwsh" { return (Remove-WinToolCommandToken -Commandline $Commandline -Token "-NoLogo") }
        "vsdev-ps" {
            $updated = Remove-WinToolCommandToken -Commandline $Commandline -Token "-NoLogo"
            return (Remove-WinToolVsDevNoLogo -Commandline $updated -Previous $null)
        }
        "cmd" { return (Remove-WinToolCmdClearCommand -Commandline $Commandline -Previous $null) }
        "vsdev-cmd" { return (Remove-WinToolVsDevNoLogo -Commandline $Commandline -Previous $null) }
        default { return $Commandline }
    }
}

function Get-WinToolJsoncProfileMatch {
    param(
        $Object,
        [string]$Guid,
        [string]$Source,
        [string]$Name,
        [string]$Commandline
    )
    $guidValue = Get-WinToolJsoncProperty -Object $Object -Name "guid"
    $sourceValue = Get-WinToolJsoncProperty -Object $Object -Name "source"
    $nameValue = Get-WinToolJsoncProperty -Object $Object -Name "name"
    $commandValue = Get-WinToolJsoncProperty -Object $Object -Name "commandline"
    if ($null -eq $guidValue -and $null -eq $sourceValue -and $null -eq $nameValue -and $null -eq $commandValue) {
        return $false
    }
    if (-not [string]::IsNullOrWhiteSpace($Guid) -and $null -ne $guidValue -and [string]$guidValue.Value -eq $Guid) {
        return $true
    }
    $sourceOk = $true
    if (-not [string]::IsNullOrWhiteSpace($Source)) {
        $sourceOk = ($null -ne $sourceValue -and [string]$sourceValue.Value -eq $Source)
    }
    $nameOk = $true
    if (-not [string]::IsNullOrWhiteSpace($Name)) {
        $nameOk = ($null -ne $nameValue -and [string]$nameValue.Value -eq $Name)
    }
    if ($sourceOk -and $nameOk -and (-not [string]::IsNullOrWhiteSpace($Source) -or -not [string]::IsNullOrWhiteSpace($Name))) {
        if (-not [string]::IsNullOrWhiteSpace($Commandline) -and $null -ne $commandValue -and [string]$commandValue.Value -ne $Commandline) {
            if ([string]::IsNullOrWhiteSpace($Guid) -and [string]::IsNullOrWhiteSpace($Source)) {
                return $false
            }
        }
        return $true
    }
    return $false
}

function Update-WinToolTerminalBannerText {
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Text,
        [switch]$Undo,
        $Change
    )
    $log = New-Object System.Collections.Generic.List[string]
    $changes = New-Object System.Collections.Generic.List[object]
    if ($null -ne $Change) {
        foreach ($item in @($Change)) {
            $changes.Add($item) | Out-Null
        }
    }
    $objects = @(Get-WinToolJsoncObjectList -Text $Text)
    $updated = $Text
    $kindsSeen = @{}
    if ($Undo) {
        $working = $updated
        foreach ($item in $changes) {
            if ([string]$item.Action -eq "add-source") {
                $objects = @(Get-WinToolJsoncObjectList -Text $working)
                foreach ($object in $objects) {
                    $sourceValue = Get-WinToolJsoncProperty -Object $object -Name "source"
                    $commandValue = Get-WinToolJsoncProperty -Object $object -Name "commandline"
                    if ($null -ne $sourceValue -and [string]$sourceValue.Value -eq [string]$item.Source -and $null -ne $commandValue -and [string]$commandValue.Value -eq [string]$item.Current) {
                        $start = [int]$object.Start
                        $end = [int]$object.End
                        $before = $start
                        while ($before -gt 0 -and ($working[$before - 1] -eq " " -or $working[$before - 1] -eq "`t")) {
                            $before--
                        }
                        if ($before -gt 0 -and $working[$before - 1] -eq ",") {
                            $before--
                        }
                        elseif ($end -lt $working.Length) {
                            $after = Skip-WinToolJsoncTrivia -Text $working -Index $end
                            if ($after -lt $working.Length -and $working[$after] -eq ",") {
                                $end = $after + 1
                            }
                        }
                        $working = $working.Substring(0, $before) + $working.Substring($end)
                        $log.Add("Removed the added " + [string]$item.Source + " profile override.")
                        break
                    }
                }
                continue
            }
            $objects = @(Get-WinToolJsoncObjectList -Text $working)
            foreach ($object in $objects) {
                if (Get-WinToolJsoncProfileMatch -Object $object -Guid ([string]$item.Guid) -Source ([string]$item.Source) -Name ([string]$item.Name) -Commandline ([string]$item.Current)) {
                    if ([bool]$item.AddedCommandline) {
                        $working = Remove-WinToolJsoncObjectProperty -Text $working -Object $object -Name "commandline"
                    }
                    else {
                        $working = Set-WinToolJsoncObjectString -Text $working -Object $object -Name "commandline" -Value ([string]$item.Previous)
                    }
                    $log.Add("Restored the command line for " + $(if ([string]$item.Name) { [string]$item.Name } else { [string]$item.Source }) + ".")
                    break
                }
            }
        }
        return [pscustomobject]@{ Text = $working; Log = $log.ToArray(); Change = @(); Changed = ($working -ne $Text) }
    }

    $pending = New-Object System.Collections.Generic.List[object]
    foreach ($object in $objects) {
        $guidValue = Get-WinToolJsoncProperty -Object $object -Name "guid"
        $sourceValue = Get-WinToolJsoncProperty -Object $object -Name "source"
        $nameValue = Get-WinToolJsoncProperty -Object $object -Name "name"
        $commandValue = Get-WinToolJsoncProperty -Object $object -Name "commandline"
        if ($null -eq $guidValue -and $null -eq $sourceValue -and $null -eq $nameValue -and $null -eq $commandValue) {
            continue
        }
        $guid = ""
        $source = ""
        $name = ""
        $commandline = ""
        if ($null -ne $guidValue) { $guid = [string]$guidValue.Value }
        if ($null -ne $sourceValue) { $source = [string]$sourceValue.Value }
        if ($null -ne $nameValue) { $name = [string]$nameValue.Value }
        if ($null -ne $commandValue) { $commandline = [string]$commandValue.Value }
        $kind = Get-WinToolTerminalBannerKind -Name $name -Source $source -Commandline $commandline
        $kindsSeen[$kind] = $true
        if ($kind -eq "azure") {
            $log.Add("Left Azure Cloud Shell unchanged (it is a remote session).")
            continue
        }
        if ($kind -eq "wsl") {
            $log.Add("Left the " + $(if ($name) { $name } else { "WSL" }) + " profile command line unchanged; the MOTD is hidden with ~/.hushlogin.")
            continue
        }
        if ($kind -eq "gitbash") {
            $log.Add("Left the Git Bash profile command line unchanged; login messages are hidden with a .hushlogin file.")
            continue
        }
        if ($kind -eq "other") {
            $label = $name
            if ([string]::IsNullOrWhiteSpace($label)) { $label = $source }
            if ([string]::IsNullOrWhiteSpace($label)) { $label = $commandline }
            if ([string]::IsNullOrWhiteSpace($label)) { $label = "unnamed profile" }
            $log.Add("Left an unknown Windows Terminal profile unchanged: " + $label + ".")
            continue
        }
        $next = Get-WinToolBannerCommandline -Kind $kind -Commandline $commandline -Source $source
        if ([string]::IsNullOrWhiteSpace($next) -or $next -eq $commandline) {
            continue
        }
        $pending.Add([pscustomobject]@{
            Object           = $object
            Action           = "set-commandline"
            Guid             = $guid
            Source           = $source
            Name             = $name
            Kind             = $kind
            Previous         = $commandline
            Current          = $next
            AddedCommandline = ($null -eq $commandValue)
        }) | Out-Null
    }
    $working = $updated
    $ordered = @($pending | Sort-Object { [int]$_.Object.Start } -Descending)
    foreach ($item in $ordered) {
        $working = Set-WinToolJsoncObjectString -Text $working -Object $item.Object -Name "commandline" -Value ([string]$item.Current)
        $changes.Add([pscustomobject]@{
            Action           = $item.Action
            Guid             = $item.Guid
            Source           = $item.Source
            Name             = $item.Name
            Kind             = $item.Kind
            Previous         = $item.Previous
            Current          = $item.Current
            AddedCommandline = $item.AddedCommandline
        }) | Out-Null
        $log.Add("Hid the startup banner for " + $(if ([string]$item.Name) { [string]$item.Name } else { [string]$item.Kind }) + ".")
    }

    $needPwsh = -not $kindsSeen.ContainsKey("pwsh")
    $needWindows = -not $kindsSeen.ContainsKey("powershell")
    if ($needPwsh) {
        $command = Get-WinToolBannerCommandline -Kind "pwsh" -Commandline "" -Source "Windows.Terminal.PowershellCore"
        $working = Add-WinToolJsoncListItem -Text $working -Source "Windows.Terminal.PowershellCore" -Commandline $command
        $changes.Add([pscustomobject]@{ Action = "add-source"; Source = "Windows.Terminal.PowershellCore"; Current = $command; Kind = "pwsh" }) | Out-Null
        $log.Add("Added a PowerShell 7 profile override with -NoLogo.")
    }
    if ($needWindows) {
        $command = Get-WinToolBannerCommandline -Kind "powershell" -Commandline "" -Source "Windows.Terminal.WindowsPowerShell"
        $working = Add-WinToolJsoncListItem -Text $working -Source "Windows.Terminal.WindowsPowerShell" -Commandline $command
        $changes.Add([pscustomobject]@{ Action = "add-source"; Source = "Windows.Terminal.WindowsPowerShell"; Current = $command; Kind = "powershell" }) | Out-Null
        $log.Add("Added a Windows PowerShell profile override with -NoLogo.")
    }
    return [pscustomobject]@{ Text = $working; Log = $log.ToArray(); Change = $changes.ToArray(); Changed = ($working -ne $Text) }
}

function Get-WinToolTerminalSettingsCandidate {
    $local = [string]$env:LOCALAPPDATA
    if ([string]::IsNullOrWhiteSpace($local)) {
        return @()
    }
    $packages = Join-Path $local "Packages"
    return @(
        (Join-Path $packages "Microsoft.WindowsTerminal_8wekyb3d8bbwe\LocalState\settings.json"),
        (Join-Path $packages "Microsoft.WindowsTerminalPreview_8wekyb3d8bbwe\LocalState\settings.json"),
        (Join-Path $packages "Microsoft.WindowsTerminalCanary_8wekyb3d8bbwe\LocalState\settings.json"),
        (Join-Path $local "Microsoft\Windows Terminal\settings.json")
    )
}

function Get-WinToolTerminalSettingsPathList {
    $paths = New-Object System.Collections.Generic.List[string]
    foreach ($path in @(Get-WinToolTerminalSettingsCandidate)) {
        if (-not [string]::IsNullOrWhiteSpace($path) -and (Test-Path -LiteralPath $path)) {
            $paths.Add($path) | Out-Null
        }
    }
    return $paths.ToArray()
}

function Get-WinToolBannerStatePath {
    param(
        [string]$Path
    )
    if (-not [string]::IsNullOrWhiteSpace($Path)) {
        return $Path
    }
    $root = [string]$env:LOCALAPPDATA
    if ([string]::IsNullOrWhiteSpace($root)) {
        $root = [string]$env:TEMP
    }
    return (Join-Path $root "WinTool\banner-state.json")
}

function Read-WinToolBannerState {
    param(
        [string]$Path
    )
    $file = Get-WinToolBannerStatePath -Path $Path
    if ([string]::IsNullOrWhiteSpace($file) -or -not (Test-Path -LiteralPath $file)) {
        return [pscustomobject]@{ files = @(); shortcuts = @(); hushlogin = $null }
    }
    try {
        $raw = [System.IO.File]::ReadAllText($file)
        if ([string]::IsNullOrWhiteSpace($raw)) {
            return [pscustomobject]@{ files = @(); shortcuts = @(); hushlogin = $null }
        }
        return (ConvertFrom-WinToolJsonText -Text $raw)
    }
    catch {
        return [pscustomobject]@{ files = @(); shortcuts = @(); hushlogin = $null }
    }
}

function Write-WinToolBannerState {
    param(
        $State,
        [string]$Path
    )
    $file = Get-WinToolBannerStatePath -Path $Path
    $directory = Split-Path -Parent $file
    if (-not (Test-Path -LiteralPath $directory)) {
        New-Item -ItemType Directory -Path $directory -Force | Out-Null
    }
    Write-WinToolUtf8File -Path $file -Text ((ConvertTo-WinToolJsonText -Value $State) + "`n")
}

function Get-WinToolShortcutBannerKind {
    param(
        [string]$TargetPath,
        [string]$Arguments
    )
    $file = ""
    if (-not [string]::IsNullOrWhiteSpace($TargetPath)) {
        $file = [System.IO.Path]::GetFileName($TargetPath)
    }
    $argsText = [string]$Arguments
    if ($file -match '(?i)^powershell_ise\.exe$') {
        return "other"
    }
    if ($argsText -match '(?i)VsDevCmd\.bat' -or $argsText -match '(?i)Enter-VsDevShell') {
        if ($file -match '(?i)^(powershell|pwsh)\.exe$') {
            return "vsdev-ps"
        }
        return "vsdev-cmd"
    }
    if ($file -match '(?i)^pwsh\.exe$') {
        return "pwsh"
    }
    if ($file -match '(?i)^powershell\.exe$') {
        return "powershell"
    }
    if ($file -match '(?i)^cmd\.exe$') {
        return "cmd"
    }
    if ($file -match '(?i)^(bash|git-bash)\.exe$') {
        return "gitbash"
    }
    return "other"
}

function Get-WinToolShortcutBannerArgument {
    param(
        [string]$Kind,
        [string]$Arguments
    )
    switch ($Kind) {
        "powershell" { return (Add-WinToolCommandToken -Commandline $Arguments -Token "-NoLogo") }
        "pwsh" { return (Add-WinToolCommandToken -Commandline $Arguments -Token "-NoLogo") }
        "vsdev-ps" { return (Add-WinToolCommandToken -Commandline $Arguments -Token "-NoLogo") }
        "cmd" {
            $line = "cmd.exe"
            if (-not [string]::IsNullOrWhiteSpace($Arguments)) {
                $line = "cmd.exe " + $Arguments
            }
            $updated = Add-WinToolCmdClearCommand -Commandline $line
            if ($updated.StartsWith("cmd.exe ", [System.StringComparison]::OrdinalIgnoreCase)) {
                return $updated.Substring(8)
            }
            if ($updated -eq "cmd.exe") {
                return ""
            }
            return $updated
        }
        "vsdev-cmd" { return (Add-WinToolVsDevNoLogo -Commandline $Arguments) }
        default { return $null }
    }
}

function Set-WinToolUserHushlogin {
    param(
        [string]$HomePath,
        [switch]$Undo,
        [bool]$Created
    )
    $result = [pscustomobject]@{ Changed = $false; Created = $false; Existed = $false; Path = $null }
    if ([string]::IsNullOrWhiteSpace($HomePath) -or -not (Test-Path -LiteralPath $HomePath)) {
        return $result
    }
    $file = Join-Path $HomePath ".hushlogin"
    $result.Path = $file
    if ($Undo) {
        if ($Created -and (Test-Path -LiteralPath $file)) {
            Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue
            $result.Changed = $true
        }
        return $result
    }
    if (Test-Path -LiteralPath $file) {
        $result.Existed = $true
        return $result
    }
    New-Item -ItemType File -Path $file -Force | Out-Null
    $result.Changed = $true
    $result.Created = $true
    return $result
}

function Get-WinToolWslDistroNameList {
    $names = New-Object System.Collections.Generic.List[string]
    $wsl = $null
    if (-not [string]::IsNullOrWhiteSpace($env:SystemRoot)) {
        $wsl = Join-Path $env:SystemRoot "System32\wsl.exe"
    }
    if ([string]::IsNullOrWhiteSpace($wsl) -or -not (Test-Path -LiteralPath $wsl)) {
        return @()
    }
    try {
        $env:WSL_UTF8 = "1"
        $output = & $wsl -l -q 2>$null
        foreach ($line in @($output)) {
            $name = ([string]$line).Replace([string][char]0, "").Trim()
            if (-not [string]::IsNullOrWhiteSpace($name) -and $name -notmatch '(?i)docker') {
                $names.Add($name) | Out-Null
            }
        }
    }
    catch {
        return @()
    }
    return $names.ToArray()
}

function Set-WinToolWslHushlogin {
    param(
        [string]$Distro,
        [switch]$Undo
    )
    $wsl = $null
    if (-not [string]::IsNullOrWhiteSpace($env:SystemRoot)) {
        $wsl = Join-Path $env:SystemRoot "System32\wsl.exe"
    }
    if ([string]::IsNullOrWhiteSpace($wsl) -or -not (Test-Path -LiteralPath $wsl)) {
        return $false
    }
    if ($Undo) {
        $script = 'if [ -f "$HOME/.config/wintool/created-hushlogin" ]; then rm -f "$HOME/.hushlogin" "$HOME/.config/wintool/created-hushlogin"; fi'
        & $wsl -d $Distro -- bash -lc $script 2>$null | Out-Null
        return $true
    }
    $script = 'if [ ! -e "$HOME/.hushlogin" ]; then mkdir -p "$HOME/.config/wintool" && touch "$HOME/.hushlogin" && printf "created\n" > "$HOME/.config/wintool/created-hushlogin"; fi'
    & $wsl -d $Distro -- bash -lc $script 2>$null | Out-Null
    return $true
}

function Invoke-WinToolTerminalBanner {
    param(
        [switch]$Undo,
        [string[]]$SettingsPath,
        [string]$StatePath,
        [string]$HomePath,
        [string]$StartMenuPath,
        [switch]$SkipShortcuts,
        [switch]$SkipWsl
    )
    $stateFile = Get-WinToolBannerStatePath -Path $StatePath
    $state = Read-WinToolBannerState -Path $stateFile
    if ($null -eq (Get-WinToolNote -Object $state -Name "files")) {
        $state | Add-Member -NotePropertyName "files" -NotePropertyValue @() -Force
    }
    $paths = @($SettingsPath)
    if ($paths.Count -eq 0 -or ([string]::IsNullOrWhiteSpace($paths[0]) -and $paths.Count -eq 1)) {
        $paths = @(Get-WinToolTerminalSettingsPathList)
    }
    foreach ($path in $paths) {
        if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path)) {
            if (-not [string]::IsNullOrWhiteSpace($path)) {
                Write-WinToolLog -Message (Get-WinToolText "msg.windows-terminal-settings-were-not-found-at-n" $path) -Level "info"
            }
            continue
        }
        Backup-WinToolTerminalSetting -Path $path
        $raw = [System.IO.File]::ReadAllText($path)
        $change = @()
        $kept = New-Object System.Collections.Generic.List[object]
        foreach ($item in @(Get-WinToolNote -Object $state -Name "files" -Default @())) {
            if ([string](Get-WinToolNote -Object $item -Name "path") -eq $path) {
                $change = @(Get-WinToolNote -Object $item -Name "change" -Default @())
            }
            else {
                $kept.Add($item) | Out-Null
            }
        }
        $result = Update-WinToolTerminalBannerText -Text $raw -Undo:$Undo -Change $change
        foreach ($line in @($result.Log)) {
            Write-WinToolLog -Message $line -Level "info"
        }
        if ([bool]$result.Changed) {
            Write-WinToolUtf8File -Path $path -Text ([string]$result.Text)
        }
        if ($Undo) {
            $state | Add-Member -NotePropertyName "files" -NotePropertyValue $kept.ToArray() -Force
        }
        elseif ([bool]$result.Changed) {
            $kept.Add([pscustomobject]@{ path = $path; change = @($result.Change) }) | Out-Null
            $state | Add-Member -NotePropertyName "files" -NotePropertyValue $kept.ToArray() -Force
        }
    }

    $profileHome = $HomePath
    if ([string]::IsNullOrWhiteSpace($profileHome)) {
        $profileHome = [string]$env:USERPROFILE
        if ([string]::IsNullOrWhiteSpace($profileHome)) {
            $profileHome = [string]$env:HOME
        }
    }
    $hushState = Get-WinToolNote -Object $state -Name "hushlogin"
    $createdWindows = $false
    if ($null -ne $hushState) {
        $createdWindows = [bool](Get-WinToolNote -Object $hushState -Name "windowsCreated" -Default $false)
    }
    $hush = Set-WinToolUserHushlogin -HomePath $profileHome -Undo:$Undo -Created $createdWindows
    if ($hush.Created) {
        Write-WinToolLog -Message (Get-WinToolText "msg.created-n-hushlogin-to-hide-git-bash-login-messages" $profileHome) -Level "ok"
        $createdWindows = $true
    }
    elseif ($Undo -and $hush.Changed) {
        Write-WinToolLog -Message (Get-WinToolText "msg.removed-the-hushlogin-file-wintool-created-in-n" $profileHome) -Level "ok"
        $createdWindows = $false
    }
    elseif ($hush.Existed -and -not $Undo) {
        Write-WinToolLog -Message (Get-WinToolText "msg.left-an-existing-n-hushlogin-in-place" $profileHome) -Level "info"
    }

    $wslCreated = New-Object System.Collections.Generic.List[string]
    if ($null -ne $hushState) {
        foreach ($name in @(Get-WinToolNote -Object $hushState -Name "wsl" -Default @())) {
            if (-not [string]::IsNullOrWhiteSpace([string]$name)) {
                $wslCreated.Add([string]$name) | Out-Null
            }
        }
    }
    if (-not $SkipWsl) {
        if ($Undo) {
            foreach ($distro in @($wslCreated)) {
                if (Set-WinToolWslHushlogin -Distro $distro -Undo) {
                    Write-WinToolLog -Message (Get-WinToolText "msg.removed-the-hushlogin-file-wintool-created-in-n-2" $distro) -Level "ok"
                }
            }
            $wslCreated = New-Object System.Collections.Generic.List[string]
        }
        else {
            foreach ($distro in @(Get-WinToolWslDistroNameList)) {
                if (Set-WinToolWslHushlogin -Distro $distro) {
                    Write-WinToolLog -Message (Get-WinToolText "msg.hid-the-login-message-in-n-with-hushlogin" $distro) -Level "ok"
                    if (-not ($wslCreated -contains $distro)) {
                        $wslCreated.Add($distro) | Out-Null
                    }
                }
            }
        }
    }

    $shortcutEntries = New-Object System.Collections.Generic.List[object]
    if (-not $SkipShortcuts) {
        $menu = $StartMenuPath
        if ([string]::IsNullOrWhiteSpace($menu)) {
            $appData = [string]$env:APPDATA
            if (-not [string]::IsNullOrWhiteSpace($appData)) {
                $menu = Join-Path $appData "Microsoft\Windows\Start Menu\Programs"
            }
        }
        if ($Undo) {
            foreach ($item in @(Get-WinToolNote -Object $state -Name "shortcuts" -Default @())) {
                $shortcutEntries.Add($item) | Out-Null
            }
            if ($env:OS -eq "Windows_NT" -and $shortcutEntries.Count -gt 0) {
                try {
                    $shell = New-Object -ComObject WScript.Shell
                    foreach ($item in $shortcutEntries) {
                        $linkPath = [string](Get-WinToolNote -Object $item -Name "path")
                        if ([string]::IsNullOrWhiteSpace($linkPath) -or -not (Test-Path -LiteralPath $linkPath)) {
                            continue
                        }
                        $link = $shell.CreateShortcut($linkPath)
                        $link.Arguments = [string](Get-WinToolNote -Object $item -Name "previous" -Default "")
                        $link.Save()
                        Write-WinToolLog -Message (Get-WinToolText "msg.restored-start-menu-shortcut-arguments-for-n" ([System.IO.Path]::GetFileName($linkPath))) -Level "ok"
                    }
                }
                catch {
                    Write-WinToolLog -Message (Get-WinToolText "msg.start-menu-shortcuts-could-not-be-restored-n" $($_.Exception.Message)) -Level "warn"
                }
            }
            $shortcutEntries = New-Object System.Collections.Generic.List[object]
        }
        elseif ($env:OS -eq "Windows_NT" -and -not [string]::IsNullOrWhiteSpace($menu) -and (Test-Path -LiteralPath $menu)) {
            try {
                $shell = New-Object -ComObject WScript.Shell
                foreach ($file in @(Get-ChildItem -LiteralPath $menu -Filter "*.lnk" -Recurse -File -ErrorAction SilentlyContinue)) {
                    $link = $shell.CreateShortcut($file.FullName)
                    $kind = Get-WinToolShortcutBannerKind -TargetPath ([string]$link.TargetPath) -Arguments ([string]$link.Arguments)
                    if ($kind -eq "other" -or $kind -eq "gitbash" -or $kind -eq "wsl" -or $kind -eq "azure") {
                        if ($kind -eq "other") {
                            Write-WinToolLog -Message (Get-WinToolText "msg.left-start-menu-shortcut-unchanged-n" $file.Name) -Level "info"
                        }
                        continue
                    }
                    $previous = [string]$link.Arguments
                    $next = Get-WinToolShortcutBannerArgument -Kind $kind -Arguments $previous
                    if ($null -eq $next -or $next -eq $previous) {
                        continue
                    }
                    $link.Arguments = $next
                    $link.Save()
                    $shortcutEntries.Add([pscustomobject]@{ path = $file.FullName; previous = $previous; current = $next; kind = $kind }) | Out-Null
                    Write-WinToolLog -Message (Get-WinToolText "msg.hid-the-startup-banner-in-start-menu-shortcut-n" $file.Name) -Level "ok"
                }
            }
            catch {
                Write-WinToolLog -Message (Get-WinToolText "msg.start-menu-shortcuts-were-left-unchanged-n" $($_.Exception.Message)) -Level "warn"
            }
        }
        elseif ($env:OS -ne "Windows_NT") {
            Write-WinToolLog -Message (Get-WinToolText "msg.start-menu-shortcuts-are-only-updated-on-windows") -Level "info"
        }
    }

    $state | Add-Member -NotePropertyName "hushlogin" -NotePropertyValue ([pscustomobject]@{ windowsCreated = $createdWindows; wsl = $wslCreated.ToArray() }) -Force
    $state | Add-Member -NotePropertyName "shortcuts" -NotePropertyValue $shortcutEntries.ToArray() -Force
    Write-WinToolBannerState -State $state -Path $stateFile
}

function Get-WinToolTerminalBannerStep {
    param(
        [switch]$Undo
    )
    if ($Undo) {
        return [pscustomobject]@{ Type = "banner"; Label = (Get-WinToolText "msg.show-the-startup-banner-in-terminals-again"); Undo = $true }
    }
    return [pscustomobject]@{ Type = "banner"; Label = (Get-WinToolText "msg.hide-the-startup-banner-in-terminals"); Undo = $false }
}

function Invoke-WinToolTerminalBannerStep {
    param(
        $Step
    )
    $undo = [bool](Get-WinToolNote -Object $Step -Name "Undo" -Default $false)
    Invoke-WinToolTerminalBanner -Undo:$undo
}
# endregion

# region src/Private/PackageCache.ps1
# Copyright (c) 2026 Henrique
# SPDX-License-Identifier: MIT

# Cached view of what is already on the PC: winget packages (from the
# Install view's background export), modules in the usual 5.1 and pwsh
# folders, fonts from the resolver map, and saved Oh My Posh themes.
# The Terminal click path only reads this cache.

$script:WinToolPackageCache = $null
$script:WinToolConfigNeedCache = $null
$script:WinToolMinimumModuleVersion = @{
    "PSReadLine" = "2.2.0"
}

function New-WinToolIdSet {
    param(
        [string[]]$Id = @()
    )
    $set = @{}
    foreach ($item in @($Id)) {
        if ([string]::IsNullOrWhiteSpace($item)) { continue }
        $set[$item.ToLowerInvariant()] = $true
    }
    return $set
}

function New-WinToolPackageCache {
    return [pscustomobject]@{
        WingetReady = $false
        InstalledId = (New-WinToolIdSet)
        UpdateId    = (New-WinToolIdSet)
        Module      = @{}
        Theme       = @{}
        Font        = @{}
    }
}

function Get-WinToolPackageCache {
    if ($null -eq $script:WinToolPackageCache) {
        $script:WinToolPackageCache = New-WinToolPackageCache
    }
    return $script:WinToolPackageCache
}

function Reset-WinToolPackageCache {
    $script:WinToolPackageCache = New-WinToolPackageCache
    $script:WinToolConfigNeedCache = $null
    return $script:WinToolPackageCache
}

function Set-WinToolWingetPackageCache {
    param(
        [string[]]$InstalledId = @(),
        [string[]]$UpdateId = @()
    )
    $cache = Get-WinToolPackageCache
    $cache.InstalledId = New-WinToolIdSet -Id $InstalledId
    $cache.UpdateId = New-WinToolIdSet -Id $UpdateId
    $cache.WingetReady = $true
    return $cache
}

function Get-WinToolDefaultModuleRoot {
    $roots = New-Object System.Collections.Generic.List[object]
    $docs = [Environment]::GetFolderPath("MyDocuments")
    if (-not [string]::IsNullOrWhiteSpace($docs)) {
        $roots.Add([pscustomobject]@{ Host = "powershell"; Path = (Join-Path $docs "WindowsPowerShell\Modules") }) | Out-Null
        $roots.Add([pscustomobject]@{ Host = "pwsh"; Path = (Join-Path $docs "PowerShell\Modules") }) | Out-Null
    }
    if (-not [string]::IsNullOrWhiteSpace($env:SystemRoot)) {
        $roots.Add([pscustomobject]@{ Host = "powershell"; Path = (Join-Path $env:SystemRoot "System32\WindowsPowerShell\v1.0\Modules") }) | Out-Null
        $roots.Add([pscustomobject]@{ Host = "powershell"; Path = (Join-Path $env:SystemRoot "SysWOW64\WindowsPowerShell\v1.0\Modules") }) | Out-Null
    }
    $programFiles = [Environment]::GetFolderPath("ProgramFiles")
    if (-not [string]::IsNullOrWhiteSpace($programFiles)) {
        $roots.Add([pscustomobject]@{ Host = "powershell"; Path = (Join-Path $programFiles "WindowsPowerShell\Modules") }) | Out-Null
        $roots.Add([pscustomobject]@{ Host = "pwsh"; Path = (Join-Path $programFiles "PowerShell\7\Modules") }) | Out-Null
        $roots.Add([pscustomobject]@{ Host = "pwsh"; Path = (Join-Path $programFiles "PowerShell\Modules") }) | Out-Null
    }
    $programFilesX86 = ${env:ProgramFiles(x86)}
    if (-not [string]::IsNullOrWhiteSpace($programFilesX86)) {
        $roots.Add([pscustomobject]@{ Host = "powershell"; Path = (Join-Path $programFilesX86 "WindowsPowerShell\Modules") }) | Out-Null
    }
    return $roots.ToArray()
}

function ConvertTo-WinToolModuleVersion {
    param(
        [string]$Text
    )
    $raw = [string]$Text
    if ([string]::IsNullOrWhiteSpace($raw)) {
        return [version]"0.0.0"
    }
    $trimmed = $raw.Trim().Trim("'", '"')
    $parts = New-Object System.Collections.Generic.List[string]
    foreach ($piece in @($trimmed.Split("."))) {
        if ($piece -match '^[0-9]+$') {
            $parts.Add($piece) | Out-Null
        }
        else {
            break
        }
    }
    if ($parts.Count -eq 0) {
        return [version]"0.0.0"
    }
    while ($parts.Count -lt 2) {
        $parts.Add("0") | Out-Null
    }
    try {
        return [version]($parts.ToArray() -join ".")
    }
    catch {
        return [version]"0.0.0"
    }
}

function Get-WinToolModuleFolderVersion {
    param(
        [Parameter(Mandatory = $true)][string]$Path
    )
    $highest = [version]"0.0.0"
    $found = $false
    if (-not (Test-Path -LiteralPath $Path)) {
        return $null
    }
    $manifests = @(Get-ChildItem -LiteralPath $Path -Filter "*.psd1" -File -ErrorAction SilentlyContinue)
    if ($manifests.Count -eq 0) {
        $manifests = @(Get-ChildItem -LiteralPath $Path -Filter "*.psd1" -File -Recurse -Depth 2 -ErrorAction SilentlyContinue)
    }
    foreach ($manifest in $manifests) {
        $found = $true
        try {
            $text = [System.IO.File]::ReadAllText($manifest.FullName)
            if ($text -match "(?im)ModuleVersion\s*=\s*['`"]?([0-9][0-9.]*)") {
                $version = ConvertTo-WinToolModuleVersion -Text $Matches[1]
                if ($version -gt $highest) { $highest = $version }
            }
        }
        catch {
            $null = $_.Exception.Message
        }
    }
    $children = @(Get-ChildItem -LiteralPath $Path -Directory -ErrorAction SilentlyContinue)
    foreach ($child in $children) {
        $version = ConvertTo-WinToolModuleVersion -Text $child.Name
        if ($version -gt [version]"0.0.0") {
            $found = $true
            if ($version -gt $highest) { $highest = $version }
        }
        $scriptFiles = @(Get-ChildItem -LiteralPath $child.FullName -Include "*.psd1", "*.psm1" -File -ErrorAction SilentlyContinue)
        if ($scriptFiles.Count -gt 0) {
            $found = $true
        }
    }
    $rootScripts = @(Get-ChildItem -LiteralPath $Path -Include "*.psm1", "*.psd1" -File -ErrorAction SilentlyContinue)
    if ($rootScripts.Count -gt 0) {
        $found = $true
    }
    if (-not $found) {
        return $null
    }
    return $highest
}

function Get-WinToolModuleCacheKey {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        [Parameter(Mandatory = $true)][string]$HostName
    )
    return ($HostName.ToLowerInvariant() + "|" + $Name.ToLowerInvariant())
}

function Update-WinToolLocalPackageCache {
    param(
        [object[]]$ModuleRoot,
        [string]$ThemeFolder
    )
    $cache = Get-WinToolPackageCache
    $roots = @($ModuleRoot)
    if ($roots.Count -eq 0) {
        $roots = @(Get-WinToolDefaultModuleRoot)
    }
    $modules = @{}
    foreach ($root in $roots) {
        $hostName = [string](Get-WinToolNote -Object $root -Name "Host" -Default "powershell")
        $path = [string](Get-WinToolNote -Object $root -Name "Path" -Default "")
        if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path)) {
            continue
        }
        $folders = @(Get-ChildItem -LiteralPath $path -Directory -ErrorAction SilentlyContinue)
        foreach ($folder in $folders) {
            $version = Get-WinToolModuleFolderVersion -Path $folder.FullName
            if ($null -eq $version) { continue }
            $key = Get-WinToolModuleCacheKey -Name $folder.Name -HostName $hostName
            if ($modules.ContainsKey($key)) {
                $current = ConvertTo-WinToolModuleVersion -Text ([string]$modules[$key])
                if ($version -gt $current) {
                    $modules[$key] = [string]$version
                }
            }
            else {
                $modules[$key] = [string]$version
            }
        }
    }
    $cache.Module = $modules

    $themes = @{}
    $themePath = $ThemeFolder
    if ([string]::IsNullOrWhiteSpace($themePath) -and -not [string]::IsNullOrWhiteSpace($env:LOCALAPPDATA)) {
        $themePath = Join-Path $env:LOCALAPPDATA "WinTool\themes"
    }
    if (-not [string]::IsNullOrWhiteSpace($themePath) -and (Test-Path -LiteralPath $themePath)) {
        foreach ($file in @(Get-ChildItem -LiteralPath $themePath -File -ErrorAction SilentlyContinue)) {
            $themes[$file.Name.ToLowerInvariant()] = $true
        }
    }
    $cache.Theme = $themes
    $script:WinToolConfigNeedCache = $null
    return $cache
}

function Test-WinToolCachedWingetId {
    param(
        [Parameter(Mandatory = $true)][string]$Id,
        $Cache
    )
    if ($null -eq $Cache -or -not [bool]$Cache.WingetReady) {
        return $false
    }
    return $Cache.InstalledId.ContainsKey($Id.ToLowerInvariant())
}

function Test-WinToolCachedWingetUpgrade {
    param(
        [Parameter(Mandatory = $true)][string]$Id,
        $Cache
    )
    if ($null -eq $Cache -or -not [bool]$Cache.WingetReady) {
        return $false
    }
    return $Cache.UpdateId.ContainsKey($Id.ToLowerInvariant())
}

function Test-WinToolCachedModule {
    param(
        [Parameter(Mandatory = $true)][string]$Name,
        [string]$HostName = "powershell",
        $Cache,
        [string]$MinimumVersion
    )
    if ($null -eq $Cache) {
        $Cache = Get-WinToolPackageCache
    }
    $key = Get-WinToolModuleCacheKey -Name $Name -HostName $HostName
    if (-not $Cache.Module.ContainsKey($key)) {
        return $false
    }
    $minimum = $MinimumVersion
    if ([string]::IsNullOrWhiteSpace($minimum) -and $script:WinToolMinimumModuleVersion.ContainsKey($Name)) {
        $minimum = [string]$script:WinToolMinimumModuleVersion[$Name]
    }
    if ([string]::IsNullOrWhiteSpace($minimum)) {
        return $true
    }
    $have = ConvertTo-WinToolModuleVersion -Text ([string]$Cache.Module[$key])
    $need = ConvertTo-WinToolModuleVersion -Text $minimum
    return ($have -ge $need)
}

function Test-WinToolCachedTheme {
    param(
        [Parameter(Mandatory = $true)][string]$FileName,
        $Cache
    )
    if ($null -eq $Cache) {
        $Cache = Get-WinToolPackageCache
    }
    if ($null -eq $Cache.Theme) {
        return $false
    }
    return $Cache.Theme.ContainsKey($FileName.ToLowerInvariant())
}

function Test-WinToolCachedFont {
    param(
        [string]$FontId,
        [string]$Face,
        $Cache
    )
    if ($null -ne $Cache -and $null -ne $Cache.Font) {
        if (-not [string]::IsNullOrWhiteSpace($FontId) -and $Cache.Font.ContainsKey($FontId.ToLowerInvariant())) {
            return [bool]$Cache.Font[$FontId.ToLowerInvariant()]
        }
        if (-not [string]::IsNullOrWhiteSpace($Face) -and $Cache.Font.ContainsKey($Face.ToLowerInvariant())) {
            return [bool]$Cache.Font[$Face.ToLowerInvariant()]
        }
    }
    if (-not [string]::IsNullOrWhiteSpace($FontId)) {
        try {
            return [bool](Test-WinToolFontResolve -FontId $FontId)
        }
        catch {
            return $false
        }
    }
    return $false
}

function Get-WinToolStepPackageId {
    param($Step)
    $id = [string](Get-WinToolNote -Object $Step -Name "Id" -Default "")
    if ([string]::IsNullOrWhiteSpace($id)) {
        $id = [string](Get-WinToolNote -Object $Step -Name "WingetId" -Default "")
    }
    return $id
}

function Get-WinToolStepChipName {
    param($Step)
    $type = [string]$Step.Type
    $label = [string]$Step.Label
    if ($type -eq "winget" -or $type -eq "font-download") {
        if ($label -match '^(Install|Download|Upgrade|Update)\s+(.+)$') {
            return $Matches[2]
        }
        return $label
    }
    if ($type -eq "module") {
        if ($label -match '^(Install|Update)\s+') {
            return ($label -replace '^(Install|Update)\s+', '')
        }
        return $label
    }
    if ($type -eq "font") {
        $text = "Terminal font"
        if ($null -ne $Step.PSObject.Properties["Size"] -and [int]$Step.Size -ne 12) {
            $text += " " + [int]$Step.Size + " pt"
        }
        return $text
    }
    if ($type -eq "ligatures") { return (Get-WinToolText "msg.font-ligatures-on") }
    if ($type -eq "scheme") { return ($label -replace '^Set the Windows Terminal color scheme to ', 'Scheme ') }
    if ($type -eq "banner") {
        if ([bool](Get-WinToolNote -Object $Step -Name "Undo" -Default $false)) { return (Get-WinToolText "msg.startup-banner-shown") }
        return (Get-WinToolText "msg.startup-banner-hidden")
    }
    if ($type -eq "profile") { return (Get-WinToolText "msg.powershell-profile") }
    if ($type -eq "starship-preset") { return $label }
    return $label
}

function Get-WinToolPlanStepDecision {
    param(
        [Parameter(Mandatory = $true)]$Step,
        $Cache,
        [switch]$Update
    )
    if ($null -eq $Cache) {
        $Cache = Get-WinToolPackageCache
    }
    $type = [string]$Step.Type
    if ($type -eq "winget") {
        $id = Get-WinToolStepPackageId -Step $Step
        $ready = [bool]$Cache.WingetReady
        $present = $false
        if ($ready -and -not [string]::IsNullOrWhiteSpace($id)) {
            $present = Test-WinToolCachedWingetId -Id $id -Cache $Cache
        }
        if ($ready -and $present) {
            if ($Update) {
                $upgradable = Test-WinToolCachedWingetUpgrade -Id $id -Cache $Cache
                if ($upgradable) {
                    return [pscustomobject]@{ Run = $true; Action = "upgrade"; Outcome = "update"; Reason = "upgrade available" }
                }
                return [pscustomobject]@{ Run = $false; Action = "install"; Outcome = "already-had"; Reason = "already installed" }
            }
            return [pscustomobject]@{ Run = $false; Action = "install"; Outcome = "already-had"; Reason = "already installed" }
        }
        return [pscustomobject]@{ Run = $true; Action = "install"; Outcome = "install"; Reason = "missing" }
    }
    if ($type -eq "font-download") {
        $fontId = [string](Get-WinToolNote -Object $Step -Name "FontId" -Default "")
        $face = [string](Get-WinToolNote -Object $Step -Name "Face" -Default "")
        if (Test-WinToolCachedFont -FontId $fontId -Face $face -Cache $Cache) {
            return [pscustomobject]@{ Run = $false; Action = ""; Outcome = "already-had"; Reason = "font installed" }
        }
        return [pscustomobject]@{ Run = $true; Action = ""; Outcome = "install"; Reason = "missing" }
    }
    if ($type -eq "module") {
        $name = [string](Get-WinToolNote -Object $Step -Name "Name" -Default "")
        if ([string]::IsNullOrWhiteSpace($name)) {
            $name = [string](Get-WinToolNote -Object $Step -Name "Module" -Default "")
        }
        if ([string]::IsNullOrWhiteSpace($name) -and [string]$Step.Label -match '^(Install|Update) (.+?) for ') {
            $name = $Matches[2]
        }
        $hostName = [string](Get-WinToolNote -Object $Step -Name "Host" -Default "powershell")
        if (Test-WinToolCachedModule -Name $name -HostName $hostName -Cache $Cache) {
            if ($Update) {
                return [pscustomobject]@{ Run = $true; Action = ""; Outcome = "update"; Reason = "update module" }
            }
            return [pscustomobject]@{ Run = $false; Action = ""; Outcome = "already-had"; Reason = "module installed" }
        }
        return [pscustomobject]@{ Run = $true; Action = ""; Outcome = "install"; Reason = "missing" }
    }
    if ($type -eq "profile") {
        return [pscustomobject]@{ Run = $true; Action = ""; Outcome = "config"; Reason = "profile"; RefreshTheme = [bool]$Update }
    }
    return [pscustomobject]@{ Run = $true; Action = ""; Outcome = "config"; Reason = $type; RefreshTheme = $false }
}

function New-WinToolPlanTally {
    return [pscustomobject]@{
        Installed       = New-Object System.Collections.Generic.List[string]
        AlreadyHad      = New-Object System.Collections.Generic.List[string]
        Updated         = New-Object System.Collections.Generic.List[string]
        ConfigChanged   = New-Object System.Collections.Generic.List[string]
        ConfigUnchanged = New-Object System.Collections.Generic.List[string]
        Failed          = New-Object System.Collections.Generic.List[string]
    }
}

function Add-WinToolPlanTally {
    param(
        [Parameter(Mandatory = $true)]$Tally,
        [Parameter(Mandatory = $true)][string]$Bucket,
        [Parameter(Mandatory = $true)][string]$Name
    )
    $target = $null
    switch ($Bucket) {
        "Installed" { $target = $Tally.Installed }
        "AlreadyHad" { $target = $Tally.AlreadyHad }
        "Updated" { $target = $Tally.Updated }
        "ConfigChanged" { $target = $Tally.ConfigChanged }
        "ConfigUnchanged" { $target = $Tally.ConfigUnchanged }
        "Failed" { $target = $Tally.Failed }
        default { return }
    }
    if ($target.Contains($Name)) {
        return
    }
    $target.Add($Name) | Out-Null
}

function Join-WinToolNameList {
    param(
        [string[]]$Name
    )
    $items = @($Name | Where-Object { -not [string]::IsNullOrWhiteSpace($_) })
    if ($items.Count -eq 0) { return "" }
    if ($items.Count -eq 1) { return [string]$items[0] }
    if ($items.Count -eq 2) { return ([string]$items[0] + " and " + [string]$items[1]) }
    $head = $items[0..($items.Count - 2)] -join ", "
    return ($head + ", and " + [string]$items[$items.Count - 1])
}

function Format-WinToolPlanSummary {
    param(
        [Parameter(Mandatory = $true)]$Tally
    )
    $parts = New-Object System.Collections.Generic.List[string]
    if ($Tally.Installed.Count -gt 0) {
        $parts.Add("Installed " + (Join-WinToolNameList -Name $Tally.Installed.ToArray()) + ".") | Out-Null
    }
    if ($Tally.AlreadyHad.Count -gt 0) {
        $parts.Add("Already had " + (Join-WinToolNameList -Name $Tally.AlreadyHad.ToArray()) + ".") | Out-Null
    }
    if ($Tally.Updated.Count -gt 0) {
        $parts.Add("Updated " + (Join-WinToolNameList -Name $Tally.Updated.ToArray()) + ".") | Out-Null
    }
    if ($Tally.ConfigChanged.Count -gt 0) {
        $parts.Add("Updated settings: " + (Join-WinToolNameList -Name $Tally.ConfigChanged.ToArray()) + ".") | Out-Null
    }
    if ($Tally.ConfigUnchanged.Count -gt 0) {
        $parts.Add("Already set " + (Join-WinToolNameList -Name $Tally.ConfigUnchanged.ToArray()) + ".") | Out-Null
    }
    if ($Tally.Failed.Count -gt 0) {
        $parts.Add("Failed: " + (Join-WinToolNameList -Name $Tally.Failed.ToArray()) + ".") | Out-Null
    }
    if ($parts.Count -eq 0) {
        return (Get-WinToolText "msg.nothing-to-do")
    }
    return ($parts.ToArray() -join " ")
}

function Get-WinToolOutcomeBucket {
    param(
        [string]$Outcome
    )
    switch ($Outcome) {
        "install" { return "Installed" }
        "already-had" { return "AlreadyHad" }
        "update" { return "Updated" }
        "config-changed" { return "ConfigChanged" }
        "config-unchanged" { return "ConfigUnchanged" }
        "failed" { return "Failed" }
        default { return "" }
    }
}

function Select-WinToolInstallApp {
    param(
        $App,
        [bool]$Detected
    )
    $pending = New-Object System.Collections.Generic.List[object]
    $already = New-Object System.Collections.Generic.List[object]
    foreach ($item in @($App)) {
        $installed = $false
        if ($Detected) {
            $installed = [bool](Get-WinToolNote -Object $item -Name "Installed" -Default $false)
        }
        if ($installed) {
            $already.Add($item) | Out-Null
        }
        else {
            $pending.Add($item) | Out-Null
        }
    }
    return [pscustomobject]@{
        Pending = $pending.ToArray()
        Already = $already.ToArray()
    }
}

function Test-WinToolSettingsFontMatch {
    param(
        $Settings,
        [string]$Face,
        [int]$Size
    )
    $profiles = Get-WinToolNote -Object $Settings -Name "profiles"
    $defaults = Get-WinToolNote -Object $profiles -Name "defaults"
    $font = Get-WinToolNote -Object $defaults -Name "font"
    $currentFace = [string](Get-WinToolNote -Object $font -Name "face" -Default (Get-WinToolNote -Object $defaults -Name "fontFace" -Default ""))
    $currentSize = Get-WinToolNote -Object $font -Name "size"
    if ([string]$currentFace -ne [string]$Face) {
        return $false
    }
    if ($null -eq $currentSize) {
        return ($Size -eq 12)
    }
    return ([int]$currentSize -eq [int]$Size)
}

function Test-WinToolFontFeatureEnabled {
    param($Font)
    $features = Get-WinToolNote -Object $Font -Name "features"
    if ($null -eq $features) { return $false }
    foreach ($key in $script:WinToolLigatureFeatures.Keys) {
        $value = Get-WinToolNote -Object $features -Name $key
        if ($null -eq $value -or [int]$value -ne [int]$script:WinToolLigatureFeatures[$key]) {
            return $false
        }
    }
    return $true
}

function Test-WinToolSettingsLigatureMatch {
    param($Settings)
    $profiles = Get-WinToolNote -Object $Settings -Name "profiles"
    $defaults = Get-WinToolNote -Object $profiles -Name "defaults"
    $font = Get-WinToolNote -Object $defaults -Name "font"
    if (-not (Test-WinToolFontFeatureEnabled -Font $font)) {
        return $false
    }
    foreach ($item in @(Get-WinToolNote -Object $profiles -Name "list" -Default @())) {
        if ($null -eq $item) { continue }
        $own = Get-WinToolNote -Object $item -Name "font"
        if ($null -eq $own -or $null -eq (Get-WinToolNote -Object $own -Name "features")) { continue }
        if (-not (Test-WinToolFontFeatureEnabled -Font $own)) {
            return $false
        }
    }
    return $true
}

function Test-WinToolSettingsSchemeMatch {
    param(
        $Settings,
        $Scheme
    )
    $fields = Get-WinToolJsoncSchemeEntry -Scheme $Scheme
    $profiles = Get-WinToolNote -Object $Settings -Name "profiles"
    $defaults = Get-WinToolNote -Object $profiles -Name "defaults"
    $current = [string](Get-WinToolNote -Object $defaults -Name "colorScheme" -Default "")
    if ($current -ne [string]$fields.name) {
        return $false
    }
    $entries = @(Get-WinToolNote -Object $Settings -Name "schemes" -Default @())
    foreach ($entry in $entries) {
        if ([string](Get-WinToolNote -Object $entry -Name "name" -Default "") -ne [string]$fields.name) {
            continue
        }
        foreach ($key in $fields.Keys) {
            if ([string](Get-WinToolNote -Object $entry -Name $key -Default "") -ne [string]$fields[$key]) {
                return $false
            }
        }
        return $true
    }
    return $false
}

function Test-WinToolTextNeedsManagedBlock {
    param(
        [string]$Text,
        [string]$Body
    )
    $updated = Update-WinToolManagedBlock -Text $Text -Begin $script:WinToolProfileBegin -End $script:WinToolProfileEnd -Body $Body
    return ($updated -ne $Text)
}

function Get-WinToolTerminalConfigNeed {
    param(
        $Selection,
        [string[]]$SettingsPath,
        [string[]]$ProfilePath,
        [bool]$SkipRead
    )
    $need = @{
        font      = $true
        ligatures = $true
        scheme    = $true
        banner    = $true
        profile   = $true
    }
    if ($SkipRead) {
        return $need
    }
    $paths = @($SettingsPath)
    if ($paths.Count -eq 0) {
        try { $paths = @(Get-WinToolTerminalSettingsPathList) } catch { $paths = @() }
    }
    $face = ""
    $size = 12
    $schemeId = ""
    $hideBanner = $true
    if ($null -ne $Selection) {
        $face = [string](Get-WinToolNote -Object $Selection -Name "fontFace" -Default (Get-WinToolNote -Object $Selection -Name "Face" -Default ""))
        if ([string]::IsNullOrWhiteSpace($face)) {
            $fontId = [string](Get-WinToolNote -Object $Selection -Name "fontId" -Default "")
            if (-not [string]::IsNullOrWhiteSpace($fontId)) {
                try {
                    foreach ($item in @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "fonts" -Default @())) {
                        if ([string]$item.id -eq $fontId) {
                            $face = [string]$item.face
                            break
                        }
                    }
                }
                catch {
                    $face = $face
                }
            }
        }
        $sizeValue = Get-WinToolNote -Object $Selection -Name "fontSize"
        if ($null -ne $sizeValue) { $size = [int]$sizeValue }
        $schemeId = [string](Get-WinToolNote -Object $Selection -Name "schemeId" -Default "")
        $hideValue = Get-WinToolNote -Object $Selection -Name "hideStartupBanner"
        if ($null -ne $hideValue) { $hideBanner = [bool]$hideValue }
    }
    if ($paths.Count -eq 0) {
        return $need
    }
    $fontNeed = $false
    $ligatureNeed = $false
    $schemeNeed = $false
    $scheme = $null
    if (-not [string]::IsNullOrWhiteSpace($schemeId)) {
        try {
            foreach ($item in @(Get-WinToolNote -Object (Get-WinToolTerminalCatalog) -Name "schemes" -Default @())) {
                if ([string]$item.id -eq $schemeId) { $scheme = $item; break }
            }
        }
        catch {
            $scheme = $null
        }
    }
    foreach ($path in $paths) {
        if ([string]::IsNullOrWhiteSpace($path) -or -not (Test-Path -LiteralPath $path)) {
            $fontNeed = $true
            $ligatureNeed = $true
            $schemeNeed = $true
            continue
        }
        try {
            $raw = [System.IO.File]::ReadAllText($path)
            $settings = ConvertFrom-WinToolJsonText -Text $raw
        }
        catch {
            $fontNeed = $true
            $ligatureNeed = $true
            $schemeNeed = $true
            continue
        }
        if (-not [string]::IsNullOrWhiteSpace($face) -and -not (Test-WinToolSettingsFontMatch -Settings $settings -Face $face -Size $size)) {
            $fontNeed = $true
        }
        if (-not (Test-WinToolSettingsLigatureMatch -Settings $settings)) {
            $ligatureNeed = $true
        }
        if ($null -ne $scheme -and -not (Test-WinToolSettingsSchemeMatch -Settings $settings -Scheme $scheme)) {
            $schemeNeed = $true
        }
    }
    $need.font = $fontNeed
    $need.ligatures = $ligatureNeed
    $need.scheme = $schemeNeed
    # Banner and profile stay "needed" unless a later check proves otherwise.
    # Banner apply is already a no-op when nothing would change; the chip
    # still shows a change until that file walk is cheap enough to cache.
    $profiles = @($ProfilePath)
    if ($profiles.Count -eq 0) {
        try {
            $profiles = @(
                (Get-WinToolShellProfilePath -HostName "powershell"),
                (Get-WinToolShellProfilePath -HostName "pwsh")
            )
        }
        catch {
            $profiles = @()
        }
    }
    if ($profiles.Count -gt 0 -and $null -ne $Selection) {
        try {
            $body = Get-WinToolPromptScript -PromptId ([string](Get-WinToolNote -Object $Selection -Name "prompt" -Default "")) -TerminalIcons ([bool](Get-WinToolNote -Object $Selection -Name "terminalIcons" -Default $false)) -PromptStyle ([string](Get-WinToolNote -Object $Selection -Name "promptStyle" -Default "")) -PsReadLine ([bool](Get-WinToolNote -Object $Selection -Name "psReadLine" -Default $false)) -Zoxide ([bool](Get-WinToolNote -Object $Selection -Name "zoxide" -Default $false))
            $profileNeed = $false
            foreach ($path in $profiles) {
                $existing = ""
                if (-not [string]::IsNullOrWhiteSpace($path) -and (Test-Path -LiteralPath $path)) {
                    $existing = [System.IO.File]::ReadAllText($path)
                }
                if (Test-WinToolTextNeedsManagedBlock -Text $existing -Body $body) {
                    $profileNeed = $true
                }
            }
            $need.profile = $profileNeed
        }
        catch {
            $need.profile = $true
        }
    }
    $null = $hideBanner
    return $need
}

function Get-WinToolCachedConfigNeed {
    param($Selection)
    $key = ""
    if ($null -ne $Selection) {
        $key = ([string](Get-WinToolNote -Object $Selection -Name "prompt" -Default "") + "|" + [string](Get-WinToolNote -Object $Selection -Name "promptStyle" -Default "") + "|" + [string](Get-WinToolNote -Object $Selection -Name "fontFace" -Default "") + "|" + [string](Get-WinToolNote -Object $Selection -Name "fontSize" -Default "") + "|" + [string](Get-WinToolNote -Object $Selection -Name "schemeId" -Default "") + "|" + [string](Get-WinToolNote -Object $Selection -Name "terminalIcons" -Default "") + "|" + [string](Get-WinToolNote -Object $Selection -Name "psReadLine" -Default "") + "|" + [string](Get-WinToolNote -Object $Selection -Name "zoxide" -Default "") + "|" + [string](Get-WinToolNote -Object $Selection -Name "hideStartupBanner" -Default ""))
    }
    $stamp = $key
    try {
        foreach ($path in @(Get-WinToolTerminalSettingsPathList)) {
            if (Test-Path -LiteralPath $path) {
                $stamp += "|" + $path + ":" + [string](Get-Item -LiteralPath $path).LastWriteTimeUtc.Ticks
            }
        }
    }
    catch {
        $stamp += "|settings"
    }
    if ($null -ne $script:WinToolConfigNeedCache -and [string]$script:WinToolConfigNeedCache.Stamp -eq $stamp) {
        return $script:WinToolConfigNeedCache.Need
    }
    $need = Get-WinToolTerminalConfigNeed -Selection $Selection
    $script:WinToolConfigNeedCache = [pscustomobject]@{ Stamp = $stamp; Need = $need }
    return $need
}


function Set-WinToolPlanStepDecision {
    param(
        [Parameter(Mandatory = $true)]$Step,
        $Cache,
        [switch]$Update
    )
    $decision = Get-WinToolPlanStepDecision -Step $Step -Cache $Cache -Update:$Update
    if ([bool](Get-WinToolNote -Object $decision -Name "RefreshTheme" -Default $false)) {
        $Step | Add-Member -NotePropertyName "RefreshTheme" -NotePropertyValue $true -Force
    }
    if ([string](Get-WinToolNote -Object $decision -Name "Action" -Default "") -eq "upgrade") {
        $Step | Add-Member -NotePropertyName "Action" -NotePropertyValue "upgrade" -Force
    }
    return $decision
}

function Add-WinToolPlanStepOutcome {
    param(
        [Parameter(Mandatory = $true)]$Tally,
        [Parameter(Mandatory = $true)]$Step,
        [string]$Outcome
    )
    $bucket = Get-WinToolOutcomeBucket -Outcome $Outcome
    if ([string]::IsNullOrWhiteSpace($bucket)) {
        return
    }
    Add-WinToolPlanTally -Tally $Tally -Bucket $bucket -Name (Get-WinToolStepChipName -Step $Step)
}


function Get-WinToolTerminalWingetId {
    $ids = New-Object System.Collections.Generic.List[string]
    try {
        $catalog = Get-WinToolTerminalCatalog
        $components = Get-WinToolNote -Object $catalog -Name "components"
        foreach ($name in @("windowsTerminal", "powerShell")) {
            $id = [string](Get-WinToolNote -Object $components -Name $name -Default "")
            if (-not [string]::IsNullOrWhiteSpace($id)) { $ids.Add($id) | Out-Null }
        }
        foreach ($prompt in @(Get-WinToolNote -Object $catalog -Name "prompts" -Default @())) {
            $id = [string](Get-WinToolNote -Object $prompt -Name "wingetId" -Default "")
            if (-not [string]::IsNullOrWhiteSpace($id)) { $ids.Add($id) | Out-Null }
        }
        foreach ($extra in @(Get-WinToolNote -Object $catalog -Name "extras" -Default @())) {
            $id = [string](Get-WinToolNote -Object $extra -Name "wingetId" -Default "")
            if (-not [string]::IsNullOrWhiteSpace($id)) { $ids.Add($id) | Out-Null }
        }
        foreach ($font in @(Get-WinToolNote -Object $catalog -Name "fonts" -Default @())) {
            $id = [string](Get-WinToolNote -Object $font -Name "wingetId" -Default "")
            if (-not [string]::IsNullOrWhiteSpace($id)) { $ids.Add($id) | Out-Null }
        }
    }
    catch {
        $null = $_.Exception.Message
    }
    return $ids.ToArray()
}
# endregion

